      title: `Early-morning rise of about ${dawnAvg} mg/dL on ${dawnN} mornings`,
      title_ar: `ارتفاع في الصباح الباكر بحوالي ${dawnAvg} في ${dawnN} صباحًا`,
      detail: { mornings: dawnN, average_rise: dawnAvg }, evidence_count: dawnN });
