    if (coalesce(_m12_txt(p_opts, 'writer'), '') === 'caregiver' && _m12_re(v_text, C('third_person')) === true) {
      v_en = C('self_harm_caregiver_en'); v_ar = C('self_harm_caregiver_ar');
    } else {
      v_en = C('self_harm_message_en'); v_ar = C('self_harm_message_ar');
    }
