      v_new = false;
      return { title: nr.title, title_ar: nr.title_ar, body: nr.body, body_ar: nr.body_ar, citations: nr.citations, ai_run_id: nr.ai_run_id };
    } } });
    v_id = row.id;
    if (v_new) {
