      {}, 'account-closed:' + pid);
  } else {
    dbUpdateWhere('caregiver_grants', (g) => g.caregiver_user_id === uid && g.active === true, { active: false, revoked_at: now() });
    dbUpdateWhere('caregiver_invites', (i) => i.used_by === uid && i.used_at === null, { revoked: true });
