          + 'ستحتاج إلى اختيار كلمة مرور جديدة عند تسجيل الدخول. إذا لم تطلب ذلك فأبلغ عيادتك فورًا.'
        : 'Hello ' + u.full_name + ',\n\nAn administrator set a temporary password for your account.\n'
          + 'You will choose a new password when you next sign in. If you did not ask for this, tell your clinic straight away.',
    };
  }
  return { skip: 'unknown_event' };
}

// ---- 19_guidelines.js
// 019 Accredited guideline sources: registry, edition watch, fetched editions, review and approval
// (port of database/migrations/019_fn_guidelines.sql).
// The workflows WF-024 / WF-024b fetch and parse; every decision (is this a new edition, what becomes a draft,
// who is told, what an approval changes) is made here.
//
// Notes on the port:
// - Nothing here searches: the module only counts chunks (`embedding is not null`, `quarantined`) and deletes them.
//   Vector and full-text search stay in 012 (fn_rag_search).
// - A fetched section is stored up to 45,000 characters (the SQL kept 60,000): a Google Sheets cell holds 50,000.
// - `now() - make_interval(days => n)` keeps the Cairo wall-clock time (calendar days, as Postgres in Africa/Cairo);
//   `current_date + make_interval(months => n)` clamps to the end of a shorter month, as Postgres does.
// - ORDER BY s.key compares code units (the database used en_US.utf8; the source keys are lower-case ASCII words).

/* ------------------------------------------------------------------------------------------- private helpers */

function _m19_isObj(v) { return v !== null && typeof v === 'object' && !Array.isArray(v); }
/** jsonb ? 'key' on an object (the key exists, even with a JSON null value). */
function _m19_has(v, key) { return _m19_isObj(v) && Object.prototype.hasOwnProperty.call(v, key) && v[key] !== undefined; }
/** v -> 'key' (null for a missing key or a value that is not an object) */
function _m19_get(v, key) { return _m19_has(v, key) ? v[key] : null; }
/** v ->> 'key' */
function _m19_text(v, key) { return jtext(_m19_get(v, key)); }
/** a || b || ...: NULL when any part is NULL. */
function _m19_cat(...parts) { return parts.some((p) => p === null || p === undefined) ? null : parts.map(String).join(''); }
/** v = any(arr) with SQL NULL semantics: true, false or null. */
function _m19_anyEq(v, arr) {
  if (v === null || v === undefined || !Array.isArray(arr)) return null;
  if (arr.includes(v)) return true;
  return arr.includes(null) ? null : false;
}
/** jsonb_array_length of a value that is not SQL NULL (a JSON null is a scalar). */
function _m19_arrayLength(v) {
  if (Array.isArray(v)) return v.length;
  throw new Error(_m19_isObj(v) ? 'cannot get array length of a non-array' : 'cannot get array length of a scalar');
}
/** jsonb_array_elements of a value that is not SQL NULL. */
function _m19_arrayElements(v) {
  if (Array.isArray(v)) return v;
  throw new Error(_m19_isObj(v) ? 'cannot extract elements from an object' : 'cannot extract elements from a scalar');
}
/** now() - make_interval(days => n): the same Cairo wall-clock time n calendar days earlier. */
function _m19_daysAgo(n) {
  const p = cairoParts(now());
  const d = addDays(`${p.y}-${String(p.mo).padStart(2, '0')}-${String(p.d).padStart(2, '0')}`, -n);
  return iso(cairoLocalToMs(+d.slice(0, 4), +d.slice(5, 7), +d.slice(8, 10), p.h, p.mi, p.s, p.ms));
}
/** (date + make_interval(months => n))::date: the day is clamped to the length of the target month. */
function _m19_addMonths(date, n) {
  if (date === null || date === undefined || n === null || n === undefined) return null;
  const [y, m, d] = String(date).slice(0, 10).split('-').map(Number);
  const total = y * 12 + (m - 1) + Number(n);
  const ny = Math.floor(total / 12), nm = total - ny * 12 + 1;
  const last = new Date(Date.UTC(ny, nm, 0)).getUTCDate();
  return `${String(ny).padStart(4, '0')}-${String(nm).padStart(2, '0')}-${String(Math.min(d, last)).padStart(2, '0')}`;
}
/** s.last_checked_at is null or s.last_checked_at < now() - make_interval(days => s.check_every_days) */
// Due when never checked, when the check period has passed, or, after a failed check, sooner: 1 hour after the first
// failure, then 2, 4, 8 … hours (a network blip does not delay a new edition by a whole period).
function _m19_unchecked(s) {
  if (s.last_checked_at === null) return true;
  if (s.check_every_days !== null && t(s.last_checked_at) < t(_m19_daysAgo(s.check_every_days))) return true;
  const failures = s.last_status === 'error' ? coalesce(castInt(_m19_text(s.last_detail, 'failures')), 1) : 0;
  return failures > 0 && t(s.last_checked_at) + Math.min(2 ** (failures - 1), 24 * 30) * 3600e3 <= t(now());
}
function _m19_source(key) { return key === null || key === undefined ? null : dbGet('guideline_sources', String(key)); }

/* --------------------------------------------------------------------------------------------------- functions */

// Is edition a newer than edition b? Years compare as numbers; anything else (PMC article versions, ETags,
// content hashes) is newer when it differs.
function fn_edition_newer(a, b) {
  if (a === null || a === undefined) return false;
  if (b === null || b === undefined) return true;
  if (/^\d{4}$/.test(String(a)) && /^\d{4}$/.test(String(b))) return Number(a) > Number(b);
  return String(a) !== String(b);
}

function fn_guideline_source_json(s) {
  const pending = dbWhere('rag_documents', (x) => x.source_key === s.key && x.status === 'draft' && s.pending_version !== null
    && x.source_version === s.pending_version);
  return {
    ...cloneValue(omit(s, 'last_detail')),
    last_error: _m19_text(s.last_detail, 'error'),
    last_found: cloneValue(_m19_get(s.last_detail, 'meta')),
    pending_documents: pending.length,
    pending_flagged: pending.filter((x) => ['block', 'suspicious'].includes(_m19_text(x.screening, 'verdict'))).length,
    approved_documents: dbCount('rag_documents', (x) => x.source_key === s.key && x.status === 'approved'),
    open_updates: jsonAgg(orderBy(dbWhere('guideline_updates', (u) => u.source_key === s.key && u.status === 'open'), [(u) => t(u.detected_at), 'desc'])
      .map((u) => ({ id: u.id, version: u.version, detected_at: u.detected_at, items: cloneValue(u.items) }))) ?? [],
    due: s.active === true && _m19_unchecked(s),
  };
}

// Sources due for a check, longest-unchecked first. Empty while the guideline_sync flag is off.
function fn_guideline_sources_due(p_limit = 5) {
  const flag = dbGet('feature_flags', 'guideline_sync');
  if (coalesce(flag ? flag.enabled : null, false) !== true) return [];
  const limit = greatest(1, least(castInt(coalesce(p_limit, 5)), 20));
  const due = dbWhere('guideline_sources', (s) => s.active === true && _m19_unchecked(s));
  return jsonAgg(orderBy(due, [(s) => t(s.last_checked_at), 'asc', 'nulls first']).slice(0, limit).map((s) => ({ key: s.key }))) ?? [];
}

// What the check workflow needs for one source: the registry entry, the editions it must not report again, the
// validators of the last download (ETag, content hash) and the prompt-injection rule for screening fetched text.
function fn_guideline_source_ctx(p_key) {
  const s = _m19_source(p_key);
  if (!s) return fn_raise('not_found: guideline source not found');
  return {
    ...cloneValue(s),
    known_versions: [s.current_version, s.pending_version].filter((v) => v !== null).concat(s.dismissed_versions || []),
    known_etag: _m19_text(s.last_detail, 'etag'),
    known_sha: _m19_text(s.last_detail, 'sha'),
    injection: fn_rule('prompt_injection'),
  };
}

// In-app notification to every active Safety Officer (deduplicated per officer).
function fn_notify_safety_officers(p_kind, p_title, p_body, p_dedupe) {
  let n = 0;
  for (const u of dbWhere('users', (x) => x.role === 'safety_officer' && x.active === true)) {
    const row = dbInsert('notifications', {
      user_id: u.id, kind: p_kind ?? null, title: left(p_title ?? null, 200), body: left(p_body ?? null, 1000),
      dedupe_key: _m19_cat(p_dedupe, ':', u.id),
    }, { onConflict: 'nothing' });
    if (row) n++;
  }
  return n;
}

// Records the result of one source check (WF-024b). p_result:
//   {status: unchanged | fetched | watch | not_licensed | retracted | error, version, etag, sha, error,
//    meta: {title, short_title, edition, citation, journal, pmid, pmcid, doi, url, license, published},
//    sections: [{title, content, screening}]   (fetched)
//    items: [{pmid, pmcid, doi, title, journal, pubdate, url}]   (watch / not_licensed)}
// A fetched edition becomes draft documents (never searchable before approval); a watched edition becomes an open
// review item. Either way every active Safety Officer is notified once. A retracted edition is withdrawn at once.
function fn_guideline_record(p_key, p_result) {
  const s = _m19_source(p_key);
  if (!s) fn_raise('not_found: guideline source not found');
  const key = String(p_key);
  const r = p_result;
  const status = coalesce(nullif(_m19_text(r, 'status'), ''), 'error');
  const version = nullif(_m19_text(r, 'version'), '');
  const meta = _m19_has(r, 'meta') ? r.meta : {};   // coalesce(p_result->'meta', '{}'): a JSON null stays null
  const metaText = (k) => _m19_text(meta, k);
  // Validators of the last successful download survive checks that do not carry them (e.g. "304 Not Modified").
  const detail = {
    ...(_m19_isObj(s.last_detail) ? omit(cloneValue(s.last_detail), 'error', 'failures') : {}),
    ...stripNulls({
      version, etag: _m19_text(r, 'etag'), sha: _m19_text(r, 'sha'),
      meta: _m19_isObj(meta) && Object.keys(meta).length === 0 ? null : cloneValue(meta), checked_at: now(),
    }),
  };
  const isNew = fn_edition_newer(version, s.current_version) && version !== s.pending_version && _m19_anyEq(version, s.dismissed_versions) === false;

  if (status === 'error') {
    dbUpdate('guideline_sources', s, {
      last_checked_at: now(), last_status: 'error',
      last_detail: { ...detail, error: left(coalesce(_m19_text(r, 'error'), 'unknown error'), 500),
        failures: (s.last_status === 'error' ? coalesce(castInt(_m19_text(s.last_detail, 'failures')), 1) : 0) + 1 },
    });
    return { key, status: 'error', error: left(_m19_text(r, 'error'), 500) };
  }

  if (status === 'retracted') {
    const docs = dbWhere('rag_documents', (x) => x.source_key === key && version !== null && x.source_version === version
      && (x.status === 'draft' || x.status === 'approved'));
    for (const x of docs) dbUpdate('rag_documents', x, { status: 'retired' });
    const ids = new Set(docs.map((x) => x.id));
    dbDeleteWhere('rag_chunks', (ch) => ids.has(ch.document_id));
    dbUpdate('guideline_sources', s, {
      last_checked_at: now(), last_status: 'retracted', last_detail: detail,
      pending_version: version !== null && s.pending_version === version ? null : s.pending_version,
      current_version: version !== null && s.current_version === version ? null : s.current_version,
    });
    dbInsert('incidents', {
      workflow: 'WF-024 Guideline sources', node: 'Retraction check',
      message: left(`${s.title ?? ''} edition ${version ?? ''} was marked retracted at the source; ${docs.length} document(s) withdrawn from answers.`, 500),
    });
    fn_notify_safety_officers('guideline', _m19_cat('Guideline edition retracted: ', s.title),
      _m19_cat('The source marks edition ', version, ' as retracted. It was withdrawn from AI answers at once. Review the knowledge base.'),
      _m19_cat('guideline-retracted:', key, ':', version));
    dbInsert('audit_logs', { action: 'guideline.retracted', entity: 'guideline_source', entity_id: key, detail: { version, documents: docs.length } });
    return { key, status: 'retracted', version, withdrawn: docs.length };
  }

  if (status === 'fetched' && isNew) {
    // An earlier pending edition that was never approved is replaced by this one.
    dbUpdateWhere('rag_documents', (x) => x.source_key === key && x.status === 'draft', { status: 'retired' });
    let n = 0, flagged = 0;
    for (const sec of _m19_arrayElements(_m19_has(r, 'sections') ? r.sections : [])) {
      const content = _m19_text(sec, 'content');
      if (Array.from(coalesce(content, '')).length < 200) continue;
      if (n >= 80) break;
      const screening = _m19_get(sec, 'screening');
      dbInsert('rag_documents', {
        title: left(coalesce(nullif(metaText('short_title'), ''), s.title) + ' — ' + left(coalesce(nullif(_m19_text(sec, 'title'), ''), 'Text'), 160), 300),
        source: left(s.publisher + coalesce(_m19_cat('. ', nullif(metaText('citation'), '')), ''), 500),
        version: left(coalesce(nullif(metaText('edition'), ''), version), 60),
        language: s.language, region: s.region, population: s.population,
        // A Google Sheets cell holds 50,000 characters (the SQL kept 60,000).
        content: left(content, 45000), status: 'draft', review_date: _m19_addMonths(today(), s.review_months),
        source_key: key, source_version: version,
        source_url: coalesce(nullif(metaText('url'), ''), _m19_text(s.locator, 'page_url'), _m19_text(s.locator, 'url')),
        publisher: s.publisher,
        external_ids: stripNulls({ pmid: metaText('pmid'), pmcid: metaText('pmcid'), doi: metaText('doi') }),
        license: coalesce(nullif(metaText('license'), ''), s.license),
        audience: s.audience, origin: 'fetched', content_sha: sha256(content), screening: cloneValue(screening),
      });
      n++;
      if (['block', 'suspicious'].includes(_m19_text(screening, 'verdict'))) flagged++;
    }
    if (n === 0) {
      dbUpdate('guideline_sources', s, {
        last_checked_at: now(), last_status: 'error', last_detail: { ...detail, error: 'The fetched edition contained no usable text.' },
      });
      return { key, status: 'error', error: 'no usable text' };
    }
    dbUpdate('guideline_sources', s, { last_checked_at: now(), last_status: 'new_edition', pending_version: version, last_detail: detail });
    fn_notify_safety_officers('guideline', _m19_cat('New guideline edition to review: ', s.title),
      _m19_cat(n, ' section(s) of ', coalesce(metaText('citation'), s.publisher), ' were fetched as drafts',
        flagged > 0 ? ` (${flagged} flagged by the prompt-injection screen)` : '',
        '. Check the text and the license, then approve the edition in Administration, Knowledge base.'),
      _m19_cat('guideline-edition:', key, ':', version));
    dbInsert('audit_logs', {
      action: 'guideline.edition_fetched', entity: 'guideline_source', entity_id: key,
      detail: { version, documents: n, flagged, meta: cloneValue(meta) },
    });
    return { key, status: 'new_edition', version, documents: n, flagged };
  }

  if ((status === 'watch' || status === 'not_licensed') && isNew) {
    const items = _m19_has(r, 'items') ? r.items : [];
    // jsonb_array_length of the items (in SQL it fails after the insert, which rolls the call back all the same)
    const count = _m19_arrayLength(items);
    const u = dbInsert('guideline_updates', { source_key: key, version, items: cloneValue(items) }, {
      onConflict: { cols: ['source_key', 'version'], set: (old, row) => ({ items: row.items, status: 'open', detected_at: now() }) },
    });
    dbUpdate('guideline_sources', s, { last_checked_at: now(), last_status: 'watch_update', pending_version: version, last_detail: detail });
    fn_notify_safety_officers('guideline', _m19_cat('New guideline edition published: ', s.title),
      _m19_cat('Edition ', version, ' (', count, ' publication(s))',
        status === 'not_licensed' ? ' is not licensed for automatic import' : ' is watched only',
        '. Update the knowledge-base summaries from it, then mark the edition reviewed.'),
      _m19_cat('guideline-update:', key, ':', version));
    dbInsert('audit_logs', { action: 'guideline.edition_detected', entity: 'guideline_source', entity_id: key, detail: { version, kind: status } });
    return { key, status: 'watch_update', version, update_id: u.id };
  }

  dbUpdate('guideline_sources', s, { last_checked_at: now(), last_status: 'unchanged', last_detail: detail });
  return { key, status: 'unchanged', version: coalesce(version, s.current_version) };
}

// Approves the pending edition of a source as one unit. A fetched edition needs the reviewer to confirm that its
// license allows this use; its drafts become approved and are indexed (WF-019), and the previous edition stays in use
// until every new document is indexed (fn_guideline_switch_over). For a watched edition, approval records that the
// knowledge base was reviewed against it.
function api_guideline_approve(c, d) {
  const uid = castUuid(_m19_text(c, 'user_id'));
  fn_require_role(c, ['safety_officer']);
  const s = _m19_source(_m19_text(d, 'source_key'));
  if (!s) fn_raise('not_found: guideline source not found');
  const version = coalesce(nullif(_m19_text(d, 'version'), ''), s.pending_version);
  if (version === null || version !== s.pending_version) fn_raise('bad_request: There is no pending edition with this version.');
  const drafts = () => dbWhere('rag_documents', (x) => x.source_key === s.key && x.source_version === version && x.status === 'draft');
  let ids = null;
  if (drafts().length) {
    if (!coalesce(castBool(_m19_text(d, 'license_confirmed')), false)) {
      fn_raise('bad_request: Confirm that the license of this guideline allows its use in the knowledge base before approving it.');
    }
    const rows = drafts();
    for (const x of rows) {
      dbUpdate('rag_documents', x, { status: 'approved', approved_by: uid, license_confirmed_by: uid, license_confirmed_at: now(), published_at: today() });
    }
    ids = rows.map((x) => x.id);
    for (const id of ids) fn_emit('RagDocumentApproved', null, id, { source_key: s.key, version });
  }
  dbUpdateWhere('guideline_updates', (u) => u.source_key === s.key && u.version === version && u.status === 'open',
    { status: 'done', resolved_by: uid, resolved_at: now(), note: nullif(_m19_text(d, 'note'), '') });
  dbUpdate('guideline_sources', s, { current_version: version, pending_version: null });
  fn_audit(c, 'guideline.edition_approved', 'guideline_source', s.key, null,
    { version, documents: ids ? ids.length : 0, license_confirmed: ids !== null, note: _m19_text(d, 'note') });
  return fn_guideline_source_json(s);
}

// Rejects the pending edition: its drafts are retired and the edition is never fetched or announced again.
function api_guideline_dismiss(c, d) {
  fn_require_role(c, ['safety_officer']);
  const s = _m19_source(_m19_text(d, 'source_key'));
  if (!s) fn_raise('not_found: guideline source not found');
  const version = coalesce(nullif(_m19_text(d, 'version'), ''), s.pending_version);
  if (version === null || version !== s.pending_version) fn_raise('bad_request: There is no pending edition with this version.');
  const note = _m19_text(d, 'note');
  if (coalesce(note === null ? null : Array.from(trimChars(note, ' ')).length, 0) < 5) {
    fn_raise('bad_request: Give a short reason for rejecting this edition.');
  }
  dbUpdateWhere('rag_documents', (x) => x.source_key === s.key && x.source_version === version && x.status === 'draft', { status: 'retired' });
  dbUpdateWhere('guideline_updates', (u) => u.source_key === s.key && u.version === version && u.status === 'open',
    { status: 'dismissed', resolved_by: castUuid(_m19_text(c, 'user_id')), resolved_at: now(), note });
  dbUpdate('guideline_sources', s, { pending_version: null, dismissed_versions: [...(s.dismissed_versions || []), version] });
  fn_audit(c, 'guideline.edition_dismissed', 'guideline_source', s.key, null, { version, note });
  return fn_guideline_source_json(s);
}

// After a document of an approved edition is indexed: once every approved document of that edition has chunks, the
// earlier approved editions of the same source are retired (zero-downtime switch-over, called by WF-019).
function fn_guideline_switch_over(p_document_id) {
  const id = castUuid(p_document_id);
  const dd = id === null ? null : dbGet('rag_documents', id);
  if (!dd || dd.source_key === null || dd.status !== 'approved') return { switched: false };
  const indexed = (docId) => dbExists('rag_chunks', (ch) => ch.document_id === docId && ch.embedding !== null);
  if (dbExists('rag_documents', (x) => x.source_key === dd.source_key && dd.source_version !== null && x.source_version === dd.source_version
      && x.status === 'approved' && !indexed(x.id))) {
    return { switched: false, waiting: true };
  }
  const old = dbWhere('rag_documents', (x) => x.source_key === dd.source_key && x.status === 'approved' && x.source_version !== dd.source_version);
  for (const x of old) dbUpdate('rag_documents', x, { status: 'retired', superseded_by: id });
  const oldIds = new Set(old.map((x) => x.id));
  dbDeleteWhere('rag_chunks', (ch) => oldIds.has(ch.document_id));
  if (old.length) {
    dbInsert('audit_logs', {
      action: 'guideline.edition_switched', entity: 'guideline_source', entity_id: dd.source_key,
      detail: { version: dd.source_version, retired_documents: old.length },
    });
  }
  return { switched: old.length > 0, retired: old.length };
}

/* ------------------------------------------------------------------------------------------------- Admin views */

function api_guideline_sources(c, d) {
  fn_require_role(c, ['safety_officer', 'clinic_admin', 'platform_admin']);
  return jsonAgg(orderBy(dbRows('guideline_sources'), (s) => s.pending_version === null, (s) => s.key).map((s) => fn_guideline_source_json(s))) ?? [];
}

// A NULL row (no document) gives an object of nulls, as the SQL function does.
function fn_rag_document_json(d) {
  const x = d || {};
  const v = (k) => (x[k] === undefined ? null : x[k]);
  const id = v('id');
  return {
    id, title: v('title'), source: v('source'), version: v('version'), language: v('language'),
    region: v('region'), population: v('population'), status: v('status'), published_at: v('published_at'), review_date: v('review_date'),
    chunks: dbCount('rag_chunks', (ch) => id !== null && ch.document_id === id && ch.embedding !== null),
    quarantined_chunks: dbCount('rag_chunks', (ch) => id !== null && ch.document_id === id && ch.quarantined === true),
    created_at: v('created_at'), origin: v('origin'), audience: v('audience'), publisher: v('publisher'), source_key: v('source_key'),
    source_version: v('source_version'), source_url: v('source_url'), external_ids: cloneValue(v('external_ids')), license: v('license'),
    license_confirmed_at: v('license_confirmed_at'), screening: cloneValue(v('screening')), superseded: v('superseded_by') !== null,
    // who added it: the same person may not approve it (four eyes)
    created_by: v('created_by'), approved_by: v('approved_by'),
  };
}

// Single-document approval is for documents written by the team. A fetched guideline edition is approved as a whole
// (api_guideline_approve), so its sections can never be half-approved and its license is always confirmed.
function api_rag_approve(c, d) {
  fn_require_role(c, ['safety_officer', 'clinic_admin']);
  const id = castUuid(nullif(_m19_text(d, 'document_id'), ''));
  const dd = id === null ? null : dbGet('rag_documents', id);
  if (!dd || dd.status === 'retired') fn_raise('not_found: document not found or retired');
  if (dd.origin === 'fetched') {
    fn_raise('bad_request: This section belongs to a fetched guideline edition. Approve the whole edition under Guideline sources.');
  }
  // Four eyes: patient education is approved by someone other than the person who added it.
  const uid = castUuid(_m19_text(c, 'user_id'));
  if (dd.created_by !== null && dd.created_by === uid) fn_raise('forbidden: A second person must approve a document you added.');
  dbUpdate('rag_documents', dd, { status: 'approved', approved_by: uid, published_at: coalesce(dd.published_at, today()) });
  fn_emit('RagDocumentApproved', null, dd.id, { title: dd.title });
  fn_audit(c, 'rag.document_approved', 'rag_document', dd.id, null, {});
  return fn_rag_document_json(dd);
}

// ---- 20_operations.js
// 020 Operations: job records, retention, escalation of unacknowledged urgent items, daily care tasks, stale episodes,
// the operations health page, read auditing, input range checks and family changes to verified records
// (port of database/migrations/020_fn_operations.sql).
//
// Notes on the port:
// - Day intervals (`now() - interval 'N days'`, make_interval(days => N)) keep the Cairo wall-clock time across a
//   daylight-saving change, as Postgres does (_m15_daysAgo in 15_events_jobs.js); hour and minute intervals are absolute.
// - Retention never touches audit_logs, which stays append-only (the runtime refuses updates and deletes there).
// - fn_log_date accepts the ISO forms of a date (YYYY-MM-DD, optionally followed by a time, and YYYYMMDD) and the words
//   today / yesterday / tomorrow; other spellings Postgres would read as a date ('10/10/2026', 'Oct 10 2026') are
//   refused with the same "date must be YYYY-MM-DD" message.
// - api_cancel_appointment treats a NULL from fn_can_access_patient as "no access" (fail closed).

/* ------------------------------------------------------------------------------------------- private helpers */

/** jsonb ? key: an object key, a string element of an array, or the string itself; NULL when the value is NULL. */
function _m20_hasKey(v, key) {
  if (v === null || v === undefined || key === null || key === undefined) return null;
  if (Array.isArray(v)) return v.some((x) => typeof x === 'string' && x === key);
  if (typeof v === 'object') return Object.prototype.hasOwnProperty.call(v, key);
  return typeof v === 'string' && v === key;
}
/** Counts per key, as jsonb_object_agg(key, count(*)) ... group by key; {} when there are no rows. */
function _m20_countBy(rows, keyOf) {
  const out = {};
  for (const r of rows) { const k = keyOf(r); out[k] = (out[k] || 0) + 1; }
  return out;
}
/** format('%s', v): NULL prints as the empty string. */
function _m20_s(v) { return v === null || v === undefined ? '' : String(v); }

/* ------------------------------------------------------------------- job records (a job that stops running is visible) */

function fn_job_run(p_job, p_result) {
  dbInsert('job_runs', { job: p_job ?? null, result: p_result ?? null });
  const cutoff = t(_m15_daysAgo(14));
  dbDeleteWhere('job_runs', (r) => r.job === p_job && t(r.at) < cutoff);
  return p_result ?? null;
}

/* ------------------------------------------------------------------------------------------------------ retention */

// Retention (safety_rules.retention_policy). The audit log, clinical records and briefs are kept; operational data that
// can hold health information is removed or emptied when it is no longer needed.
function fn_run_retention() {
  const p = coalesce(fn_rule('retention_policy'), {});
  const days = (key, dflt) => coalesce(castInt(jtext(_m15_get(p, key))), dflt);
  const before = (key, dflt) => t(_m15_daysAgo(days(key, dflt)));
  const r = {};

  let cut = before('outbox_days', 30);
  r.outbox = dbDeleteWhere('outbox', (x) => ['done', 'skipped', 'failed'].includes(x.status) && t(coalesce(x.processed_at, x.occurred_at)) < cut);

  cut = before('incidents_days', 90);
  r.incidents = dbDeleteWhere('incidents', (x) => t(x.at) < cut);

  cut = before('notifications_days', 180);
  r.notifications = dbDeleteWhere('notifications', (x) => t(x.created_at) < cut && x.read_at !== null);

  // AI runs keep their metadata (status, model, release, latency, gate summary) for safety review; the stored inputs
  // and outputs, which can hold health information, are emptied.
  cut = before('ai_run_payload_days', 90);
  r.ai_run_payloads = dbUpdateWhere('ai_runs', (x) => t(x.created_at) < cut && (x.input !== null || x.output !== null), { input: null, output: null });

  // Uploaded files are kept until the document has been reviewed, then for document_file_days.
  cut = before('document_file_days', 30);
  // The file on the n8n server is overwritten (the workflow writes the engine's file list), and the row loses its reference.
  r.document_files = dbUpdateWhere('documents', (x) => (x.file_base64 !== null || x.file_ref !== null) && ['verified', 'rejected'].includes(x.status) && t(x.created_at) < cut,
    (x) => { if (x.file_ref) dbFileRemove(x.file_ref); return { file_base64: null, file_ref: null }; });

  // Every request reads glucose_readings whole, so it must stay small: readings older than readings_archive_days move to
  // glucose_readings_archive (at most readings_archive_batch a night). The data export reads both tabs.
  cut = before('readings_archive_days', 180);
  const old = dbWhere('glucose_readings', (x) => t(x.measured_at) < cut).slice(0, days('readings_archive_batch', 2000));
  for (const x of old) {
    dbInsert('glucose_readings_archive', { ...x, archived_at: now() }, { onConflict: 'nothing' });
    dbDelete('glucose_readings', x);
  }
  r.readings_archived = old.length;

  cut = before('expired_grants_days', 30);
  r.access_grants = dbDeleteWhere('access_grants', (x) => t(x.expires_at) < cut);

  cut = before('invites_days', 30);
  const nowT = nowMs();
  r.invites = dbDeleteWhere('caregiver_invites', (x) => (x.used_at !== null || x.revoked === true || t(x.expires_at) < nowT) && t(x.created_at) < cut);

  cut = before('link_requests_days', 180);
  r.link_requests = dbDeleteWhere('link_requests', (x) => x.status !== 'pending' && t(x.created_at) < cut);

  dbDeleteWhere('mfa_challenges', (x) => t(x.expires_at) < nowT - HOUR);
  const dayAgo = t(_m15_daysAgo(1));
  dbDeleteWhere('password_reset_tokens', (x) => t(x.expires_at) < dayAgo);
  const weekAgo = t(_m15_daysAgo(7)), monthAgo = t(_m15_daysAgo(30));
  dbDeleteWhere('sessions', (x) => t(x.expires_at) < weekAgo || (x.revoked === true && t(x.created_at) < monthAgo));
  dbDeleteWhere('auth_events', (x) => t(x.at) < dayAgo);
  // Deleted rows stay in their tab as tombstones (so row numbers held by running requests stay right); the busiest tabs
  // would grow for ever, so the tombstones this run read are removed here, once there are at least 20 in a tab. The
  // removal is guarded like every write (dbCompact): a request that read the tab before it runs again on a fresh read.
  // Only rows deleted earlier are removed, never a live row; their references were removed or cleared when they were
  // deleted (the foreign-key actions of dbDelete), so nothing points at them.
  let compacted = 0;
  for (const name of ['outbox', 'auth_events', 'sessions', 'notifications', 'incidents', 'mfa_challenges', 'password_reset_tokens',
    'access_grants', 'caregiver_invites', 'link_requests', 'glucose_readings']) compacted += dbCompact(name, { min: 20 });
  if (compacted) r.compacted = compacted;
  return r;
}

/* ------------------------------------------------------------------------------------------------------ escalation */

// An urgent item that nobody acknowledged in time is raised to the Safety Officers and the clinic's administrators
// (once per item). Critical: 30 minutes; high: 4 hours.
function fn_run_escalations() {
  const nowT = nowMs();
  const week = t(_m15_daysAgo(7));   // an older backlog is shown on the health page, not paged
  const late = dbWhere('inbox_items', (i) => ['OPEN', 'ROUTED'].includes(i.status) && i.escalated_at === null
    && t(i.created_at) > week
    && ((i.urgency === 'critical' && t(i.created_at) < nowT - 30 * MIN) || (i.urgency === 'high' && t(i.created_at) < nowT - 4 * HOUR)));
  for (const l of late) dbUpdate('inbox_items', l, { escalated_at: now() });
  const staff = dbWhere('users', (u) => u.active === true && (u.role === 'safety_officer' || u.role === 'clinic_admin'));
  for (const l of late) {
    const o = l.organization_id === null ? null : dbGet('organizations', l.organization_id);
    const minutes = round((nowT - t(l.created_at)) / MIN);
    for (const u of staff) {
      if (u.role === 'clinic_admin'
          && !(l.organization_id !== null && dbExists('memberships', (m) => m.user_id === u.id && m.organization_id === l.organization_id))) continue;
      dbInsert('notifications', {
        user_id: u.id, patient_id: l.patient_id, kind: 'escalation',
        title: `Not yet acknowledged: ${l.title}`,
        body: `A ${l.urgency} item in ${coalesce(o && o.name, 'a clinic')} has waited ${minutes} minutes without acknowledgement.`,
        title_ar: `لم يتم الاطلاع بعد: ${l.title}`,
        body_ar: `عنصر ${l.urgency === 'critical' ? 'حرج' : 'عاجل'} في ${coalesce(o && o.name_ar, o && o.name, 'العيادة')} ينتظر منذ ${minutes} دقيقة دون اطلاع.`,
        dedupe_key: `escalation:${l.id}:${u.id}`,
      }, { onConflict: 'nothing' });
    }
  }
  return { escalated: late.length };
}

/* ---------------------------------------------------------------------------------------- daily care tasks, episodes */

// Daily care tasks: every day the next 7 days of tasks exist for the daily items of each active plan, and daily tasks
// left pending for more than 2 days are marked skipped (the list never grows without end).
function fn_generate_tasks() {
  const day = today();
  const dueTimes = [0, 1, 2, 3, 4, 5, 6].map((n) => castTs(`${addDays(day, n)} 20:00`));
  let created = 0;
  for (const cp of dbWhere('care_plans', (x) => x.status === 'ACTIVE')) {
    const p = dbGet('patients', cp.patient_id);
    if (!p || fn_account_closed(p.id)) continue;
    const items = dbWhere('care_plan_items', (it) => it.plan_id === cp.id && ['monitoring', 'lifestyle'].includes(it.kind)
      && _m20_hasKey(it.schedule, 'times_per_day') === true);
    for (const it of items) {
      for (const due of dueTimes) {
        const row = dbInsert('care_tasks', { patient_id: cp.patient_id, plan_id: cp.id, plan_item_id: it.id, title: it.title,
          title_ar: it.title_ar, kind: it.kind, due_at: due }, { onConflict: 'nothing' });
        if (row) created++;
      }
    }
  }
  const cutoff = t(_m15_daysAgo(2));
  const expired = dbUpdateWhere('care_tasks', (x) => x.status === 'pending' && ['monitoring', 'lifestyle'].includes(x.kind)
    && x.due_at !== null && t(x.due_at) < cutoff, { status: 'skipped' });
  return { created, expired };
}

// Episodes nobody touched for a long time are closed: an intake never finished (3 days) or an assessed problem with
// no activity for 30 days. The follow-up job handles the normal path.
function fn_close_stale_episodes() {
  const d3 = t(_m15_daysAgo(3)), d30 = t(_m15_daysAgo(30));
  const n1 = dbUpdateWhere('episodes', (e) => ['DRAFT', 'INTAKE_IN_PROGRESS'].includes(e.status) && t(e.updated_at) < d3,
    { status: 'CLOSED', updated_at: now() });
  const n2 = dbUpdateWhere('episodes', (e) => ['ASSESSED', 'ROUTED', 'ACTION_SELECTED', 'FOLLOW_UP', 'CARE_RECEIVED'].includes(e.status)
    && t(e.updated_at) < d30, { status: 'CLOSED', updated_at: now() });
  return { abandoned_intakes: n1, inactive: n2 };
}

// A patient whose app account was closed: no reminders, reviews or other patient-facing messages.
function fn_account_closed(p_patient_id) {
  const p = dbGet('patients', castUuid(p_patient_id));
  if (!p || p.user_id === null) return false;
  const u = dbGet('users', p.user_id);
  return !!u && u.active === false;
}

/* ----------------------------------------------- operations health page (platform administrator, Safety Officer) */

function api_admin_health(c, d) {
  const expected = { reminders: 15, followups: 30, pattern_scan: 30, referral_aging: 360, daily_maintenance: 1440 };
  const g = fn_ai_gate(null, 'health_check');
  fn_require_role(c, ['platform_admin', 'safety_officer']);
  const nowT = nowMs();
  const dayAgo = nowT - 24 * HOUR;
  const pending = dbWhere('outbox', (o) => o.status === 'pending');
  const oldest = minOf(pending.map((o) => t(o.occurred_at)));
  const failed = orderBy(dbWhere('outbox', (o) => o.status === 'failed' && o.processed_at !== null && t(o.processed_at) > dayAgo),
    [(o) => t(o.processed_at), 'desc']).slice(0, 20);
  const jobs = Object.keys(expected).sort().map((key) => {
    const every = expected[key];
    const r = orderBy(dbWhere('job_runs', (j) => j.job === key), [(j) => t(j.at), 'desc'])[0] || null;
    return { job: key, every_minutes: every, last_run: r ? r.at : null,
      late: r === null || t(r.at) < nowT - (every * 2 + 5) * MIN, result: r ? r.result : null };
  });
  const runs24 = dbWhere('ai_runs', (r) => t(r.created_at) > dayAgo);
  const incidents = orderBy(dbWhere('incidents', (i) => t(i.at) > dayAgo), [(i) => t(i.at), 'desc']).slice(0, 20);
  const flags = {};
  for (const f of dbRows('feature_flags')) flags[f.key] = f.enabled;
  return {
    at: now(),
    events: {
      by_status: _m20_countBy(dbWhere('outbox', (o) => ['pending', 'processing'].includes(o.status)
        || t(coalesce(o.processed_at, o.occurred_at)) > dayAgo), (o) => o.status),
      oldest_pending_minutes: oldest === null ? null : round((nowT - oldest) / MIN),
      failed_24h: jsonAgg(failed.map((o) => ({ type: o.event_type, error: o.last_error, at: o.processed_at }))) ?? [],
    },
    jobs,
    ai: {
      runs_24h: _m20_countBy(runs24, (r) => r.status),
      releases_24h: _m20_countBy(runs24, (r) => coalesce(jtext(_m15_get(r.guard, 'release')), 'none')),
      open_runs: dbCount('ai_runs', (r) => ['QUEUED', 'PROCESSING', 'VERIFYING'].includes(r.status)),
      cloud_allowed_now: castBool(jtext(_m15_get(g, 'cloud_allowed'))), cloud_reasons: _m15_get(g, 'reasons'),
    },
    incidents_24h: jsonAgg(incidents.map((i) => ({ workflow: i.workflow, node: i.node, message: i.message, at: i.at }))) ?? [],
    inbox: {
      unacknowledged_critical: dbCount('inbox_items', (i) => ['OPEN', 'ROUTED'].includes(i.status) && i.urgency === 'critical'),
      escalated_open: dbCount('inbox_items', (i) => i.status !== 'RESOLVED' && i.escalated_at !== null),
    },
    flags,
  };
}

/* ------------------------------------- read auditing: staff opening a patient's record (once an hour per person, view) */

function fn_audit_read(c, p_patient_id, p_view, p_payload) {
  const role = jtext(_m15_get(c, 'role'));
  const pid = castUuid(p_patient_id);
  if (role !== null && role !== 'patient' && role !== 'caregiver' && pid !== null) {
    const uid = castUuid(jtext(_m15_get(c, 'user_id')));
    const view = p_view ?? null;
    const since = nowMs() - HOUR;
    const seen = uid !== null && view !== null && dbExists('audit_logs', (a) => a.action === 'record.view' && a.actor_id === uid
      && a.patient_id === pid && a.entity === view && t(a.at) > since);
    if (!seen) dbInsert('audit_logs', { actor_id: uid, actor_role: role, action: 'record.view', entity: view, patient_id: pid });
  }
  return p_payload ?? null;
}

/* ------------------- input ranges: a value outside the plausible range is refused with a clear message, not stored */

function fn_num_in(p_data, p_key, p_lo, p_hi, p_default = null) {
  const v = nullif(trimChars(coalesce(jtext(_m15_get(p_data, p_key)), ''), ' '), '');
  if (v === null) return p_default ?? null;
  const ok = /^-?[0-9]+(\.[0-9]+)?$/.test(v);
  const n = ok ? Number(v) : null;
  const lo = p_lo ?? null, hi = p_hi ?? null;
  if (!ok || (lo !== null && n < Number(lo)) || (hi !== null && n > Number(hi))) {
    fn_raise(`bad_request: ${_m20_s(_m15_replace(p_key, '_', ' '))} must be a number from ${_m20_s(lo)} to ${_m20_s(hi)}.`);
  }
  return n + 0;    // -0 is 0, as numeric
}

// A list size or a number of days from the request, kept within limits.
function fn_clamp(p_value, p_default, p_lo, p_hi) {
  const s = p_value === null || p_value === undefined ? '' : String(p_value);
  const x = /^[0-9]{1,6}$/.test(s) ? Number(s) : (p_default ?? null);
  return greatest(p_lo ?? null, least(p_hi ?? null, x));
}

/* ------------- a patient or family member changing something a clinician verified: the care team is told (see
   fn_medication_safety: the clinician's own safety items stay open) */

function fn_note_family_change(c, p_patient_id, p_kind, p_id, p_title, p_verified) {
  const role = jtext(_m15_get(c, 'role'));
  // `role not in (...)` is NULL for a context without role, which does not return here (as in the SQL).
  if ((role !== null && role !== 'patient' && role !== 'caregiver') || !coalesce(p_verified, false)) return;
  p_id = castUuid(p_id);
  const prefix = p_kind === 'medication' ? 'Patient stopped a verified medicine: '
    : p_kind === 'allergy' ? 'Patient removed a verified allergy: '
    : 'Patient marked a verified condition resolved: ';
  fn_create_inbox_item(p_patient_id, 'verification', 'medium', 3, prefix + coalesce(p_title, ''),
    `${role === 'caregiver' ? 'Changed by a family member' : 'Changed by the patient'} in the app. Please review it with them.`,
    { entity: p_kind ?? null, id: p_id ?? null, by_role: role }, _m15_cat('family-change:', p_kind, ':', p_id));
}

/* ------- appointments: cancelling (patients and family: their own future requests and bookings; staff: any open one) */

function api_cancel_appointment(c, d) {
  const role = jtext(_m15_get(c, 'role'));
  const family = role === 'patient' || role === 'caregiver';
  const a = dbGet('appointments', castUuid(nullif(jtext(_m15_get(d, 'appointment_id')), '')));
  if (!a || !fn_can_access_patient(c, a.patient_id)) fn_raise('not_found: appointment not found');
  if (!['requested', 'booked'].includes(a.status)) {
    fn_raise('bad_request: Only a requested or booked appointment can be cancelled.');
  }
  if (family && t(a.starts_at) < nowMs()) fn_raise('bad_request: This appointment has already started or passed.');
  dbUpdate('appointments', a, { status: 'cancelled' });
  const when = _m15_local16(a.starts_at);
  if (family) {
    // The clinic learns about it in its inbox.
    const reason = nullif(left(jtext(_m15_get(d, 'reason')), 300), '');
    fn_create_inbox_item(a.patient_id, 'question', 'low', 4, `Appointment cancelled by the ${role === 'caregiver' ? 'family' : 'patient'}`,
      `${when}${reason === null ? '' : ` · ${reason}`}`, { appointment_id: a.id }, `appt-cancel:${a.id}`);
  } else {
    fn_notify_patient(a.patient_id, 'appointment', 'Your appointment was cancelled',
      `${when}. Please book a new time if you still need one.`, `appt-cancelled:${a.id}`,
      'تم إلغاء موعدك', `${when}. من فضلك احجز موعدًا جديدًا إذا كنت ما زلت تحتاج إليه.`);
  }
  fn_audit(c, 'appointment.cancelled', 'appointment', a.id, a.patient_id);
  return { ok: true, appointment: fn_appointment_json(a) };
}

// The day a log entry belongs to: today when not given; never in the future and at most 30 days back.
function fn_log_date(p) {
  const s = p === null || p === undefined ? '' : trimChars(String(p), ' ');
  const day = today();
  if (s === '') return day;
  let v = null;
  const words = { today: 0, yesterday: -1, tomorrow: 1 };
  const w = s.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(words, w)) v = addDays(day, words[w]);
  else {
    const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ]\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]\d{2}(?::?\d{2})?)?)?$/i)
      || s.match(/^(\d{4})(\d{2})(\d{2})$/);
    if (m) {
      const iso10 = `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
      v = dbTry(() => castDate(iso10), () => null);
    }
  }
  if (v === null) fn_raise('bad_request: date must be YYYY-MM-DD');
  if (v > day) fn_raise('bad_request: The date is in the future.');
  if (v < addDays(day, -30)) fn_raise('bad_request: Entries can be added for the last 30 days only.');
  return v;
}

// ---- 21_quality.js
/* ------------------------------------------------------------------------------------------------------------
   AI quality and continuous improvement
     LLM-as-a-judge (WF-025): AI answers are scored after the fact by a judge model and recorded, one row per answer,
       in the ai_trials tab. Flagged answers (withheld, fallback, risk signals, rejected, fixed off-topic replies) are
       always judged; the rest are sampled (rule ai_judge.sample_pct) within a daily cap, to stay in the free quota.
     Quality incidents: a judged hallucination, unsafe answer, over-refusal or failed answer becomes an incidents row
       (kind ai_*), which the platform admin resolves or dismisses with a note.
     Improvement report (WF-026, weekly and on request): judge metrics by workflow, model and prompt version, AI run
       releases, fallbacks and latency, incidents and the latest evaluation run, with rule-based recommendations, kept
       in the quality_reports tab.
------------------------------------------------------------------------------------------------------------ */

function _m21_obj(v) { return v !== null && typeof v === 'object' && !Array.isArray(v) ? v : {}; }
function _m21_arr(v) { return Array.isArray(v) ? v : []; }
function _m21_int(v, d) { const n = Number(v); return Number.isFinite(n) ? Math.round(n) : d; }
function _m21_rate(n, d) { return d ? Math.round((n / d) * 1000) / 1000 : null; }
function _m21_countBy(rows, key) {
  const out = {};
  for (const r of rows) { const k = String(key(r) ?? 'none'); out[k] = (out[k] || 0) + 1; }
  return out;
}
// A stable 0-99 bucket per run id, so a run is either always or never in the sample.
function _m21_bucket(id) {
  let h = 2166136261;
  for (const ch of String(id)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; }
  return h % 100;
}
// Rows written before the incident columns existed have empty cells: they are open workflow errors of medium severity.
function _m21_kind(x) { return x.kind || 'workflow_error'; }
function _m21_status(x) { return x.status || 'open'; }
function _m21_cfg() {
  const c = _m21_obj(fn_rule('ai_judge'));
  return {
    sample_pct: _m21_int(c.sample_pct, 20), daily_max: _m21_int(c.daily_max, 120), lookback_days: _m21_int(c.lookback_days, 7),
    min_age_minutes: _m21_int(c.min_age_minutes, 2), excerpt_chars: _m21_int(c.excerpt_chars, 300),
  };
}
// The text a person saw (Companion) or read (explanations: every string field of the output).
function _m21_answer(r) {
  const o = _m21_obj(r.output);
  if (typeof o.content === 'string') return o.content;
  // The care-team part of a pattern explanation (summary, questions) is labelled, so the judge does not read it as
  // internal text shown to the patient (judged "raw internal evaluation text", 2026-10-10).
  const SKIP = ['citations', 'suggested_actions', 'language', 'source'], TEAM = ['clinician_summary', 'questions_to_discuss'];
  const parts = [], team = [];
  const walk = (v, out) => {
    if (typeof v === 'string') { if (v.trim()) out.push(v.trim()); } else if (Array.isArray(v)) v.forEach((x) => walk(x, out));
    else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) if (!SKIP.includes(k)) walk(x, out);
  };
  for (const [k, x] of Object.entries(o)) if (!SKIP.includes(k)) walk(x, TEAM.includes(k) ? team : parts);
