  const rows = _m21_arr(q.results).slice(0, 200);
  let n = 0;
  for (const r0 of rows) {
    const r = _m21_obj(r0);
    if (!r.case_id) continue;
    let runId = null;
    try { runId = r.ai_run_id ? castUuid(r.ai_run_id) : null; } catch (e) { runId = null; }
    const ai = runId ? dbGet('ai_runs', runId) : null;
    dbInsert('eval_results', { eval_run: run, case_id: String(r.case_id).slice(0, 20), category: r.category ? String(r.category).slice(0, 40) : null,
      persona: r.persona ? String(r.persona).slice(0, 40) : null, passed: r.passed === true,
      failed_checks: _m21_arr(r.failed_checks).map((x) => String(x).slice(0, 40)).slice(0, 20), ai_run_id: ai ? ai.id : null,
      latency_ms: _m21_int(r.latency_ms, null), prompt_version: ai ? ai.prompt_version : null });
    n++;
  }
  return { eval_run: run, recorded: n };
}

// ---- 22_patient_history.js
/* ------------------------------------------------------------------------------------------------------------
   Patient-history retrieval (RAG over the person's own record) and the dashboard summary, for the Companion's tools
   search_patient_history and get_dashboard_summary.
   A tool result reaches the model without the input gate, so it is de-identified here: no names or ids of people, no
   absolute dates (days_ago instead), and the only free text is the person's own short notes, with their identifiers
   replaced. Clinicians' free text (encounter notes, team messages) is not included. Each item has a ref the answer can
   cite (meal:<id>, lab:<id>, medication:<id>, ...), so a statement about the person's history is checkable.
------------------------------------------------------------------------------------------------------------ */

function _m22_ago(ts) { return ts === null || ts === undefined ? null : round((nowMs() - t(ts)) / DAY, 1); }
function _m22_hour(ts) { try { return cairoParts(ts).h; } catch (e) { return null; } }
// The person's own note with their and their family's identifiers replaced, emails, phones and ids removed, and cut short.
function _m22_redactor(pid) {
  const ids = (fn_ai_gate(pid, 'history').identifiers || []).filter((x) => String(x.value || '').length >= 3)
    .sort((a, b) => String(b.value).length - String(a.value).length);
  return (s) => {
    if (s === null || s === undefined || String(s).trim() === '') return null;
    let out = String(s);
    for (const x of ids) out = out.split(String(x.value)).join('[' + x.type + ']');
    out = regexpReplace(fn_redact_error(out), '\\+?[0-9][0-9 ]{7,}[0-9]', '[phone]', 'g');
    return left(out, 160);
  };
}

/**
 * Searches the person's record for what the question is about: meals (with the glucose rise after them), low and high
 * glucose days, lab results over time, medicines including stopped ones, activity, sleep, check-ins, vitals, visits,
 * care-plan versions and care-access episodes, over the last 180 days. Arabic and English questions are matched through
 * the same query preparation (stemming, glossary expansion) as the knowledge base. Best matches first, then the newest.
 */
function fn_patient_history_search(p_patient_id, p_query, p_k) {
  const pid = castUuid(p_patient_id);
  const k = Math.max(1, Math.min(castInt(p_k) ?? 8, 15));
  const prep = fn_rag_prepare_query(String(p_query ?? '').slice(0, 300), null);
  const terms = new Set(prep.fts_terms);
  const red = _m22_redactor(pid);
  const since = nowMs() - 180 * DAY;
  const items = [];
  const add = (ref, kind, at, summary, words, extra) => items.push({ ref, kind, days_ago: _m22_ago(at), summary, ...(extra || {}), _text: [kind, ...words].filter(Boolean).join(' ') });

  const rise = new Map((fn_meal_responses(pid, 30) || []).map((r) => [r.meal_id, r]));
  for (const m of dbWhere('meal_logs', (x) => x.patient_id === pid && t(x.eaten_at) > since)) {
    const foods = (Array.isArray(m.items) ? m.items : []).map((i) => dbGet('foods', castUuid(i && i.food_id))).filter(Boolean);
    const r = rise.get(m.id);
    add('meal:' + m.id, 'meal', m.eaten_at, `${m.meal_type || 'meal'}: ${foods.map((f) => f.name).join(', ') || 'no foods listed'}`
      + (m.est_carbs_g !== null ? `; about ${m.est_carbs_g} g carbohydrate` : '') + (r && r.rise !== null ? `; glucose rose ${r.rise} mg/dL after it` : ''),
      ['food', 'eat', 'eating', m.meal_type, ...foods.map((f) => f.name), ...foods.map((f) => f.name_ar), m.meal_type === 'breakfast' ? 'فطار' : null, r && r.rise >= 60 ? 'high rise after meal' : null, m.notes],
      { local_hour: _m22_hour(m.eaten_at), note: red(m.notes), _rise: r && r.rise !== null ? r.rise : null });
  }
  // Glucose: one item per day with a low (< 70) or very high (> 250) reading, not every reading.
  const days = new Map();
  for (const g of dbWhere('glucose_readings', (x) => x.patient_id === pid && t(x.measured_at) > since)) {
    const d = localDate(g.measured_at);
    const v = castNum(g.value_mgdl);
    const e = days.get(d) || { min: null, max: null, at: g.measured_at, contexts: new Set() };
    if (e.min === null || v < e.min) { e.min = v; e.at = g.measured_at; }
    if (e.max === null || v > e.max) e.max = v;
    if (g.context) e.contexts.add(g.context);
    days.set(d, e);
  }
  for (const [d, e] of days) {
    if (e.min !== null && e.min < 70) add('glucose_day:' + d, 'low_glucose', e.at, `lowest reading ${e.min} mg/dL that day`, ['low', 'hypoglycemia', 'هبوط', 'reading', ...e.contexts]);
    if (e.max !== null && e.max > 250) add('glucose_day:' + d, 'high_glucose', e.at, `highest reading ${e.max} mg/dL that day`, ['high', 'hyperglycemia', 'ارتفاع', 'reading', ...e.contexts]);
  }
  for (const l of dbWhere('lab_results', (x) => x.patient_id === pid && x.verification_status !== 'refuted')) {
    const lc = dbGet('lab_catalog', l.test_code);
    add('lab:' + l.id, 'lab', l.observed_at, `${lc ? lc.display : l.test_code} ${l.value} ${l.unit || ''}`.trim(), ['lab', 'test', 'تحليل', l.test_code, lc ? lc.display : null], { verification: l.verification_status });
  }
  for (const m of dbWhere('medications', (x) => x.patient_id === pid && x.verification_status !== 'refuted')) {
    const d = m.generic ? dbGet('drugs', m.generic) : null;
    add('medication:' + m.id, 'medicine', coalesce(m.end_date, m.start_date, m.created_at), `${m.name} (${m.generic || 'unknown generic'}), ${m.status}`
      + (m.start_date ? `, started ${_m22_ago(m.start_date)} days ago` : '') + (m.end_date ? `, stopped ${_m22_ago(m.end_date)} days ago` : ''),
      ['medicine', 'medication', 'دوا', m.name, m.generic, m.drug_class, m.status === 'stopped' ? 'stopped' : null, ...(d ? [d.display_ar, ...(d.brand_names_ar || [])] : [])]);
  }
  for (const a of dbWhere('activity_logs', (x) => x.patient_id === pid && x.date > addDays(today(), -30))) {
    add('activity:' + a.id, 'activity', a.date, `${a.steps ?? 0} steps` + (a.minutes ? `, ${a.minutes} min ${a.type || ''}` : ''), ['activity', 'walk', 'walking', 'steps', 'exercise', 'مشي', a.type]);
  }
  for (const s of dbWhere('sleep_logs', (x) => x.patient_id === pid && x.date > addDays(today(), -30))) {
    add('sleep:' + s.id, 'sleep', s.date, `${s.hours} h sleep` + (s.quality ? `, quality ${s.quality}` : ''), ['sleep', 'نوم', s.quality]);
  }
  for (const c of dbWhere('checkins', (x) => x.patient_id === pid && t(x.at) > since)) {
    add('checkin:' + c.id, 'checkin', c.at, `mood ${c.mood ?? '-'}/5, stress ${c.stress ?? '-'}/5, energy ${c.energy ?? '-'}/5`, ['mood', 'stress', 'energy', 'feel', 'مزاج', 'توتر', c.note], { note: red(c.note) });
  }
  for (const v of dbWhere('vitals', (x) => x.patient_id === pid && t(x.measured_at) > since)) {
    add('vital:' + v.id, v.type, v.measured_at, v.type === 'blood_pressure' ? `blood pressure ${v.systolic}/${v.diastolic} mmHg` : `${v.type} ${v.value} ${v.unit || ''}`.trim(),
      [v.type === 'blood_pressure' ? 'blood pressure ضغط' : v.type === 'weight' ? 'weight وزن' : v.type]);
  }
  for (const ap of dbWhere('appointments', (x) => x.patient_id === pid && t(x.starts_at) > since)) {
    const future = t(ap.starts_at) > nowMs();
    add('appointment:' + ap.id, 'appointment', ap.starts_at, `${ap.type || 'appointment'} (${ap.channel || 'visit'}), ${ap.status}` + (future ? `, in ${round((t(ap.starts_at) - nowMs()) / DAY, 1)} days` : ''),
      ['appointment', 'visit', 'doctor', 'clinic', 'موعد', 'دكتور', ap.type, ap.channel]);
  }
  for (const e of dbWhere('encounters', (x) => x.patient_id === pid && t(x.occurred_at) > since)) {
    add('encounter:' + e.id, 'visit', e.occurred_at, 'a visit with the care team (notes are with the clinician)', ['visit', 'doctor', 'clinic', 'زياره', 'دكتور']);
  }
  for (const p of dbWhere('care_plans', (x) => x.patient_id === pid && x.published_at !== null)) {
    add('careplan:' + p.id, 'care_plan', p.published_at, `care plan version ${p.version} (${p.status})`, ['plan', 'care plan', 'خطه', 'changed', 'target']);
  }
  for (const e of dbWhere('episodes', (x) => x.patient_id === pid && t(x.started_at) > since)) {
    add('episode:' + e.id, 'care_request', e.started_at, `Need Care request, ${e.status}` + (e.selected_action ? `, ${e.selected_action}` : ''),
      ['symptom', 'problem', 'need care', 'تعبان', e.chief_complaint], { complaint: red(e.chief_complaint) });
  }

  const hitsIn = (txt) => { let n = 0; for (const w of new Set(fn_rag_search_text(txt).split(' '))) if (terms.has(w)) n++; return n; };
  const scored = items.map((x) => ({ ...x, _hits: terms.size ? hitsIn(x._text) : 0 })).filter((x) => x._hits > 0);
  // "Which meals raise my sugar (the most)?": meals by the size of the rise after them instead of the newest first.
  const byRise = ['rais', 'rise', 'rose', 'spike', 'most', 'worst', 'بيرفع', 'يرفع', 'رفع', 'اكتر', 'اكثر'].some((w) => [...terms].some((x) => x.startsWith(w)));
  const top = orderBy(scored, [(x) => x._hits, 'desc'], [(x) => (byRise ? -(x._rise ?? -1e9) : 0), 'asc'], [(x) => x.days_ago ?? 1e9, 'asc']).slice(0, k);
  return {
    query_terms: [...terms].slice(0, 20), searched_days: 180, matches: scored.length,
    results: top.map(({ _text, _hits, _rise, ...x }) => x),
    note: scored.length ? null : 'Nothing in the record matched; use the other tools or PATIENT_CONTEXT, or say the record has no data on it.',
  };
}

/** The person's dashboard (Today and Food & activity screens) as the model sees it: no dates, no free text. */
function fn_dashboard_summary(p_patient_id, p_days) {
  const pid = castUuid(p_patient_id);
  const days = Math.max(1, Math.min(castInt(p_days) ?? 7, 30));
  const life = fn_lifestyle_summary(pid, days) || {};
  const en = life.energy || {};
  const targets = fn_targets(pid);
  const g = fn_glucose_metrics(pid, days);
  const steps = life.steps_avg ?? null;
  return {
    days,
    glucose: g ? { mean: g.mean, tir: g.tir, tbr: (g.tbr_level1 ?? 0) + (g.tbr_level2 ?? 0), tar: (g.tar_level1 ?? 0) + (g.tar_level2 ?? 0), readings: g.readings, data_quality: g.data_quality,
      latest: g.latest ? { value_mgdl: g.latest.value_mgdl, age_minutes: g.latest.age_minutes } : null } : null,
    target_checks: fn_target_checks(pid, targets, fn_glucose_metrics(pid, 14), steps),
    energy: { eaten_today_kcal: en.eaten_today_kcal ?? null, meals_today: en.meals_today ?? null, burned_today_kcal: en.burned_today_kcal ?? null,
      eaten_avg_kcal: en.eaten_avg_kcal ?? null, days_with_meals: en.days_with_meals ?? null, estimated_needs_kcal: en.needs ? en.needs.kcal ?? null : null,
      needs_note: en.needs ? en.needs.note ?? null : null },
    activity: { steps_avg: steps, active_minutes_avg: life.active_minutes_avg ?? null, days_logged: (life.activity || []).length },
    sleep: { hours_avg: life.sleep_hours_avg ?? null },
    weight: { latest_kg: life.weight_latest ?? null, change_30d_kg: life.weight_change_30d ?? null },
    meals_logged: (life.meals || []).length,
  };
}

// ---- 23_prediction.js
/* 23 · Prediction: early warnings of low glucose, from the person's own readings (deterministic, no AI).
 *
 *   fn_glucose_trend(patient, at)   the trend of the last window_min minutes: least-squares slope (mg/dL per minute)
 *                                   and the value projected horizon_min minutes ahead. Needs min_points readings that
 *                                   span at least min_span_min minutes (a CGM, or frequent meter readings).
 *   fn_predict_low(patient, reading) after each new live reading (fn_add_glucose): when the trend will cross the low
 *                                   threshold, or falls fast near it, the person and their family get a fixed warning;
 *                                   the care team gets an inbox item when the projection is below the severe threshold
 *                                   or it is night. At most one warning per patient per hour.
 *   fn_run_night_risk()             once in the evening (from fn_run_reminders): a "risky night" notice when someone on
 *                                   insulin or a sulfonylurea has another risk factor (exercise today, a low evening
 *                                   reading, a night low this week).
 * The texts give the person's own low-sugar plan (check, 15 g fast sugar, check again), never a medicine change.
 * Settings: safety rule low_prediction (any key overrides the defaults below).
 */

const _P23_DEFAULTS = {
  window_min: 30, horizon_min: 30, min_points: 3, min_span_min: 15, live_within_min: 20,
  min_drop_per_min: 1, fast_drop_per_min: 2, fast_below: 100,
  night_from: 22, night_to: 6, night_check_hour: 21, bedtime_below: 120, exercise_minutes: 30, night_low_days: 7,
  hypo_classes: ['basal_insulin', 'rapid_insulin', 'sulfonylurea'],
};

function _p23_cfg() {
  const c = { ..._P23_DEFAULTS, ...(coalesce(fn_rule('low_prediction'), {})) };
  for (const k of Object.keys(_P23_DEFAULTS)) if (typeof _P23_DEFAULTS[k] === 'number') c[k] = coalesce(castNum(c[k]), _P23_DEFAULTS[k]);
  return c;
}

function _p23_isNight(cfg, ts) {
  const h = localHour(ts);
  return cfg.night_from > cfg.night_to ? (h >= cfg.night_from || h < cfg.night_to) : (h >= cfg.night_from && h < cfg.night_to);
}

/** Trend of the readings in the window ending at p_at (default now), or null when there are too few. */
function fn_glucose_trend(p_patient_id, p_at = null) {
  const cfg = _p23_cfg();
  const pid = castUuid(p_patient_id);
  const end = p_at === null || p_at === undefined ? nowMs() : t(p_at);
  const from = end - cfg.window_min * MIN;
  const pts = dbWhere('glucose_readings', (r) => r.patient_id === pid && t(r.measured_at) >= from && t(r.measured_at) <= end)
    .map((r) => ({ x: (t(r.measured_at) - end) / MIN, y: castNum(r.value_mgdl) }))
    .filter((p) => p.y !== null)
    .sort((a, b) => a.x - b.x);
  if (pts.length < cfg.min_points || pts[pts.length - 1].x - pts[0].x < cfg.min_span_min) return null;
  const mx = pts.reduce((s, p) => s + p.x, 0) / pts.length;
  const my = pts.reduce((s, p) => s + p.y, 0) / pts.length;
  const den = pts.reduce((s, p) => s + (p.x - mx) ** 2, 0);
  if (den === 0) return null;
  const slope = pts.reduce((s, p) => s + (p.x - mx) * (p.y - my), 0) / den;
  const last = pts[pts.length - 1].y;
  return { slope: round(slope, 2), last, projected: Math.round(last + slope * cfg.horizon_min), points: pts.length, horizon_min: cfg.horizon_min };
}

/** After a new reading: warns about a coming low. Returns the warning (also sent), or null. */
function fn_predict_low(p_patient_id, p_reading) {
  const cfg = _p23_cfg();
  const pid = castUuid(p_patient_id);
  if (!p_reading || pid === null) return null;
  const at = t(p_reading.measured_at);
  if (!(at > nowMs() - cfg.live_within_min * MIN)) return null;           // back-filled data: no live warning
  const th = coalesce(fn_rule('glucose_thresholds'), {});
  const hypo = coalesce(castNum(th.hypo), 70), severe = coalesce(castNum(th.severe_hypo), 54);
  const trend = fn_glucose_trend(pid, p_reading.measured_at);
  if (trend === null || trend.last < hypo) return null;                     // already low: the low-glucose alert handles it
  const crossing = trend.slope <= -cfg.min_drop_per_min && trend.projected < hypo;
  const fast = trend.slope <= -cfg.fast_drop_per_min && trend.last < cfg.fast_below;
  if (!crossing && !fast) return null;
  const night = _p23_isNight(cfg, p_reading.measured_at);
  const serious = trend.projected < severe;
  const dedupe = `lowpred:${pid}:${Math.floor(at / HOUR)}`;
  const en = `Your glucose is ${trend.last} mg/dL and falling (about ${Math.abs(trend.slope)} mg/dL a minute). It may go below ${hypo} within about ${cfg.horizon_min} minutes. Check your glucose now. If it is below ${hypo}, follow your low-sugar plan: 15 g of fast sugar, then check again after 15 minutes.`;
  const ar = `السكر ${trend.last} مجم/دل وبينزل (حوالي ${Math.abs(trend.slope)} مجم/دل في الدقيقة)، وممكن يقل عن ${hypo} خلال حوالي ${cfg.horizon_min} دقيقة. قيس السكر دلوقتي. لو أقل من ${hypo}، اتبع خطة هبوط السكر: 15 جرام سكر سريع، وقيس تاني بعد 15 دقيقة.`;
  fn_notify_patient(pid, 'low_predicted', 'Low glucose may be coming', en, dedupe, 'احتمال هبوط السكر قريبًا', ar);
  if (serious || night) {
    fn_create_inbox_item(pid, 'glucose', serious ? 'high' : 'medium', serious ? 2 : 3,
      `Low glucose predicted${night ? ' (night)' : ''}: ${trend.last} → ~${trend.projected} mg/dL in ${cfg.horizon_min} min`,
      `Falling ${trend.slope} mg/dL/min over ${trend.points} readings.`, { type: 'low_predicted', ...trend, night }, dedupe);
  }
  return { type: 'low_predicted', ...trend, night, serious, message_en: en, message_ar: ar };
}

/** Evening check (at night_check_hour, local): a "risky night" notice for people on insulin or a sulfonylurea. */
function fn_run_night_risk() {
  const cfg = _p23_cfg();
  const day = today();
  const th = coalesce(fn_rule('glucose_thresholds'), {});
  const hypo = coalesce(castNum(th.hypo), 70);
  const since = nowMs() - cfg.night_low_days * DAY;
  const eveningFrom = t(dayStart(day)) + 18 * HOUR - 0;
  let sent = 0;
  const onHypoMeds = new Set(dbWhere('medications', (m) => m.status === 'active' && m.verification_status !== 'refuted'
    && cfg.hypo_classes.includes(m.drug_class)).map((m) => m.patient_id));
  for (const pid of onHypoMeds) {
    const p = dbGet('patients', pid);
    if (!p || p.user_id === null || fn_account_closed(pid)) continue;
    const reasons = [];
    const nightLow = dbExists('glucose_events', (e) => e.patient_id === pid && ['hypo', 'severe_hypo'].includes(e.type)
      && t(e.occurred_at) > since && _p23_isNight(cfg, e.occurred_at));
    if (nightLow) reasons.push(['a low at night this week', 'هبوط بالليل الأسبوع ده']);
    const ex = dbWhere('activity_logs', (a) => a.patient_id === pid && String(a.date).slice(0, 10) === day)
      .reduce((s, a) => s + coalesce(castNum(a.minutes), 0), 0);
    if (ex >= cfg.exercise_minutes) reasons.push([`${ex} minutes of exercise today`, `${ex} دقيقة رياضة النهارده`]);
    const evening = orderBy(dbWhere('glucose_readings', (r) => r.patient_id === pid && t(r.measured_at) >= eveningFrom), [(r) => t(r.measured_at), 'desc'])[0];
    if (evening && castNum(evening.value_mgdl) < cfg.bedtime_below && castNum(evening.value_mgdl) >= hypo) {
      reasons.push([`an evening reading of ${evening.value_mgdl} mg/dL`, `قراية بالليل ${evening.value_mgdl} مجم/دل`]);
    }
    if (!reasons.length) continue;
    fn_notify_patient(pid, 'night_low_risk', 'Higher risk of a low tonight',
      `Because of ${reasons.map((r) => r[0]).join(', ')}, your risk of a low tonight is higher than usual. Check your glucose before bed and keep fast sugar next to your bed. If this happens often, ask your care team about a bedtime plan.`,
      `nightrisk:${pid}:${day}`, 'احتمال هبوط السكر الليلة أعلى',
      `بسبب ${reasons.map((r) => r[1]).join('، ')}، احتمال هبوط السكر الليلة أعلى من المعتاد. قيس السكر قبل النوم وخلّي سكر سريع جنب السرير. لو ده بيتكرر، اسأل فريق الرعاية عن خطة لوقت النوم.`);
    sent++;
  }
  return { night_risk: sent };
}

// ---- 24_ramadan.js
/* 24 · Ramadan: the IDF-DAR 2021 fasting risk score, the person's fasting choice, and a check of every reading taken
 * during fasting hours (deterministic, no AI).
 *
 *   fn_ramadan_score(patient, answers)  the score from the record (diabetes type and duration, lows, HbA1c, medicines,
 *                                       kidney function, pregnancy) plus the answers only the person or clinician can
 *                                       give (awareness of lows, glucose checking, complications, frailty, physical
 *                                       work, earlier Ramadan). Missing answers count 0 and are listed in `missing`.
 *   api_ramadan_assess(c, d)            stores the assessment; a high-risk result goes to the care team's inbox.
 *   api_ramadan_status(c, d)            the latest assessment, the Ramadan dates and today's fasting window.
 *   api_ramadan_set_fasting(c, d)       the person says they are (not) fasting this Ramadan.
 *   fn_ramadan_check_reading(p, r)      during fasting hours of a fasting day: a reading below break_below or above
 *                                       break_above gets the fixed "break your fast now" message (fn_add_glucose).
 * Points and categories follow the IDF-DAR Diabetes and Ramadan Practical Guidelines 2021 (low 0-3, moderate 3.5-6,
 * high > 6). Demonstration content: the Clinical Safety Officer must check it against the guideline before use.
 * Settings: safety rule `ramadan` (dates, fasting hours, break thresholds).
 */

const _R24_DEFAULTS = { start: '2027-02-08', end: '2027-03-09', fasting_from: '04:15', fasting_to: '17:45', break_below: 70, break_above: 300 };
const _R24_ANSWERS = {
  hypo_unawareness: [true, false],
  smbg: ['as_indicated', 'suboptimal', 'not_done'],
  acute_complication: ['none', 'last_12m', 'last_6m', 'last_3m'],
  macrovascular: ['none', 'stable', 'unstable'],
  frailty: ['none', 'over70_no_support', 'frail_or_cognitive'],
  labour: ['none', 'moderate', 'intense'],
  previous_ramadan: ['no_problem', 'negative', 'first_time'],
};

function _r24_cfg() { return { ..._R24_DEFAULTS, ...(coalesce(fn_rule('ramadan'), {})) }; }

/** IDF-DAR 2021 risk score: { score, category, items[], missing[], advice_en, advice_ar }. */
function fn_ramadan_score(p_patient_id, p_answers = {}) {
  const pid = castUuid(p_patient_id);
  const p = dbGet('patients', pid);
  if (!p) fn_raise('not_found: patient not found');
  const a = p_answers && typeof p_answers === 'object' ? p_answers : {};
  for (const [k, v] of Object.entries(a)) {
    if (!(k in _R24_ANSWERS)) fn_raise(`bad_request: unknown answer ${k}`);
    if (v !== null && !_R24_ANSWERS[k].includes(v)) fn_raise(`bad_request: ${k} must be one of ${_R24_ANSWERS[k].join(', ')}`);
  }
  const items = [];
  const add = (key, points, basis, detail) => items.push({ key, points, basis, detail });
  const missing = [];
  const answer = (key) => { if (a[key] === undefined || a[key] === null) { missing.push(key); return null; } return a[key]; };

  add('diabetes_type', p.diabetes_type === 'type1' ? 1 : 0, 'record', p.diabetes_type);
  const yearsSince = p.diagnosis_year ? Number(today().slice(0, 4)) - Number(p.diagnosis_year) : null;
  add('duration', yearsSince !== null && yearsSince >= 10 ? 1 : 0, yearsSince === null ? 'missing' : 'record', yearsSince === null ? null : `${yearsSince} years`);

  // Lows: unawareness (answer) > a severe low in 3 months > several lows a week > fewer lows > none.
  const day = nowMs();
  const lows = dbWhere('glucose_events', (e) => e.patient_id === pid && ['hypo', 'severe_hypo'].includes(e.type));
  const severe90 = lows.some((e) => e.type === 'severe_hypo' && t(e.occurred_at) > day - 90 * DAY);
  const lows28 = lows.filter((e) => t(e.occurred_at) > day - 28 * DAY).length;
  const unaware = answer('hypo_unawareness');
  if (unaware === true) add('hypoglycaemia', 6.5, 'answer', 'unaware of lows');
  else if (severe90) add('hypoglycaemia', 5.5, 'record', 'severe low in the last 3 months');
  else if (lows28 >= 4) add('hypoglycaemia', 3.5, 'record', `${lows28} lows in 4 weeks`);
  else if (lows28 >= 1) add('hypoglycaemia', 1, 'record', `${lows28} low(s) in 4 weeks`);
  else add('hypoglycaemia', 0, 'record', 'no lows in 4 weeks');

  const a1c = orderBy(dbWhere('lab_results', (l) => l.patient_id === pid && l.test_code === 'hba1c' && l.verification_status !== 'refuted' && l.value !== null),
    [(l) => t(l.observed_at), 'desc'])[0] || null;
  const a1cV = a1c ? castNum(a1c.value) : null;
  add('hba1c', a1cV === null ? 0 : a1cV > 9 ? 2 : a1cV >= 7.5 ? 1 : 0, a1cV === null ? 'missing' : 'record', a1cV === null ? null : `${a1cV}%`);

  const meds = dbWhere('medications', (m) => m.patient_id === pid && m.status === 'active' && m.verification_status !== 'refuted');
  const cls = new Set(meds.map((m) => m.drug_class));
  const gens = meds.map((m) => String(m.generic || m.name || '').toLowerCase());
  const insulinOrSu = cls.has('basal_insulin') || cls.has('rapid_insulin') || cls.has('sulfonylurea');
  const treat = cls.has('basal_insulin') && cls.has('rapid_insulin') ? [2.5, 'basal-bolus insulin']
    : cls.has('rapid_insulin') ? [2.5, 'mealtime insulin'] : cls.has('basal_insulin') ? [1.5, 'basal insulin']
    : gens.some((g) => /glibenclamide|glyburide/.test(g)) ? [1, 'glibenclamide']
    : cls.has('sulfonylurea') ? [0.5, 'sulfonylurea'] : [0, 'other treatment'];
  add('treatment', treat[0], 'record', treat[1]);

  // Glucose checking: the answer, or from the record for people on insulin or a sulfonylurea (14 checks in 14 days).
  let smbg = answer('smbg');
  if (smbg === null && insulinOrSu) {
    const n14 = dbCount('glucose_readings', (r) => r.patient_id === pid && t(r.measured_at) > day - 14 * DAY);
    smbg = n14 >= 14 ? 'as_indicated' : n14 >= 1 ? 'suboptimal' : 'not_done';
    missing.splice(missing.indexOf('smbg'), 1);
  }
  add('glucose_checking', smbg === 'not_done' ? 2 : smbg === 'suboptimal' ? 1 : 0, a.smbg ? 'answer' : smbg ? 'record' : 'missing', smbg);

  const acute = answer('acute_complication');
  add('acute_complications', { last_3m: 3, last_6m: 2, last_12m: 1 }[acute] || 0, acute ? 'answer' : 'missing', acute);
  const macro = answer('macrovascular');
  add('macrovascular', { unstable: 6.5, stable: 2 }[macro] || 0, macro ? 'answer' : 'missing', macro);

  const eg = fn_egfr(pid);
  const e = eg && eg.value_exact !== null && eg.value_exact !== undefined ? eg.value_exact : null;
  add('kidney', e === null ? 0 : e < 30 ? 6.5 : e < 45 ? 4 : e < 60 ? 2 : 0, e === null ? 'missing' : 'record', e === null ? null : `eGFR ${eg.value}`);
  add('pregnancy', p.pregnant === true ? 6.5 : 0, 'record', p.pregnant === true ? 'pregnant' : null);
  const frail = answer('frailty');
  add('frailty', { frail_or_cognitive: 6.5, over70_no_support: 3.5 }[frail] || 0, frail ? 'answer' : 'missing', frail);
  const labour = answer('labour');
  add('physical_labour', { intense: 4, moderate: 2 }[labour] || 0, labour ? 'answer' : 'missing', labour);
  const prev = answer('previous_ramadan');
  add('previous_ramadan', prev === 'negative' ? 1 : 0, prev ? 'answer' : 'missing', prev);

  const score = round(items.reduce((s, i) => s + i.points, 0), 1);
  const category = score <= 3 ? 'low' : score <= 6 ? 'moderate' : 'high';
  const cfg = _r24_cfg();
  const ADVICE = {
    low: [`Low risk. Fasting is likely to be safe with a plan from your care team. Check your glucose during the day; checking does not break the fast. Break your fast at once if your glucose is below ${cfg.break_below} or above ${cfg.break_above} mg/dL, or if you feel unwell.`,
      `خطورة منخفضة. الصيام غالبًا آمن مع خطة من فريق الرعاية. قيس السكر أثناء النهار، والقياس لا يفطر. افطر فورًا لو السكر أقل من ${cfg.break_below} أو أعلى من ${cfg.break_above} مجم/دل، أو لو حسيت بتعب.`],
    moderate: [`Moderate risk. Talk to your care team before Ramadan: fasting may be possible with a personal plan and frequent glucose checks. Break your fast at once if your glucose is below ${cfg.break_below} or above ${cfg.break_above} mg/dL, or if you feel unwell.`,
      `خطورة متوسطة. اتكلم مع فريق الرعاية قبل رمضان: الصيام ممكن مع خطة شخصية وقياس متكرر للسكر. افطر فورًا لو السكر أقل من ${cfg.break_below} أو أعلى من ${cfg.break_above} مجم/دل، أو لو حسيت بتعب.`],
    high: ['High risk. Fasting is not advised for you. Please see your doctor before Ramadan to plan what is safe for you.',
      'خطورة عالية. الصيام غير منصوح به لك. من فضلك قابل طبيبك قبل رمضان علشان تتفقوا على الآمن ليك.'],
  };
  return { version: 'IDF-DAR 2021', score, category, items, missing, advice_en: ADVICE[category][0], advice_ar: ADVICE[category][1] };
}

function _r24_latest(pid) {
  return orderBy(dbWhere('ramadan_assessments', (r) => r.patient_id === pid), [(r) => t(r.created_at), 'desc'])[0] || null;
}

/** Stores an assessment (patient, family member with 'log' scope, or care team). */
function api_ramadan_assess(c, d) {
  const pid = fn_resolve_patient(c, d);
  const res = fn_ramadan_score(pid, d && d.answers ? d.answers : {});
  const prev = _r24_latest(pid);
  const row = dbInsert('ramadan_assessments', { patient_id: pid, year: Number(_r24_cfg().start.slice(0, 4)), score: res.score,
    category: res.category, items: res.items, answers: (d && d.answers) || {}, fasting: prev ? prev.fasting === true && res.category !== 'high' : false,
    assessed_by: castUuid(c.user_id) });
  if (res.category === 'high') {
    fn_create_inbox_item(pid, 'care_plan', 'medium', 3, `Ramadan risk: high (IDF-DAR ${res.score})`,
      'Pre-Ramadan visit needed: fasting is not advised. Review the treatment plan and give fasting advice.',
      { type: 'ramadan_high_risk', assessment_id: row.id, score: res.score }, `ramadan-high:${pid}:${row.year}`);
  }
  fn_audit(c, 'ramadan.assess', 'ramadan_assessment', row.id, pid, { score: res.score, category: res.category });
  return { id: row.id, ...res, fasting: row.fasting };
}

/** The latest assessment and today's fasting window. */
function api_ramadan_status(c, d) {
  const pid = fn_resolve_patient(c, d);
  const cfg = _r24_cfg();
  const last = _r24_latest(pid);
  const day = today();
  return {
    ramadan: { start: cfg.start, end: cfg.end, active: day >= cfg.start && day <= cfg.end, fasting_from: cfg.fasting_from, fasting_to: cfg.fasting_to,
      break_below: cfg.break_below, break_above: cfg.break_above },
    assessment: last ? { id: last.id, score: last.score, category: last.category, items: last.items, created_at: last.created_at } : null,
    fasting: last ? last.fasting === true : false,
  };
}

/** The person says they are fasting (or not). Needs an assessment first; not allowed after a high-risk result. */
function api_ramadan_set_fasting(c, d) {
  const pid = fn_resolve_patient(c, d);
  const last = _r24_latest(pid);
  const want = castBool(d && d.fasting) === true;
  if (!last) fn_raise('bad_request: Please complete the Ramadan risk check first.');
  if (want && last.category === 'high') fn_raise('forbidden: Fasting is not advised at high risk. Please talk to your doctor first.');
  dbUpdate('ramadan_assessments', last, { fasting: want, updated_at: now() });
  fn_audit(c, 'ramadan.set_fasting', 'ramadan_assessment', last.id, pid, { fasting: want });
  return { fasting: want };
}

/** During fasting hours on a fasting day of Ramadan: "break your fast" for a reading out of the safe range. */
function fn_ramadan_check_reading(p_patient_id, p_reading) {
  const cfg = _r24_cfg();
  const pid = castUuid(p_patient_id);
  if (!p_reading || pid === null) return null;
  const day = localDate(p_reading.measured_at);
  if (!(day >= cfg.start && day <= cfg.end)) return null;
  if (!(t(p_reading.measured_at) > nowMs() - 2 * HOUR)) return null;
  const last = _r24_latest(pid);
  if (!last || last.fasting !== true) return null;
  const hm = localHHMM(p_reading.measured_at);
  if (!(hm >= cfg.fasting_from && hm < cfg.fasting_to)) return null;
  const v = castNum(p_reading.value_mgdl);
  if (v === null || (v >= cfg.break_below && v <= cfg.break_above)) return null;
  const low = v < cfg.break_below;
  const en = low
    ? `Your glucose is ${v} mg/dL. Break your fast now: take 15 g of fast sugar, check again after 15 minutes, then eat. Tell your care team.`
    : `Your glucose is ${v} mg/dL. Break your fast now: drink water and check again within an hour. If it stays high, or you feel unwell, vomit or breathe fast, seek care today.`;
  const ar = low
    ? `السكر ${v} مجم/دل. افطر دلوقتي: خد 15 جرام سكر سريع، وقيس تاني بعد 15 دقيقة، وبعدين كُل. بلّغ فريق الرعاية.`
    : `السكر ${v} مجم/دل. افطر دلوقتي: اشرب مية وقيس تاني خلال ساعة. لو فضل عالي، أو حسيت بتعب أو ترجيع أو نفس سريع، اطلب رعاية النهارده.`;
  fn_notify_patient(pid, 'ramadan_break_fast', 'Break your fast now', en, `ramadan-break:${p_reading.id}`, 'افطر دلوقتي', ar);
  fn_create_inbox_item(pid, 'glucose', low ? 'high' : 'medium', low ? 2 : 3, `Fasting patient: ${v} mg/dL during the fast`,
    'The person was told to break the fast. Review the Ramadan plan.', { type: 'ramadan_break_fast', value: v }, `ramadan-break:${p_reading.id}`);
  return { type: 'break_fast', value: v, message_en: en, message_ar: ar };
}

// ---- 25_care_gaps.js
/* 25 · Care gaps and panel risk: what a clinic should act on first, across all its patients (deterministic, no AI).
 *
 *   fn_care_gaps(ctx)        overdue screenings (eye, foot, HbA1c, urine albumin, lipids… from fn_screenings) per
 *                            patient the caller may see, with days overdue, plus per-screening coverage of the panel.
 *   fn_panel_risk(ctx, n)    the n patients with the highest risk score, each with the reasons (English and Arabic):
 *                            recent lows, time in range, HbA1c, kidney function, open safety findings, urgent inbox
 *                            items, overdue screenings, missing data. Points: safety rule panel_risk (defaults below).
 * Clinical roles only (doctor, nurse, clinic administrator); reception and patients are refused.
 */

const _G25_POINTS = {
  severe_hypo_7d: 5, hypo_2plus_7d: 3, tir_below_50: 3, tir_50_70: 1, hba1c_above_9: 3, hba1c_above_8: 2,
  egfr_below_30: 3, egfr_below_45: 2, safety_finding: 2, urgent_inbox: 2, overdue_screening: 1, overdue_max: 3, no_data_14d: 1,
  adherence_below_50: 2, adherence_50_80: 1, medicine_runs_out: 1, therapy_review: 1, wellbeing_flag: 2, self_harm_30d: 5, sick_day: 2,
};

function _g25_clinical(c) {
  const role = c !== null && typeof c === 'object' ? jtext(c.role) : null;
  if (!['doctor', 'nurse', 'clinic_admin'].includes(role)) fn_raise('forbidden: Only the care team can see this.');
}

function _g25_patients(c) { return dbRows('patients').filter((p) => fn_can_access_patient(c, p.id) && !fn_account_closed(p.id)); }

function _g25_daysBetween(a, b) { return Math.round((t(`${b}T00:00:00Z`) - t(`${a}T00:00:00Z`)) / DAY); }

function fn_care_gaps(c) {
  _g25_clinical(c);
  const td = today();
  const patients = [];
  const cover = {};
  for (const p of _g25_patients(c)) {
    const sc = fn_screenings(p.id);
    for (const s of sc) {
      cover[s.type] = cover[s.type] || { type: s.type, title: s.title, title_ar: s.title_ar, up_to_date: 0, total: 0 };
      cover[s.type].total++;
      if (!s.overdue) cover[s.type].up_to_date++;
    }
    const gaps = sc.filter((s) => s.overdue).map((s) => ({ type: s.type, title: s.title, title_ar: s.title_ar, last_done: s.last_done,
      next_due: s.next_due, days_overdue: s.last_done === null ? null : Math.max(0, _g25_daysBetween(s.next_due, td)) }));
    if (gaps.length) patients.push({ id: p.id, full_name: p.full_name, full_name_ar: p.full_name_ar, mrn: p.mrn, gaps });
  }
  patients.sort((a, b) => b.gaps.length - a.gaps.length || (a.full_name || '').localeCompare(b.full_name || ''));
  const coverage = Object.values(cover).map((x) => ({ ...x, percent: x.total ? Math.round((100 * x.up_to_date) / x.total) : null }));
  return { date: td, patients, coverage, patients_with_gaps: patients.length };
}

function fn_panel_risk(c, p_limit = 20) {
  _g25_clinical(c);
  const P = { ..._G25_POINTS, ...(coalesce(fn_rule('panel_risk'), {})) };
  const limit = Math.max(1, Math.min(coalesce(castInt(p_limit), 20), 100));
  const nowT = nowMs(), from7 = nowT - 7 * DAY;
  const out = [];
  for (const p of _g25_patients(c)) {
    const reasons = [];
    let score = 0;
    const add = (pts, en, ar) => { if (pts > 0) { score += pts; reasons.push({ points: pts, en, ar }); } };
    const ev = dbWhere('glucose_events', (e) => e.patient_id === p.id && t(e.occurred_at) > from7);
    const lows7 = dbCount('glucose_readings', (r) => r.patient_id === p.id && t(r.measured_at) > from7 && castNum(r.value_mgdl) < 70);
    const severe7 = ev.some((e) => e.type === 'severe_hypo') || dbExists('glucose_readings', (r) => r.patient_id === p.id && t(r.measured_at) > from7 && castNum(r.value_mgdl) < 54);
    if (severe7) add(P.severe_hypo_7d, 'Severe low in the last 7 days', 'هبوط شديد خلال آخر 7 أيام');
    else if (lows7 >= 2) add(P.hypo_2plus_7d, `${lows7} lows in the last 7 days`, `${lows7} مرات هبوط خلال آخر 7 أيام`);
    const m = fn_glucose_metrics(p.id, 14);
    if (!m || m.readings === 0) add(P.no_data_14d, 'No glucose readings in 14 days', 'مفيش قراءات سكر خلال 14 يوم');
    else if (m.tir !== null && m.tir < 50) add(P.tir_below_50, `Time in range ${m.tir}%`, `الوقت في المدى ${m.tir}%`);
    else if (m.tir !== null && m.tir < 70) add(P.tir_50_70, `Time in range ${m.tir}%`, `الوقت في المدى ${m.tir}%`);
    const a1c = orderBy(dbWhere('lab_results', (l) => l.patient_id === p.id && l.test_code === 'hba1c' && l.verification_status !== 'refuted' && l.value !== null),
      [(l) => t(l.observed_at), 'desc'])[0];
    const a1cV = a1c ? castNum(a1c.value) : null;
    if (a1cV !== null && a1cV > 9) add(P.hba1c_above_9, `HbA1c ${a1cV}%`, `السكر التراكمي ${a1cV}%`);
    else if (a1cV !== null && a1cV > 8) add(P.hba1c_above_8, `HbA1c ${a1cV}%`, `السكر التراكمي ${a1cV}%`);
    const eg = fn_egfr(p.id);
    if (eg && eg.value_exact !== null && eg.value_exact < 30) add(P.egfr_below_30, `eGFR ${eg.value}`, `وظائف الكلى ${eg.value}`);
    else if (eg && eg.value_exact !== null && eg.value_exact < 45) add(P.egfr_below_45, `eGFR ${eg.value}`, `وظائف الكلى ${eg.value}`);
    const findings = dbCount('safety_findings', (f) => f.patient_id === p.id && f.status === 'open' && ['major', 'contraindicated'].includes(f.severity));
    if (findings) add(P.safety_finding, `${findings} open medicine safety finding(s)`, `${findings} ملاحظة أمان دوائي مفتوحة`);
    const urgent = dbCount('inbox_items', (i) => i.patient_id === p.id && i.status !== 'RESOLVED' && ['high', 'critical'].includes(i.urgency));
    if (urgent) add(P.urgent_inbox, `${urgent} urgent inbox item(s)`, `${urgent} عناصر عاجلة في البريد`);
    // Medicines: doses taken in the last 14 days, and a medicine about to run out (28_adherence.js).
    const adh = fn_adherence(p.id, 14);
    if (adh !== null && adh < 50) add(P.adherence_below_50, `Medicines taken ${adh}% (14 days)`, `الالتزام بالأدوية ${adh}% (14 يوم)`);
    else if (adh !== null && adh < 80) add(P.adherence_50_80, `Medicines taken ${adh}% (14 days)`, `الالتزام بالأدوية ${adh}% (14 يوم)`);
    const runsOut = fn_refills_due(p.id).filter((r) => r.days_left !== null && r.days_left <= 1);
    if (runsOut.length) add(P.medicine_runs_out, `${runsOut.map((r) => r.name).join(', ')} runs out`, `${runsOut.map((r) => r.name).join('، ')} على وشك النفاد`);
    // A "review" treatment consideration nobody has decided on yet (32_personal.js): lows on medicines that cause them,
    // or HbA1c above target with no plan change.
    const review = p.diabetes_type === 'type2' && !p.pregnant ? fn_therapy_considerations(p.id).items.filter((x) => x.kind === 'review') : [];
    if (review.length) add(P.therapy_review, review.map((x) => x.title_en).join('; '), review.map((x) => x.title_ar).join('؛ '));
    // Check-ins and sick days (33_wellbeing.js): self-harm thoughts in 30 days, a high PHQ-9 or PAID-5, an active sick day.
    const qs = dbWhere('questionnaires', (q) => q.patient_id === p.id && t(q.created_at) > nowT - 90 * DAY);
    if (qs.some((q) => q.crisis === true && t(q.created_at) > nowT - 30 * DAY)) add(P.self_harm_30d, 'Self-harm thoughts reported (PHQ-9) in 30 days', 'أفكار إيذاء النفس (PHQ-9) خلال 30 يومًا');
    else if (qs.some((q) => (q.kind === 'phq9' && castNum(q.score) >= 10) || (q.kind === 'paid5' && castNum(q.score) >= 8))) add(P.wellbeing_flag, 'Check-in: distress or depression score high', 'الاستبيان: درجة ضيق أو اكتئاب مرتفعة');
    if (dbExists('sick_days', (s) => s.patient_id === p.id && s.ended_at === null)) add(P.sick_day, 'Unwell now (sick-day mode)', 'مريض الآن (وضع أيام المرض)');
    const overdue = fn_screenings(p.id).filter((s) => s.overdue).length;
    if (overdue) add(Math.min(overdue * P.overdue_screening, P.overdue_max), `${overdue} overdue screening(s)`, `${overdue} فحوصات متأخرة`);
    if (score > 0) out.push({ id: p.id, full_name: p.full_name, full_name_ar: p.full_name_ar, mrn: p.mrn, score, reasons: reasons.sort((a, b) => b.points - a.points) });
  }
  out.sort((a, b) => b.score - a.score || (a.full_name || '').localeCompare(b.full_name || ''));
  return { patients: out.slice(0, limit), ranked: out.length };
}

// ---- 26_meter_photo.js
/* 26 · Reading a glucose meter's screen from a photo (the AI section is workflows/src/meter.mjs, WF-028).
 *
 *   fn_meter_photo_ctx(c, d)   who asks, for which patient, and where the photo may be read: by the local model always
 *                              (with AI-processing consent), in the cloud only with the meter_photo_cloud flag and the
 *                              usual cloud gate. Nothing is stored: the number fills the log form and the person
 *                              checks it and taps Save (glucose.add), like a typed reading.
 *   fn_meter_photo_result(o)   the model's answer, checked: a number a meter can show (mg/dL, or mmol/L converted),
 *                              HI/LO, or nothing; a low-confidence or implausible read is returned as "not read".
 */

function fn_meter_photo_ctx(c, d) {
  const pid = fn_resolve_patient(c, d);
  const gate = fn_ai_gate(pid, 'meter_photo');
  const flag = dbGet('feature_flags', 'meter_photo_cloud');
  return {
    patient_id: pid,
    ai_allowed: gate.ai_allowed === true,
    cloud_allowed: gate.cloud_allowed === true && coalesce(flag ? flag.enabled : null, false) === true,
  };
}

function fn_meter_photo_result(o) {
  const r = o && typeof o === 'object' ? o : {};
  const hilo = String(r.hi_lo || '').toUpperCase();
  const conf = ['high', 'medium', 'low'].includes(r.confidence) ? r.confidence : 'low';
  if (r.reading_visible !== true || conf === 'low') return { read: false, reason: r.reading_visible === true ? 'unsure' : 'no_reading' };
  if (hilo === 'HI' || hilo === 'LO') return { read: true, hi_lo: hilo, value_mgdl: null, confidence: conf };
  let v = castNum(r.value);
  const unit = String(r.unit || '').toLowerCase().replace(/\s+/g, '');
  if (v === null) return { read: false, reason: 'no_reading' };
  // A meter in mmol/L shows one decimal (5.6); in mg/dL a whole number (101).
  const mmol = unit.includes('mmol') || (unit === '' && v < 35 && !Number.isInteger(v));
  if (mmol) v = Math.round(v * 18.016);
  v = Math.round(v);
  if (v < 20 || v > 600) return { read: false, reason: 'out_of_range' };
  return { read: true, value_mgdl: v, converted_from_mmol: mmol, hi_lo: null, confidence: conf };
}

// ---- 27_digest.js
/* 27 · Weekly digest: a short summary of the past 7 days for the person and their family (deterministic, no AI).
 *
 *   fn_weekly_digest(patient)   the numbers (time in range and its change from the week before, mean, lows, days with
 *                               a reading, medicines taken, average steps) and one goal, chosen by fixed rules:
 *                               lows first, then too few readings, then time in range, then steps.
 *   fn_run_weekly_digest()      once a week (from fn_run_reminders: digest_weekday at digest_hour, Cairo time): an in-app
 *                               notice to the person and their family, and, when email is on, an email that only says
 *                               the summary is ready (no health values travel by email).
 * Settings: safety rule weekly_digest (weekday 0 = Sunday … 6 = Saturday; default Saturday 10:00).
 */

const _D27_DEFAULTS = { digest_weekday: 6, digest_hour: 10, min_readings: 7, steps_goal: 6000 };
function _d27_cfg() {
  const c = { ..._D27_DEFAULTS, ...(coalesce(fn_rule('weekly_digest'), {})) };
  for (const k of Object.keys(_D27_DEFAULTS)) c[k] = coalesce(castNum(c[k]), _D27_DEFAULTS[k]);
  return c;
}

function fn_weekly_digest(p_patient_id) {
  const cfg = _d27_cfg();
  const pid = castUuid(p_patient_id);
  const nowT = nowMs(), from7 = nowT - 7 * DAY, from14 = nowT - 14 * DAY;
  const rs = dbWhere('glucose_readings', (r) => r.patient_id === pid && t(r.measured_at) > from14 && t(r.measured_at) <= nowT)
    .map((r) => ({ v: castNum(r.value_mgdl), at: t(r.measured_at) })).filter((r) => r.v !== null);
  const week = rs.filter((r) => r.at > from7), prev = rs.filter((r) => r.at <= from7);
  const tir = (xs) => (xs.length ? Math.round((100 * xs.filter((r) => r.v >= 70 && r.v <= 180).length) / xs.length) : null);
  // Calendar days in Cairo: today and the 6 days before (a 7 x 24 h window touches 8 dates).
  const firstDay = addDays(today(), -6);
  const days = new Set(week.map((r) => localDate(new Date(r.at).toISOString())).filter((x) => x >= firstDay)).size;
  const lows = week.filter((r) => r.v < 70).length;
  const mean = week.length ? Math.round(week.reduce((s, r) => s + r.v, 0) / week.length) : null;
  const acts = dbWhere('activity_logs', (a) => a.patient_id === pid && t(`${String(a.date).slice(0, 10)}T12:00:00Z`) > from7);
  const steps = acts.length ? Math.round(acts.reduce((s, a) => s + coalesce(castNum(a.steps), 0), 0) / 7) : null;
  const meds = fn_adherence(pid, 7);
  const d = { readings: week.length, days_with_readings: days, tir: tir(week), tir_prev: tir(prev), mean, lows, steps_avg: steps, medicines_taken_pct: meds };
  // One goal, the most useful first.
  let goal;
  if (lows >= 2) goal = ['You had ' + lows + ' lows this week. Keep fast sugar with you and check before driving and at bedtime. Tell your care team if lows keep happening.',
    'حصل عندك ' + lows + ' مرات هبوط الأسبوع ده. خلّي معاك سكر سريع، وقيس قبل السواقة وقبل النوم. بلّغ فريق الرعاية لو الهبوط بيتكرر.'];
  else if (week.length < cfg.min_readings) goal = ['Try to log at least one glucose reading a day this week.', 'حاول تسجل قراية سكر واحدة على الأقل كل يوم الأسبوع ده.'];
  else if (d.tir !== null && d.tir < 70) goal = ['A 10 to 15 minute walk after your largest meal can lower the rise in glucose.', 'المشي 10 لـ 15 دقيقة بعد أكبر وجبة بيقلل ارتفاع السكر بعد الأكل.'];
  else if (steps !== null && steps < cfg.steps_goal) goal = [`Aim for ${cfg.steps_goal} steps a day this week.`, `حاول توصل لـ ${cfg.steps_goal} خطوة في اليوم الأسبوع ده.`];
  else goal = ['Great week. Keep going with what works for you.', 'أسبوع ممتاز. كمّل على اللي ماشي معاك.'];
  const change = d.tir !== null && d.tir_prev !== null ? d.tir - d.tir_prev : null;
  const parts = [];
  const partsAr = [];
  if (d.tir !== null) {
    parts.push(`Time in range ${d.tir}%${change === null ? '' : change === 0 ? ' (same as last week)' : ` (${change > 0 ? 'up' : 'down'} ${Math.abs(change)} from last week)`}`);
    partsAr.push(`الوقت في المدى ${d.tir}%${change === null ? '' : change === 0 ? ' (زي الأسبوع اللي فات)' : ` (${change > 0 ? 'زاد' : 'قل'} ${Math.abs(change)} عن الأسبوع اللي فات)`}`);
  }
  parts.push(`${days} of 7 days with a reading`); partsAr.push(`${days} من 7 أيام فيها قراية`);
  if (lows) { parts.push(`${lows} low${lows > 1 ? 's' : ''}`); partsAr.push(`${lows} هبوط`); }
  if (meds !== null) { parts.push(`medicines taken ${meds}%`); partsAr.push(`الأدوية اتاخدت ${meds}%`); }
  if (steps !== null) { parts.push(`about ${steps} steps a day`); partsAr.push(`حوالي ${steps} خطوة في اليوم`); }
  return { ...d, change, text_en: `${parts.join(', ')}. ${goal[0]}`, text_ar: `${partsAr.join('، ')}. ${goal[1]}` };
}

function fn_run_weekly_digest() {
  const day = today();
  let sent = 0, emails = 0;
  for (const p of dbWhere('patients', (x) => x.user_id !== null)) {
    if (fn_account_closed(p.id)) continue;
    const d = fn_weekly_digest(p.id);
    if (d.readings === 0 && d.steps_avg === null && d.medicines_taken_pct === null) continue;   // nothing to report
    fn_notify_patient(p.id, 'weekly_digest', 'Your week', d.text_en, `digest:${p.id}:${day}`, 'أسبوعك', d.text_ar);
    sent++;
    if (fn_email_enabled()) { fn_emit('WeeklyDigestEmail', p.id, p.user_id, {}); emails++; }
  }
  return { digests: sent, emails };
}

// ---- 28_adherence.js
/* 28 · Medicine supply, refills and missed doses (deterministic, no AI).
 *
 *   fn_med_supply(m)                 units left from the last count: the count minus every scheduled dose since then
 *                                    (assumes doses are taken as prescribed, so it never overstates the supply).
 *   api_set_supply(c, d)             the person (or family member, or clinician) counts what is left of a medicine.
 *   fn_refills_due(pid)              medicines that run out within refill_days_ahead days (Today, the clinician).
 *   fn_dose_reason_followup(...)     a dose missed because the medicine was not available, too expensive or had side
 *                                    effects goes to the care team's inbox (once a week per medicine and reason).
 *   fn_run_adherence()               part of the 15-minute reminders job: "did you take it?" two hours after a dose
 *                                    with no answer (to the person only), and refill notices (to the person and family).
 * Settings: rule `adherence` (refill_days_ahead, missed_followup_minutes, team_reasons).
 * Why: medication reminders are the feature people with type 2 diabetes ask for most, and medicine shortages and price
 * rises in Egypt (2024-2026) make "could not get it" a frequent reason for missed doses that the clinic needs to know.
 */

const _A28_DEFAULTS = { refill_days_ahead: 5, missed_followup_minutes: 120, team_reasons: ['not_available', 'cost', 'side_effects'] };
const _A28_REASONS = ['forgot', 'side_effects', 'not_available', 'cost', 'felt_well', 'fasting', 'other'];
const _A28_REASON_TEXT = {
  not_available: ['could not find it in pharmacies', 'لم يجده في الصيدليات'],
  cost: ['could not afford it', 'لم يستطع شراءه بسبب السعر'],
  side_effects: ['side effects', 'أعراض جانبية'],
};

function _a28_cfg() { return { ..._A28_DEFAULTS, ...(coalesce(fn_rule('adherence'), {})) }; }

function _a28_times(m) { return (Array.isArray(m.times) ? m.times : []).filter((x) => typeof x === 'string' && _M11_HHMM.test(x)); }

/** Supply of one medicine: null when it was never counted. */
