// ---- 31_sections.js
// Database steps of the workflow sections whose SQL was a query of its own rather than a call of one function: the
// Companion's agent tools, the scheduler queries, RAG chunk storage, the incident record and the intake episode load.
// The workflow calls them through engine_step (see workflows/src/sheets-steps.mjs, which maps every former Postgres
// node to its JavaScript).

/** 099 · Record incident: insert into incidents (message without identifiers) returning id. */
function sec_record_incident(workflow, node, message, executionId) {
  const r = dbInsert('incidents', { workflow, node, message: fn_redact_error(message), execution_id: executionId });
  return { id: r.id };
}

/** Companion tool get_meal_responses: glucose before and after logged meals, with the foods, biggest rise first. */
function sec_meal_responses(patientId, days) {
  const rows = (fn_meal_responses(patientId, days) || []).map((r) => {
    const m = dbGet('meal_logs', r.meal_id);
    if (!m) return null;
    const foods = (Array.isArray(m.items) ? m.items : [])
      .map((i) => dbGet('foods', castUuid(jtext(i && i.food_id))))
      .filter(Boolean).map((f) => f.name);
    return { r, out: {
      days_ago: round((nowMs() - t(r.eaten_at)) / DAY, 1),
      local_hour: localHour(r.eaten_at),
      carbs_g: r.est_carbs_g ?? null, pre: r.pre ?? null, peak: r.peak ?? null, rise: r.rise ?? null,
      foods: foods.length ? foods.join(', ') : null,
    } };
  }).filter(Boolean);
  return orderBy(rows, [(x) => x.r.rise, 'desc', 'nulls last']).map((x) => x.out);
}

/** Companion tool get_plan_and_appointments: structured plan fields only, and upcoming appointments. */
function sec_plan_and_appointments(patientId) {
  const plan = dbOne('care_plans', (c) => c.patient_id === patientId && c.status === 'ACTIVE');
  let planOut = null;
  if (plan) {
    const p = fn_plan_json(plan.id) || {};
    planOut = { version: p.version ?? null, title: p.title ?? null, targets: p.targets ?? null,
      items: (Array.isArray(p.items) ? p.items : []).map((i) => omit(i, 'id', 'detail')) };
  }
  const appointments = dbWhere('appointments', (a) => a.patient_id === patientId && t(a.starts_at) > nowMs() && ['booked', 'requested'].includes(a.status))
    .map((a) => ({ in_days: round((t(a.starts_at) - nowMs()) / DAY, 1), local_time: localHHMM(a.starts_at), type: a.type, channel: a.channel, status: a.status }));
  return { plan: planOut, appointments };
}

/** Companion tool find_care: facilities near the patient (no row when the patient is unknown). */
function sec_find_care(patientId, specialty, facilityType) {
  const p = dbGet('patients', patientId);
  if (!p) return [];
  return [{ facilities: fn_match_facilities({ specialty: nullif(left(specialty, 40), ''), type: nullif(left(facilityType, 40), ''),
    lat: p.lat ?? null, lng: p.lng ?? null, limit: 5, specialty_soft: true, include_directory: true }) }];
}

/** 002 · Load episode: the episode with its AI gate, if the caller may see the patient; otherwise not_found. */
function sec_load_episode(ctx, data) {
  const id = castUuid(nullif(jtext((data || {}).episode_id), ''));
  const e = id ? dbGet('episodes', id) : null;
  if (e && fn_can_access_patient(ctx, e.patient_id)) {
    return { episode: { id: e.id, answers: e.answers, patient_id: e.patient_id, gate: fn_ai_gate(e.patient_id, 'care_access') } };
  }
  return { episode: fn_raise('not_found: episode not found') };
}

/**
 * 006 · Active patients: up to 15 app users with readings this week and no weekly review in 6 days, longest-waiting
 * first. Closed accounts and populations outside the AI policy are left out.
 */
function sec_weekly_candidates() {
  const lastWeekly = (pid) => maxOf(dbWhere('patient_insights', (i) => i.patient_id === pid && i.kind === 'weekly').map((i) => i.created_at));
  const recent = new Set(dbWhere('glucose_readings', (g) => t(g.measured_at) > nowMs() - 7 * DAY).map((g) => g.patient_id));
  const list = dbWhere('patients', (p) => p.user_id !== null && !fn_account_closed(p.id) && (fn_exclusions(p.id) || []).length === 0 && recent.has(p.id)
    && !dbExists('patient_insights', (i) => i.patient_id === p.id && i.kind === 'weekly' && t(i.created_at) > nowMs() - 6 * DAY));
  return orderBy(list, [(p) => lastWeekly(p.id), 'asc', 'nulls first'], (p) => p.id).slice(0, 15).map((p) => ({ patient_id: p.id }));
}

/** 009b · Appointments needing a brief: booked, within 48 hours, linked patient, no brief yet (3 at a time). */
function sec_brief_candidates() {
  const list = dbWhere('appointments', (a) => a.status === 'booked' && t(a.starts_at) >= nowMs() && t(a.starts_at) <= nowMs() + 48 * HOUR
    && fn_tier(a.patient_id) === 'linked' && !dbExists('previsit_briefs', (b) => b.appointment_id === a.id));
  return orderBy(list, (a) => a.starts_at).slice(0, 3).map((a) => ({ appointment_id: a.id, patient_id: a.patient_id }));
}

/** admin.rag_sync: asks WF-019c to read the Drive knowledge folder now (the event dispatcher starts it at once). */
function api_rag_sync(c) {
  fn_emit('KnowledgeSyncRequested', null, null, { requested_by: jtext((c || {}).user_id) });
  fn_audit(c, 'knowledge.sync_requested', 'rag_document', null, null);
  return { queued: true };
}

/**
 * 019c · Knowledge base from Google Drive: which files of the folder need (re)ingestion — new, changed (Drive version)
 * or never indexed. Documents whose file has left the folder are retired here, with their chunks.
 *   files: the Drive listing [{ id, name, mimeType, modifiedTime, md5Checksum }]
 */
function sec_drive_plan(files, complete = false) {
  const list = (Array.isArray(files) ? files : []).filter((f) => f && f.id && f.mimeType !== 'application/vnd.google-apps.folder');
  const seen = new Set();
  const out = [];
  for (const f of list) {
    const key = `drive:${f.id}`;
    seen.add(key);
    const version = String(f.md5Checksum || f.modifiedTime || '');
    const doc = dbOne('rag_documents', (d) => d.source_key === key);
    const indexed = doc && dbExists('rag_chunks', (c) => c.document_id === doc.id);
    if (doc && doc.status === 'approved' && doc.source_version === version && indexed) continue;
    out.push({ file_id: f.id, name: f.name, mime_type: f.mimeType || 'text/plain', version, modified: f.modifiedTime || null, url: `https://drive.google.com/file/d/${f.id}` });
  }
  // Retiring documents whose file left the folder needs a complete, non-empty listing (all pages fetched), and at most
  // a quarter of the folder's documents (at least 3) in one run. A permissions problem or a partial listing would
  // otherwise empty the knowledge base; then nothing is retired and an incident asks a person to check.
  const gone = dbWhere('rag_documents', (d) => String(d.source_key || '').startsWith('drive:') && d.status === 'approved' && !seen.has(d.source_key));
  const approved = dbCount('rag_documents', (d) => String(d.source_key || '').startsWith('drive:') && d.status === 'approved');
  const limit = Math.max(3, Math.floor(approved / 4));
  if (gone.length && (complete !== true || list.length === 0 || gone.length > limit)) {
    dbInsert('incidents', { workflow: 'Health Platform', node: '019c · Plan sync', kind: 'workflow_error', severity: 'medium',
      message: `Drive sync did not retire ${gone.length} document(s): ${complete !== true ? 'the folder listing was incomplete' : list.length === 0 ? 'the folder listing was empty' : `more than ${limit} at once`}. Check the folder and its sharing.` });
    return out;
  }
  for (const d of gone) {
    dbUpdate('rag_documents', d, { status: 'retired' });
    dbDeleteWhere('rag_chunks', (c) => c.document_id === d.id);
  }
  return out;
}

/**
 * 019c · One Drive file as an approved knowledge document (the folder is the approval). A Markdown file may start with
 * front matter (title, source, version, language, audience, publisher). Returns the document in the shape the ingestion
 * steps take: { doc: { id, title, content }, injection }. The tab keeps at most 45,000 characters of the text (a Sheets
 * cell holds 50,000); the chunks are made from the whole text.
 */
function sec_drive_document(file, text) {
  let body = String(text || '').replace(/\r/g, '');
  const meta = {};
  const fm = body.match(/^---\n([\s\S]*?)\n---\n/);
  if (fm) {
    for (const line of fm[1].split('\n')) { const m = line.match(/^(\w+):\s*(.*)$/); if (m) meta[m[1].toLowerCase()] = m[2].trim().replace(/^"(.*)"$/, '$1'); }
    body = body.slice(fm[0].length);
  }
  body = body.trim();
  if (!body) throw new Error(`bad_request: the Drive file "${file && file.name}" has no text`);
  const arabic = (body.match(/[؀-ۿ]/g) || []).length > (body.match(/[A-Za-z]/g) || []).length;
  const values = {
    title: left(meta.title || String(file.name || 'Document').replace(/\.[a-z0-9]+$/i, ''), 300),
    source: meta.source || `Google Drive: ${file.name}`,
    version: meta.version || (file.modified ? String(file.modified).slice(0, 10) : '1'),
    language: meta.language === 'ar' || meta.language === 'en' ? meta.language : (arabic ? 'ar' : 'en'),
    audience: meta.audience === 'clinician' ? 'clinician' : 'patient',
    publisher: meta.publisher || null,
    content: body.slice(0, RAG_PART_CHARS),
    status: 'approved', origin: 'manual',
    source_key: `drive:${file.file_id}`, source_version: file.version || null, source_url: file.url || null,
    content_sha: sha256(body), published_at: file.modified ? localDate(file.modified) : today(),
  };
  const existing = dbOne('rag_documents', (d) => d.source_key === values.source_key);
  const doc = existing ? dbUpdate('rag_documents', existing, values) : dbInsert('rag_documents', values);
  fn_rag_store_parts(doc.id, body);
  return { doc: { id: doc.id, title: doc.title, content: body }, injection: fn_rule('prompt_injection') };
}

/* A Sheets cell holds 50,000 characters: a document's text is kept in rag_documents.content (the first part) and, when
 * longer, in rag_document_parts (the rest, in order). Re-indexing reads the whole text back (fn_rag_ingest_doc). */
const RAG_PART_CHARS = 45000;

/** Stores the text beyond the first part; parts the new text no longer needs are removed. */
function fn_rag_store_parts(documentId, text) {
  const body = String(text || '');
  const parts = [];
  for (let i = RAG_PART_CHARS; i < body.length; i += RAG_PART_CHARS) parts.push(body.slice(i, i + RAG_PART_CHARS));
  const old = dbWhere('rag_document_parts', (p) => p.document_id === documentId);
  parts.forEach((content, k) => {
    const row = old.find((p) => p.part === k + 1);
    if (row) { if (row.content !== content) dbUpdate('rag_document_parts', row, { content }); }
    else dbInsert('rag_document_parts', { document_id: documentId, part: k + 1, content });
  });
  for (const p of old) if (p.part > parts.length) dbDelete('rag_document_parts', p);
  return parts.length;
}

/** The whole text of an approved document, for (re)ingestion: { id, title, content }, or {} when not approved. */
function fn_rag_ingest_doc(p_document_id) {
  const d = dbGet('rag_documents', castUuid(p_document_id));
  if (!d || d.status !== 'approved') return {};
  const rest = orderBy(dbWhere('rag_document_parts', (p) => p.document_id === d.id), (p) => p.part).map((p) => p.content).join('');
  return { id: d.id, title: d.title, content: String(d.content || '') + rest };
}

/** 019 · Store chunk: insert or replace one chunk of a document, returning its document id. */
function sec_store_chunk(documentId, index, content, embedding, embedModel, quarantined, reason) {
  // Four decimals keep a 768-number embedding near 6 KB in its Sheets cell; cosine ranking does not change.
  const vec = Array.isArray(embedding) ? embedding.map((x) => Math.round(Number(x) * 1e4) / 1e4) : embedding;
  const values = { content, embedding: vec, search_text: fn_rag_search_text(content), embed_model: embedModel, content_sha: sha256(content),
    quarantined: castBool(quarantined), quarantine_reason: nullif(reason, ''), indexed_at: now() };
  const r = dbInsert('rag_chunks', { document_id: documentId, chunk_index: index, ...values }, { onConflict: { cols: ['document_id', 'chunk_index'], set: values } });
  return { document_id: r.document_id };
}

// ---- 32_personal.js
/* 32 · Personalized care, per patient (deterministic rules; the clinician decides, the patient sees the result).
 *
 *   fn_personal_targets(pid)          a suggested target set (tier tighter, standard, relaxed, older_complex, or
 *                                     pregnancy with no number) and the reasons, from age, diabetes duration, lows,
 *                                     medicines that cause lows, kidney function, heart disease, other conditions and
 *                                     frailty. A suggestion for the doctor: it becomes the person's targets only when the
 *                                     doctor puts it in the care plan and publishes it.
 *   fn_therapy_considerations(pid)    clinician-only points to consider (kidney or heart disease without an SGLT2 inhibitor
 *                                     or GLP-1 RA, BMI 30+, lows on a sulfonylurea or insulin, HbA1c above target with no
 *                                     plan change, statin, ACE inhibitor or ARB). Never a dose, never shown to patients,
 *                                     never sent to the Companion. A doctor's decision hides an item for recheck_days.
 *   fn_food_profile(pid, days)        how this person's sugar rose after meals with each food, from their own readings.
 *   preferences                       how the person likes to be helped (simple words, voice, meal pattern, shift,
 *                                     sleep times, budget, who cooks, fasting days, goals): used by the Companion's
 *                                     wording and examples and by notification quiet hours.
 * Settings: rules personal_targets and therapy_considerations (ADA Standards of Care 2026, sections 6, 9, 10, 11, 13).
 * Demonstration values: the Clinical Safety Officer must check them against the guideline before use.
 */

const _P32_TARGETS = {
  tiers: {
    tighter: { hba1c_target: 6.5, tir_target: 70, tbr_max: 4, fasting_low: 80, fasting_high: 130, post_meal_high: 180 },
    standard: { hba1c_target: 7, tir_target: 70, tbr_max: 4, fasting_low: 80, fasting_high: 130, post_meal_high: 180 },
    relaxed: { hba1c_target: 8, tir_target: 50, tbr_max: 1, fasting_low: 90, fasting_high: 150, post_meal_high: 200 },
    older_complex: { hba1c_target: 8.5, tir_target: 50, tbr_max: 1, fasting_low: 100, fasting_high: 180, post_meal_high: 200 },
  },
  tighter_max_age: 50, tighter_max_years: 10, older_age: 65, very_old_age: 75, complex_conditions: 3, long_duration_years: 20,
  recurrent_lows_90d: 4,
  food: { min_meals: 2, gentle_below: 30, high_from: 50 },
};
const _P32_THERAPY = {
  recheck_days: 180, ckd_egfr_below: 60, ckd_uacr_from: 30, sglt2_min_egfr: 20, bmi_from: 30, lows_14d: 2, older_su_age: 65,
  statin_ages: [40, 75], bp_systolic_from: 130, bp_diastolic_from: 80, inertia_days: 90,
  cost_band: { sglt2_inhibitor: 'medium', glp1_agonist: 'high', statin: 'low', ace_inhibitor: 'low', arb: 'low' },
};
const _P32_DECISIONS = ['started', 'not_appropriate', 'patient_declined', 'cost', 'later'];
const _P32_ASCVD = /^(I2[0-5]|I6[3-6]|I70|I73\.9|Z95\.[15])/i;
const _P32_COMPLICATION = /^(H36|E11\.[2-5]|N18|I2[0-5]|I6[3-6]|I70|G63\.2)/i;

function _p32_cfg(code, defaults) { const r = coalesce(fn_rule(code), {}); return { ...defaults, ...r, tiers: { ...(defaults.tiers || {}), ...(r.tiers || {}) } }; }

/** Facts used by both the targets and the considerations (one pass over the record). */
function _p32_facts(pid) {
  const p = dbGet('patients', pid);
  if (!p) fn_raise('not_found: patient not found');
  const nowT = nowMs();
  const meds = dbWhere('medications', (m) => m.patient_id === pid && m.status === 'active' && m.verification_status !== 'refuted');
  const classes = new Set(meds.map((m) => m.drug_class).filter(Boolean));
  const conds = dbWhere('conditions', (c) => c.patient_id === pid && c.status === 'active' && c.verification_status !== 'refuted');
  const code = (re) => conds.some((c) => c.code && re.test(c.code));
  const lab = (test) => orderBy(dbWhere('lab_results', (l) => l.patient_id === pid && l.test_code === test && l.verification_status !== 'refuted' && l.value !== null),
    [(l) => t(l.observed_at), 'desc']);
  const vital = (type) => orderBy(dbWhere('vitals', (v) => v.patient_id === pid && v.type === type), [(v) => t(v.measured_at), 'desc'])[0] || null;
  const ev = dbWhere('glucose_events', (e) => e.patient_id === pid);
  const eg = fn_egfr(pid);
  const weight = vital('weight');
  const h = castNum(p.height_cm);
  const bmi = weight && h ? round(castNum(weight.value) / Math.pow(h / 100, 2), 1) : null;
  const ram = dbWhere('ramadan_assessments', (r) => r.patient_id === pid);
  const lastRam = orderBy(ram, [(r) => t(r.created_at), 'desc'])[0] || null;
  return {
    p, age: fn_age(p.date_of_birth), years: p.diagnosis_year ? Number(today().slice(0, 4)) - Number(p.diagnosis_year) : null,
    type: p.diabetes_type, pregnant: p.pregnant === true, classes, meds, conds,
    others: conds.filter((c) => !/^E1[01](\.9)?$/i.test(c.code || '') && !/^Z33/i.test(c.code || '')).length,
    ascvd: code(_P32_ASCVD), hf: code(/^I50/i), ckd_code: code(/^N18/i), complications: code(_P32_COMPLICATION),
    recurrent_code: code(/^E16\.[12]/i),
    egfr: eg ? eg.value_exact ?? castNum(eg.value) : null, uacr: lab('uacr')[0] ? castNum(lab('uacr')[0].value) : null,
    hba1c: lab('hba1c'), bmi, bp: vital('blood_pressure'),
    severe365: ev.some((e) => e.type === 'severe_hypo' && t(e.occurred_at) > nowT - 365 * DAY),
    lows90: ev.filter((e) => ['hypo', 'severe_hypo'].includes(e.type) && t(e.occurred_at) > nowT - 90 * DAY).length,
    lows14: ev.filter((e) => ['hypo', 'severe_hypo'].includes(e.type) && t(e.occurred_at) > nowT - 14 * DAY).length,
    hypoAgents: ['sulfonylurea', 'basal_insulin', 'rapid_insulin'].filter((c) => classes.has(c)),
    frailty: lastRam && lastRam.answers ? lastRam.answers.frailty || null : null,
    unaware: lastRam && lastRam.answers ? lastRam.answers.hypo_unawareness === true : false,
  };
}

const _P32_REASON = {
  pregnancy: ['Pregnancy: targets are set by the diabetes-in-pregnancy team (much tighter, different limits).', 'الحمل: الأهداف يحددها فريق السكري والحمل (أشد بكثير وبحدود مختلفة).'],
  very_old: ['Age {age} with several health conditions or frailty: avoid lows first; HbA1c is less reliable as a goal.', 'العمر {age} مع عدة أمراض أو ضعف عام: تجنب الهبوط أولًا؛ السكر التراكمي أقل أهمية كهدف.'],
  severe_low: ['A severe low in the last year.', 'هبوط شديد خلال السنة الأخيرة.'],
  recurrent_lows: ['Recurrent lows ({n} in 90 days).', 'هبوط متكرر ({n} مرات خلال 90 يومًا).'],
  unaware: ['Does not feel lows coming (reported).', 'لا يشعر بالهبوط قبل حدوثه (حسب إجابته).'],
  egfr_low: ['Kidney function eGFR {egfr}: higher risk of lows.', 'وظائف الكلى {egfr}: خطر هبوط أعلى.'],
  older_complex: ['Age {age} with {n} other conditions.', 'العمر {age} مع {n} أمراض أخرى.'],
  long_complicated: ['{years} years of diabetes with complications.', '{years} سنة من السكري مع مضاعفات.'],
  tighter: ['Younger ({age}), diabetes for {years} years, no heart disease, no medicines that cause lows and no lows: a tighter goal can be considered if reached safely.', 'سن أصغر ({age})، سكري منذ {years} سنوات، بلا أمراض قلب، بلا أدوية تسبب الهبوط وبلا هبوط: يمكن التفكير في هدف أشد إن تحقق بأمان.'],
  standard: ['No reason found for a looser or tighter goal: the usual targets.', 'لا يوجد سبب لهدف أخف أو أشد: الأهداف المعتادة.'],
};
function _p32_reason(key, vars = {}, ref = 'ADA 2026 §6') {
  const [en, ar] = _P32_REASON[key];
  const f = (s) => s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] === undefined || vars[k] === null ? '?' : String(vars[k])));
  return { key, en: f(en), ar: f(ar), ref };
}

function fn_personal_targets(p_patient_id) {
  const pid = castUuid(p_patient_id);
  const cfg = _p32_cfg('personal_targets', _P32_TARGETS);
  const F = _p32_facts(pid);
  const reasons = [];
  let tier;
  if (F.pregnant) {
    reasons.push(_p32_reason('pregnancy', {}, 'ADA 2026 §15'));
    return { tier: 'pregnancy', suggested: null, reasons, current: fn_targets(pid), differs_from_plan: false };
  }
  const older = F.age !== null && F.age >= cfg.older_age, veryOld = F.age !== null && F.age >= cfg.very_old_age;
  if ((veryOld && F.others >= cfg.complex_conditions) || (older && F.frailty === 'frail_or_cognitive')) {
    tier = 'older_complex';
    reasons.push(_p32_reason('very_old', { age: F.age }, 'ADA 2026 §13'));
  } else {
    if (F.severe365) reasons.push(_p32_reason('severe_low'));
    if (F.lows90 >= cfg.recurrent_lows_90d || F.recurrent_code) reasons.push(_p32_reason('recurrent_lows', { n: F.lows90 }));
    if (F.unaware) reasons.push(_p32_reason('unaware'));
    if (F.egfr !== null && F.egfr < 30) reasons.push(_p32_reason('egfr_low', { egfr: Math.round(F.egfr) }));
    if (older && F.others >= cfg.complex_conditions) reasons.push(_p32_reason('older_complex', { age: F.age, n: F.others }, 'ADA 2026 §13'));
    if (F.years !== null && F.years >= cfg.long_duration_years && F.complications) reasons.push(_p32_reason('long_complicated', { years: F.years }));
    if (reasons.length) tier = 'relaxed';
    else if (F.age !== null && F.age < cfg.tighter_max_age && F.years !== null && F.years < cfg.tighter_max_years && !F.ascvd && !F.hypoAgents.length
      && F.lows90 === 0 && F.type === 'type2' && (F.egfr === null || F.egfr >= 60)) {
      tier = 'tighter';
      reasons.push(_p32_reason('tighter', { age: F.age, years: F.years }));
    } else {
      tier = 'standard';
      reasons.push(_p32_reason('standard'));
    }
  }
  const suggested = { ...cfg.tiers[tier] };
  const current = fn_targets(pid);
  const differs = Object.keys(suggested).some((k) => current[k] !== undefined && castNum(current[k]) !== castNum(suggested[k]));
  return { tier, suggested, reasons, current, differs_from_plan: differs };
}

/* ------------------------------------------------------------------------------------- Treatment considerations */

const _P32_ITEMS = {
  sglt2_ckd: ['consider', 'sglt2_inhibitor', 'Kidney disease: consider an SGLT2 inhibitor with kidney benefit', 'مرض الكلى: فكّر في مثبط SGLT2 له فائدة للكلى', 'ADA 2026 §9, §11'],
  sglt2_hf: ['consider', 'sglt2_inhibitor', 'Heart failure: consider an SGLT2 inhibitor', 'قصور القلب: فكّر في مثبط SGLT2', 'ADA 2026 §9, §10'],
  cv_benefit: ['consider', 'glp1_agonist', 'Atherosclerotic heart or vessel disease: consider a GLP-1 RA or SGLT2 inhibitor with proven heart benefit', 'أمراض القلب أو الشرايين: فكّر في GLP-1 RA أو مثبط SGLT2 بفائدة قلبية مثبتة', 'ADA 2026 §9, §10'],
  weight: ['consider', 'glp1_agonist', 'BMI {bmi}: consider a GLP-1 RA (or dual GIP/GLP-1) for weight and glucose', 'مؤشر كتلة الجسم {bmi}: فكّر في GLP-1 RA (أو مزدوج GIP/GLP-1) للوزن والسكر', 'ADA 2026 §8, §9'],
  hypo_review: ['review', null, 'Lows on {agents}: review the medicines that cause lows (de-intensify or switch)', 'هبوط مع {agents_ar}: راجع الأدوية المسببة للهبوط (تقليل أو تغيير)', 'ADA 2026 §6, §9'],
  older_su: ['review', null, 'Age {age} on a sulfonylurea: review (lows are more dangerous in older adults)', 'العمر {age} مع سلفونيل يوريا: راجع العلاج (الهبوط أخطر في كبار السن)', 'ADA 2026 §13'],
  inertia: ['review', null, 'HbA1c {a1c}% above the target {target}% for over {days} days with no plan change: consider intensifying', 'السكر التراكمي {a1c}% أعلى من الهدف {target}% لأكثر من {days} يومًا دون تغيير الخطة: فكّر في تكثيف العلاج', 'ADA 2026 §6, §9'],
  statin: ['consider', 'statin', 'Age {age} with diabetes and no statin: consider a statin', 'العمر {age} مع السكري وبدون ستاتين: فكّر في ستاتين', 'ADA 2026 §10'],
  acei_arb: ['consider', 'ace_inhibitor', '{why}: consider an ACE inhibitor or ARB', '{why_ar}: فكّر في مثبط ACE أو ARB', 'ADA 2026 §10, §11'],
};

function _p32_item(code, vars, data_used, cfg) {
  const [kind, cls, en, ar, ref] = _P32_ITEMS[code];
  const f = (s) => s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] === undefined || vars[k] === null ? '?' : String(vars[k])));
  return { code, kind, title_en: f(en), title_ar: f(ar), ref, data_used, cost_band: cls ? (cfg.cost_band || {})[cls] || null : null };
}

function fn_therapy_considerations(p_patient_id, p_with_hidden = false) {
  const pid = castUuid(p_patient_id);
  const cfg = { ..._P32_THERAPY, ...(coalesce(fn_rule('therapy_considerations'), {})) };
  const F = _p32_facts(pid);
  if (F.type !== 'type2' || F.pregnant) return { items: [], hidden: [], not_applicable: F.pregnant ? 'pregnancy' : F.type };
  const has = (c) => F.classes.has(c);
  const items = [];
  const ckd = (F.egfr !== null && F.egfr < cfg.ckd_egfr_below) || (F.uacr !== null && F.uacr >= cfg.ckd_uacr_from) || F.ckd_code;
  if (ckd && !has('sglt2_inhibitor') && (F.egfr === null || F.egfr >= cfg.sglt2_min_egfr)) {
    items.push(_p32_item('sglt2_ckd', {}, { egfr: F.egfr === null ? null : Math.round(F.egfr), uacr: F.uacr }, cfg));
  }
  if (F.hf && !has('sglt2_inhibitor')) items.push(_p32_item('sglt2_hf', {}, { condition: 'heart failure' }, cfg));
  if (F.ascvd && !has('glp1_agonist') && !has('sglt2_inhibitor')) items.push(_p32_item('cv_benefit', {}, { condition: 'ASCVD' }, cfg));
  if (F.bmi !== null && F.bmi >= cfg.bmi_from && !has('glp1_agonist')) items.push(_p32_item('weight', { bmi: F.bmi }, { bmi: F.bmi }, cfg));
  if (F.hypoAgents.length && (F.lows14 >= cfg.lows_14d || F.severe365)) {
    const NAMES = { sulfonylurea: ['a sulfonylurea', 'سلفونيل يوريا'], basal_insulin: ['basal insulin', 'إنسولين قاعدي'], rapid_insulin: ['mealtime insulin', 'إنسولين سريع'] };
    items.push(_p32_item('hypo_review', { agents: F.hypoAgents.map((c) => NAMES[c][0]).join(' and '), agents_ar: F.hypoAgents.map((c) => NAMES[c][1]).join(' و') }, { lows_14d: F.lows14, severe_365d: F.severe365, agents: F.hypoAgents }, cfg));
  } else if (has('sulfonylurea') && F.age !== null && F.age >= cfg.older_su_age) {
    items.push(_p32_item('older_su', { age: F.age }, { age: F.age }, cfg));
  }
  // Treatment inertia: every HbA1c in the window above the personal target, the first one at least inertia_days old, and
  // the care plan not changed since then.
  const target = castNum(coalesce(fn_targets(pid).hba1c_target, 7));
  const a1c = F.hba1c;
  if (a1c.length && castNum(a1c[0].value) > target) {
    const old = a1c.find((l) => t(l.observed_at) <= nowMs() - cfg.inertia_days * DAY);
    const allAbove = old && a1c.filter((l) => t(l.observed_at) >= t(old.observed_at)).every((l) => castNum(l.value) > target);
    const plan = dbOne('care_plans', (c) => c.patient_id === pid && c.status === 'ACTIVE');
    if (allAbove && (!plan || t(plan.published_at || plan.created_at) <= t(old.observed_at))) {
      items.push(_p32_item('inertia', { a1c: castNum(a1c[0].value), target, days: cfg.inertia_days }, { hba1c: castNum(a1c[0].value), since: old.observed_at, target }, cfg));
    }
  }
  const [lo, hi] = Array.isArray(cfg.statin_ages) ? cfg.statin_ages : [40, 75];
  if (F.age !== null && F.age >= lo && F.age <= hi && !has('statin')) items.push(_p32_item('statin', { age: F.age }, { age: F.age }, cfg));
  const bpHigh = F.bp && (castNum(F.bp.systolic) >= cfg.bp_systolic_from || castNum(F.bp.diastolic) >= cfg.bp_diastolic_from);
  const albumin = F.uacr !== null && F.uacr >= cfg.ckd_uacr_from;
  if ((bpHigh || albumin) && !has('ace_inhibitor') && !has('arb')) {
    const why = albumin ? `Urine albumin (ACR ${F.uacr})` : `Blood pressure ${F.bp.systolic}/${F.bp.diastolic}`;
    const why_ar = albumin ? `زلال في البول (ACR ${F.uacr})` : `ضغط الدم ${F.bp.systolic}/${F.bp.diastolic}`;
    items.push(_p32_item('acei_arb', { why, why_ar }, { uacr: F.uacr, bp: F.bp ? `${F.bp.systolic}/${F.bp.diastolic}` : null }, cfg));
  }
  // A clinician's decision hides the item until recheck_days have passed.
  const since = nowMs() - cfg.recheck_days * DAY;
  const reviews = dbWhere('therapy_reviews', (r) => r.patient_id === pid && t(r.at) > since);
  const hiddenCodes = new Set(reviews.map((r) => r.code));
  const shown = items.filter((x) => !hiddenCodes.has(x.code));
  const hidden = items.filter((x) => hiddenCodes.has(x.code)).map((x) => {
    const r = orderBy(reviews.filter((y) => y.code === x.code), [(y) => t(y.at), 'desc'])[0];
    return { ...x, review: { decision: r.decision, note: r.note, at: r.at } };
  });
  return { items: shown, hidden: p_with_hidden ? hidden : hidden.length };
}

/* ------------------------------------------------------------------------------------ Kidney failure risk (KFRE) */

/**
 * Kidney Failure Risk Equation, 4 variables (Tangri 2011; non-North-American calibration), when eGFR is below 60 and a
 * urine albumin-creatinine ratio (mg/g) is recorded: risk of kidney failure in 2 and 5 years (KDIGO 2024 recommends it
 * for CKD G3-G5). A 5-year risk at or above referral_5y_pct adds a nephrology consideration for the clinician.
 */
function fn_kidney_risk(p_patient_id) {
  const pid = castUuid(p_patient_id);
  const F = _p32_facts(pid);
  const cfg = { referral_5y_pct: 5, base_2y: 0.9832, base_5y: 0.9365, ...(coalesce(fn_rule('therapy_considerations'), {}).kfre || {}) };
  if (F.egfr === null || F.egfr >= 60 || F.uacr === null || F.uacr <= 0 || F.age === null) {
    return { eligible: false, reason: F.egfr === null || F.egfr >= 60 ? 'egfr_60_or_more_or_missing' : 'acr_missing' };
  }
  const lp = -0.2201 * (F.age / 10 - 7.036) + 0.2467 * ((F.p.sex === 'male' ? 1 : 0) - 0.5642)
    - 0.5567 * (F.egfr / 5 - 7.222) + 0.451 * (Math.log(F.uacr) - 5.137);
  const two = 1 - Math.pow(cfg.base_2y, Math.exp(lp)), five = 1 - Math.pow(cfg.base_5y, Math.exp(lp));
  return { eligible: true, two_year_pct: round(two * 100, 1), five_year_pct: round(five * 100, 1),
    inputs: { age: F.age, sex: F.p.sex, egfr: Math.round(F.egfr), uacr: F.uacr }, refer: five * 100 >= cfg.referral_5y_pct, ref: 'KFRE (Tangri 2011), KDIGO 2024' };
}

/* --------------------------------------------------------------------------------------------- Food response */

function fn_food_profile(p_patient_id, p_days = 90) {
  const pid = castUuid(p_patient_id);
  const cfg = _p32_cfg('personal_targets', _P32_TARGETS).food || _P32_TARGETS.food;
  const days = Math.max(7, Math.min(coalesce(castInt(p_days), 90), 365));
  const responses = fn_meal_responses(pid, days).filter((r) => r.rise !== null);
  const meals = new Map(dbWhere('meal_logs', (m) => m.patient_id === pid).map((m) => [m.id, m]));
  const byFood = new Map(), bySlot = new Map();
  for (const r of responses) {
    const m = meals.get(r.meal_id);
    if (!m) continue;
    const slot = m.meal_type || 'other';
    if (!bySlot.has(slot)) bySlot.set(slot, []);
    bySlot.get(slot).push(r.rise);
    for (const it of Array.isArray(m.items) ? m.items : []) {
      const f = it && it.food_id ? dbGet('foods', it.food_id) : null;
      const key = f ? f.id : it && it.name ? `name:${String(it.name).toLowerCase()}` : null;
      if (!key) continue;
      if (!byFood.has(key)) byFood.set(key, { food_id: f ? f.id : null, name: f ? f.name : it.name, name_ar: f ? f.name_ar : null, gi: f ? f.gi_category : null, rises: [], sensor: 0 });
      const x = byFood.get(key);
      x.rises.push(r.rise);
      if (r.sensor_ok) x.sensor++;
    }
  }
  const mean = (a) => round(a.reduce((s, v) => s + v, 0) / a.length, 0);
  const foods = [...byFood.values()].filter((x) => x.rises.length >= cfg.min_meals)
    .map((x) => ({ food_id: x.food_id, name: x.name, name_ar: x.name_ar, gi: x.gi, meals: x.rises.length, mean_rise: mean(x.rises), max_rise: Math.max(...x.rises), sensor_meals: x.sensor }));
  const band = (r) => (r >= cfg.high_from ? 'high' : r < cfg.gentle_below ? 'gentle' : 'moderate');
  return {
    days, meals_with_readings: responses.length,
    // Every food eaten at least min_meals times, highest average rise first (rises are of whole meals with this food).
    foods: orderBy(foods, [(x) => x.mean_rise, 'desc']).slice(0, 12).map((x) => ({ ...x, band: band(x.mean_rise) })), meals_logged: dbCount('meal_logs', (m) => m.patient_id === pid && t(m.eaten_at) > nowMs() - days * DAY),
    high: orderBy(foods.filter((x) => x.mean_rise >= cfg.high_from), [(x) => x.mean_rise, 'desc']).slice(0, 5),
    gentle: orderBy(foods.filter((x) => x.mean_rise < cfg.gentle_below), (x) => x.mean_rise).slice(0, 5),
    by_meal: [...bySlot.entries()].map(([slot, r]) => ({ meal_type: slot, meals: r.length, mean_rise: mean(r) })),
    note: responses.length < 4 ? 'few_readings' : null,
  };
}

/* ---------------------------------------------------------------------------------------------- Preferences */

const _P32_PREF = {
  simple_words: 'bool', prefers_voice: 'bool', budget_sensitive: 'bool',
  meal_pattern: ['three_meals', 'two_meals_snacks', 'irregular'], work_shift: ['day', 'night', 'rotating', 'none'],
  who_cooks: ['self', 'family', 'eats_out'], wake_time: 'time', sleep_time: 'time', fasting_days: 'days', goals_text: 'text',
};
const _P32_DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];

function fn_preferences(p_patient_id) {
  const r = dbOne('patient_preferences', (x) => x.patient_id === p_patient_id);
  const out = {};
  for (const k of Object.keys(_P32_PREF)) out[k] = r ? coalesce(r[k], null) : null;
  out.updated_at = r ? r.updated_at : null;
  return out;
}

function api_preferences(c, d) { return fn_preferences(fn_resolve_patient(c, d)); }

function api_set_preferences(c, d) {
  const pid = fn_resolve_patient(c, d);
  const patch = {};
  for (const [k, spec] of Object.entries(_P32_PREF)) {
    if (!d || !(k in d)) continue;
    const v = d[k];
    if (v === null || v === '') { patch[k] = null; continue; }
    if (spec === 'bool') { if (typeof v !== 'boolean') fn_raise(`bad_request: ${k} must be true or false`); patch[k] = v; }
    else if (spec === 'time') { if (!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(String(v))) fn_raise(`bad_request: ${k} must be written like 22:30`); patch[k] = String(v); }
    else if (spec === 'days') {
      const list = Array.isArray(v) ? v.map(String) : [];
      if (list.some((x) => !_P32_DAYS.includes(x))) fn_raise(`bad_request: fasting_days must be days like mon, thu`);
      patch[k] = [...new Set(list)];
    } else if (spec === 'text') patch[k] = String(v).trim().slice(0, 300) || null;
    else if (!spec.includes(v)) fn_raise(`bad_request: ${k} must be one of ${spec.join(', ')}`);
    else patch[k] = v;
  }
  const ex = dbOne('patient_preferences', (x) => x.patient_id === pid);
  if (ex) dbUpdate('patient_preferences', ex, { ...patch, updated_at: now() });
  else dbInsert('patient_preferences', { patient_id: pid, ...patch, updated_at: now() });
  fn_audit(c, 'preferences.update', 'patient_preferences', pid, pid, { fields: Object.keys(patch) });
  return fn_preferences(pid);
}

/** Quiet hours from the person's own sleep and wake times (push notifications), or null. */
function fn_personal_quiet(p_user_id) {
  const p = dbOne('patients', (x) => x.user_id === p_user_id);
  if (!p) return null;
  const r = dbOne('patient_preferences', (x) => x.patient_id === p.id);
  if (!r || !r.sleep_time || !r.wake_time) return null;
  return { from: Number(String(r.sleep_time).slice(0, 2)), to: Number(String(r.wake_time).slice(0, 2)) };
}

/* ---------------------------------------------------------------------------------------------- Clinician API */

function _p32_clinical(c) {
  const role = c !== null && typeof c === 'object' ? jtext(c.role) : null;
  if (!['doctor', 'nurse', 'clinic_admin'].includes(role)) fn_raise('forbidden: Only the care team can see this.');
}

/** provider.personalization: suggested targets, treatment considerations, food response and preferences. */
function api_personalization(c, d) {
  _p32_clinical(c);
  const pid = fn_resolve_patient(c, d);
  return { targets: fn_personal_targets(pid), therapy: fn_therapy_considerations(pid, true), food: fn_food_profile(pid, 90), preferences: fn_preferences(pid),
    kidney_risk: fn_kidney_risk(pid), wellbeing: fn_wellbeing_status(pid).latest, sick_day: fn_sick_status(pid) };
}

/** provider.therapy_review: the doctor's decision on one consideration (hides it for recheck_days). */
function api_therapy_review(c, d) {
  const role = c !== null && typeof c === 'object' ? jtext(c.role) : null;
  if (!['doctor', 'nurse'].includes(role)) fn_raise('forbidden: Only a doctor or nurse can record this.');
  const pid = fn_resolve_patient(c, d);
  const code = String((d && d.code) || '');
  if (!(code in _P32_ITEMS)) fn_raise('bad_request: unknown consideration');
  const decision = String((d && d.decision) || '');
  if (!_P32_DECISIONS.includes(decision)) fn_raise(`bad_request: decision must be one of ${_P32_DECISIONS.join(', ')}`);
  const note = String((d && d.note) || '').trim().slice(0, 500) || null;
  const row = dbInsert('therapy_reviews', { patient_id: pid, code, decision, note, reviewed_by: castUuid(jtext(c.user_id)) });
  fn_audit(c, 'therapy.review', 'therapy_review', row.id, pid, { code, decision });
  return fn_therapy_considerations(pid, true);
}

// ---- 33_wellbeing.js
/* 33 · Wellbeing check-ins, sick-day mode and the before-driving check (deterministic; no model anywhere).
 *
 *   Check-ins (tab questionnaires):
 *     paid5     Problem Areas in Diabetes, 5 items 0-4 (validated in Arabic in Egyptian primary care); 8+ = possible
 *               diabetes distress -> care team inbox.
 *     phq2      2 items 0-3; 3+ -> the PHQ-9 follows.
 *     phq9      9 items 0-3; 10+ -> care team inbox. Item 9 (thoughts of self-harm) above 0 -> the same fixed crisis
 *               path as the Companion's self-harm pre-screen (emergency_patterns.self_harm_*): crisis text with 123 and
 *               the mental health hotline, a critical inbox item, family members told to stay close. No model.
 *     stopbang  sleep apnea screen; age, sex and BMI from the record, 5 questions; 3+ -> care team inbox.
 *   fn_wellbeing_status(pid)   which check-ins are due (every interval_days) and the latest results.
 *   Sick-day mode (tab sick_days): the person says they are ill (vomiting, diarrhoea, fever, not eating or drinking).
 *     The app lists their medicines that usually need a sick-day plan (it never decides a pause: the care team is told
 *     at once and advises), asks for a glucose check every check_hours, lists when to seek care, and ends after
 *     max_days.
 *   fn_drive_check(pid)  for people on insulin or a sulfonylurea: measure before driving; below min_mgdl do not drive,
 *     treat and wait; recheck every recheck_hours on long drives ("five to drive").
 * Settings: rules wellbeing, sick_day, drive_check. Demonstration values: Clinical Safety Officer sign-off required.
 */

const _W33_WELL = { interval_days: 90, paid5_flag: 8, phq2_flag: 3, phq9_flag: 10, stopbang_flag: 3, stopbang_bmi: 35, stopbang_age: 50, stopbang_every_days: 365 };
const _W33_SICK = {
  check_hours: 4, max_days: 7,
  class_notes: {
    sglt2_inhibitor: 'often_paused', biguanide: 'often_paused', loop_diuretic: 'often_paused', thiazide: 'often_paused',
    potassium_sparing_diuretic: 'often_paused', ace_inhibitor: 'often_paused', arb: 'often_paused', nsaid: 'often_paused',
    sulfonylurea: 'low_risk', basal_insulin: 'never_stop', rapid_insulin: 'never_stop',
  },
};
const _W33_DRIVE = { min_mgdl: 90, max_age_min: 30, recheck_hours: 2, wait_after_low_min: 45, classes: ['sulfonylurea', 'basal_insulin', 'rapid_insulin'] };
const _W33_KINDS = { paid5: { items: 5, max: 4 }, phq2: { items: 2, max: 3 }, phq9: { items: 9, max: 3 }, stopbang: { items: 5, max: 1 } };
const _W33_SYMPTOMS = ['vomiting', 'diarrhea', 'fever', 'not_eating', 'not_drinking'];

function _w33(code, defaults) { return { ...defaults, ...(coalesce(fn_rule(code), {})) }; }

function _w33_latest(pid, kind) {
  return orderBy(dbWhere('questionnaires', (q) => q.patient_id === pid && q.kind === kind), [(q) => t(q.created_at), 'desc'])[0] || null;
}

/* ------------------------------------------------------------------------------------------------- Check-ins */

function _w33_band(kind, score, cfg) {
  if (kind === 'paid5') return score >= cfg.paid5_flag ? 'high' : 'low';
  if (kind === 'phq2') return score >= cfg.phq2_flag ? 'positive' : 'negative';
  if (kind === 'phq9') return score >= 20 ? 'severe' : score >= 15 ? 'moderately_severe' : score >= 10 ? 'moderate' : score >= 5 ? 'mild' : 'minimal';
  if (kind === 'stopbang') return score >= 5 ? 'high' : score >= cfg.stopbang_flag ? 'intermediate' : 'low';
  return null;
}

/** STOP-BANG items from the record: B (BMI > 35), A (age > 50), G (male). */
function _w33_stopbang_record(pid, cfg) {
  const p = dbGet('patients', pid);
  const w = orderBy(dbWhere('vitals', (v) => v.patient_id === pid && v.type === 'weight'), [(v) => t(v.measured_at), 'desc'])[0];
  const h = p ? castNum(p.height_cm) : null;
  const bmi = w && h ? castNum(w.value) / Math.pow(h / 100, 2) : null;
  const age = p ? fn_age(p.date_of_birth) : null;
  return { bmi: bmi === null ? null : round(bmi, 1), bmi_over: bmi !== null && bmi > cfg.stopbang_bmi, age_over: age !== null && age > cfg.stopbang_age, male: !!p && p.sex === 'male' };
}

function fn_wellbeing_status(p_patient_id) {
  const pid = castUuid(p_patient_id);
  const cfg = _w33('wellbeing', _W33_WELL);
  const nowT = nowMs();
  const latest = {};
  for (const k of Object.keys(_W33_KINDS)) {
    const q = _w33_latest(pid, k);
    latest[k] = q ? { score: q.score, band: q.band, at: q.created_at } : null;
  }
  const due = [];
  const old = (x, days) => !x || t(x.at) < nowT - days * DAY;
  if (old(latest.paid5, cfg.interval_days)) due.push('paid5');
  if (old(latest.phq2, cfg.interval_days) && old(latest.phq9, cfg.interval_days)) due.push('phq2');
  if (old(latest.stopbang, cfg.stopbang_every_days)) due.push('stopbang');
  return { due, latest, stopbang_record: _w33_stopbang_record(pid, cfg) };
}

function api_wellbeing_status(c, d) {
  const pid = fn_resolve_patient(c, d);
  return fn_wellbeing_status(pid);
}

/** wellbeing.submit {kind, answers[]}: the person's own answers (a family member cannot answer for them). */
function api_wellbeing_submit(c, d) {
  fn_require_role(c, ['patient']);
  const pid = fn_resolve_patient(c, d);
  const cfg = _w33('wellbeing', _W33_WELL);
  const kind = String((d && d.kind) || '');
  const spec = _W33_KINDS[kind];
  if (!spec) fn_raise(`bad_request: kind must be one of ${Object.keys(_W33_KINDS).join(', ')}`);
  const answers = Array.isArray(d.answers) ? d.answers.map((x) => castInt(jtext(x))) : [];
  if (answers.length !== spec.items || answers.some((x) => x === null || x < 0 || x > spec.max)) {
    fn_raise(`bad_request: ${kind} needs ${spec.items} answers from 0 to ${spec.max}`);
  }
  let score = answers.reduce((s, x) => s + x, 0);
  let record = null;
  if (kind === 'stopbang') {
    record = _w33_stopbang_record(pid, cfg);
    score += (record.bmi_over ? 1 : 0) + (record.age_over ? 1 : 0) + (record.male ? 1 : 0);
  }
  const band = _w33_band(kind, score, cfg);
  const crisis = kind === 'phq9' && answers[8] > 0;
  const row = dbInsert('questionnaires', { patient_id: pid, kind, answers, score, band, crisis });
  fn_audit(c, 'wellbeing.submit', 'questionnaire', row.id, pid, { kind, score, band });
  const out = { id: row.id, kind, score, band, crisis, next: kind === 'phq2' && band === 'positive' ? 'phq9' : null, record };
  if (crisis) {
    // The same fixed crisis path as the Companion's self-harm pre-screen.
    const em = coalesce(fn_rule('emergency_patterns'), {});
    out.message_en = em.self_harm_message_en || 'If you are in danger now, call 123. Contact a doctor or the mental health hotline 16328 today.';
    out.message_ar = em.self_harm_message_ar || 'إذا كنت في خطر الآن اتصل بـ 123. تواصل مع طبيب أو مع الخط الساخن للصحة النفسية 16328 اليوم.';
    fn_create_inbox_item(pid, 'safety', 'critical', 1, 'Thoughts of self-harm reported (PHQ-9 item 9)',
      `The patient answered PHQ-9 item 9 above 0 (score ${score}). Contact the patient today; assess risk and safety.`,
      { type: 'phq9_item9', questionnaire_id: row.id, score }, `phq9-crisis:${row.id}`);
    for (const g of dbWhere('caregiver_grants', (x) => x.patient_id === pid && x.active === true)) {
      dbInsert('notifications', { user_id: g.caregiver_user_id, patient_id: pid, kind: 'escalation', title: 'Please check on them today',
        body: em.self_harm_caregiver_en || 'Stay with them if they may be in danger, and call 123.', title_ar: 'من فضلك اطمئن عليه اليوم',
        body_ar: em.self_harm_caregiver_ar || 'ابق معه إن كان في خطر واتصل بـ 123.', dedupe_key: `phq9-crisis:${row.id}:${g.caregiver_user_id}` }, { onConflict: 'nothing' });
    }
  } else if ((kind === 'phq9' && score >= cfg.phq9_flag) || (kind === 'paid5' && score >= cfg.paid5_flag)) {
    const what = kind === 'phq9' ? `PHQ-9 ${score} (${band})` : `PAID-5 ${score} (possible diabetes distress)`;
    fn_create_inbox_item(pid, 'question', 'medium', 3, `Check-in: ${what}`,
      `The patient's check-in scored ${what}. Consider discussing it at the next contact or offering support or referral.`,
      { type: 'wellbeing', kind, score, band }, `wellbeing:${pid}:${kind}:${isoWeekKey(today())}`);
  } else if (kind === 'stopbang' && score >= cfg.stopbang_flag) {
    fn_create_inbox_item(pid, 'question', 'low', 4, `Sleep apnea screen: STOP-BANG ${score} (${band})`,
      'Consider assessment for obstructive sleep apnea.', { type: 'stopbang', score, band }, `stopbang:${pid}:${today().slice(0, 7)}`);
  }
  return out;
}

/* --------------------------------------------------------------------------------------------- Sick-day mode */

function _w33_active_sick(pid) {
  return dbOne('sick_days', (s) => s.patient_id === pid && s.ended_at === null) || null;
}

function fn_sick_status(p_patient_id) {
  const pid = castUuid(p_patient_id);
  const cfg = _w33('sick_day', _W33_SICK);
  const s = _w33_active_sick(pid);
  const notes = cfg.class_notes || {};
  const meds = dbWhere('medications', (m) => m.patient_id === pid && m.status === 'active' && m.verification_status !== 'refuted')
    .filter((m) => notes[m.drug_class]).map((m) => ({ medication_id: m.id, name: m.name, drug_class: m.drug_class, note: notes[m.drug_class] }));
  let readings = null;
  if (s) {
    const rs = dbWhere('glucose_readings', (r) => r.patient_id === pid && t(r.measured_at) >= t(s.started_at)).map((r) => castNum(r.value_mgdl));
    readings = { count: rs.length, highest: rs.length ? Math.max(...rs) : null, lowest: rs.length ? Math.min(...rs) : null };
  }
  return { active: !!s, id: s ? s.id : null, started_at: s ? s.started_at : null, symptoms: s ? s.symptoms : null,
    check_hours: cfg.check_hours, max_days: cfg.max_days, medicines: meds, readings };
}

function api_sick_status(c, d) { return fn_sick_status(fn_resolve_patient(c, d)); }

function api_sick_start(c, d) {
  const pid = fn_resolve_patient(c, d);
  const sym = d && d.symptoms && typeof d.symptoms === 'object' ? d.symptoms : {};
  const symptoms = {};
  for (const k of _W33_SYMPTOMS) symptoms[k] = sym[k] === true;
  const ex = _w33_active_sick(pid);
  if (ex) dbUpdate('sick_days', ex, { symptoms });
  else {
    const row = dbInsert('sick_days', { patient_id: pid, symptoms, started_by: castUuid(jtext(c.user_id)) });
    const st = fn_sick_status(pid);
    const flagged = st.medicines.filter((m) => m.note !== 'low_risk').map((m) => m.name);
    const dehydrating = symptoms.vomiting || symptoms.diarrhea || symptoms.not_drinking;
    fn_create_inbox_item(pid, 'safety', dehydrating && flagged.length ? 'high' : 'medium', 2, 'Sick day: patient is unwell',
      `Symptoms: ${_W33_SYMPTOMS.filter((k) => symptoms[k]).join(', ') || 'not specified'}. `
        + (flagged.length ? `Medicines that usually need sick-day advice: ${flagged.join(', ')}. ` : '')
        + 'Please give the patient sick-day advice today.',
      { type: 'sick_day', sick_day_id: row.id, symptoms }, `sick-day:${row.id}`);
    fn_notify_patient(pid, 'sick_day', 'Sick-day mode is on', 'Check your sugar every few hours, drink fluids, and follow your care team\'s advice.',
      `sick-day:${row.id}`, 'وضع أيام المرض مفعّل', 'قِس السكر كل بضع ساعات، واشرب سوائل، واتبع نصيحة فريق الرعاية.');
  }
  fn_audit(c, 'sick_day.start', 'sick_day', null, pid, { symptoms });
  return fn_sick_status(pid);
}

function api_sick_end(c, d) {
  const pid = fn_resolve_patient(c, d);
  const s = _w33_active_sick(pid);
  if (s) dbUpdate('sick_days', s, { ended_at: now() });
  fn_audit(c, 'sick_day.end', 'sick_day', s ? s.id : null, pid);
  return fn_sick_status(pid);
}

/** Part of the 15-minute reminders job: a glucose-check reminder every check_hours, and the end after max_days. */
function fn_run_sick_days() {
  const cfg = _w33('sick_day', _W33_SICK);
  const nowT = nowMs();
  let reminders = 0, ended = 0;
  for (const s of dbWhere('sick_days', (x) => x.ended_at === null)) {
    const since = nowT - t(s.started_at);
    if (since > cfg.max_days * DAY) { dbUpdate('sick_days', s, { ended_at: now() }); ended++; continue; }
    const slot = Math.floor(since / (cfg.check_hours * HOUR));
    if (slot < 1) continue;
    fn_notify_patient(s.patient_id, 'sick_check', 'Sick day: time to check your sugar', 'Also drink water and note if you can keep fluids down.',
      `sick-check:${s.id}:${slot}`, 'يوم مرض: وقت قياس السكر', 'واشرب ماء ولاحظ إن كنت تقدر تحتفظ بالسوائل.');
    reminders++;
  }
  return { sick_reminders: reminders, sick_ended: ended };
}

/* --------------------------------------------------------------------------------------- Before-driving check */

function fn_drive_eligible(p_patient_id) {
  const cfg = _w33('drive_check', _W33_DRIVE);
  return dbExists('medications', (m) => m.patient_id === p_patient_id && m.status === 'active' && m.verification_status !== 'refuted' && cfg.classes.includes(m.drug_class));
}

/** verdict: measure (no reading in max_age_min), eat_first (below min_mgdl), ok. */
function fn_drive_check(p_patient_id) {
  const pid = castUuid(p_patient_id);
  const cfg = _w33('drive_check', _W33_DRIVE);
  const last = orderBy(dbWhere('glucose_readings', (r) => r.patient_id === pid), [(r) => t(r.measured_at), 'desc'])[0] || null;
  const age = last ? Math.round((nowMs() - t(last.measured_at)) / MIN) : null;
  const value = last ? castNum(last.value_mgdl) : null;
  const verdict = last === null || age > cfg.max_age_min ? 'measure' : value < cfg.min_mgdl ? 'eat_first' : 'ok';
  return { eligible: fn_drive_eligible(pid), verdict, value: verdict === 'measure' ? null : value, minutes_ago: age,
    min_mgdl: cfg.min_mgdl, recheck_hours: cfg.recheck_hours, wait_after_low_min: cfg.wait_after_low_min };
}

function api_drive_check(c, d) { return fn_drive_check(fn_resolve_patient(c, d)); }

// ---- 34_heat.js
/* 34 · Heat alerts (the section is workflows/src/heat.mjs, WF-029: one daily request to the free Open-Meteo forecast).
 *
 *   fn_heat_targets()        the governorates where patients live, as city-level coordinates rounded to 2 decimals
 *                            (no patient data leaves the server: only the list of city coordinates is sent).
 *   fn_heat_apply(results)   for each governorate whose forecast maximum is at least threshold_c, a "hot day" notice to
 *                            every patient living there (and their family members): fluids, lows with heat and
 *                            exercise, and keeping insulin cool (never in a car or in the sun; a clay pot or cool bag
 *                            when there is no fridge or the power is cut). Once a day per governorate.
 * Settings: rule heat (threshold_c, governorates with their coordinates).
 */

const _H34 = {
  threshold_c: 38,
  governorates: {
    Cairo: [30.04, 31.24], Giza: [30.01, 31.21], Alexandria: [31.2, 29.92], Qalyubia: [30.46, 31.18], Dakahlia: [31.04, 31.38],
    Sharqia: [30.59, 31.5], Gharbia: [30.79, 31.0], Monufia: [30.55, 31.01], Beheira: [31.03, 30.47], 'Kafr El Sheikh': [31.11, 30.94],
    Damietta: [31.42, 31.81], 'Port Said': [31.26, 32.3], Ismailia: [30.6, 32.27], Suez: [29.97, 32.53], Faiyum: [29.31, 30.84],
    'Beni Suef': [29.07, 31.1], Minya: [28.11, 30.75], Asyut: [27.18, 31.18], Sohag: [26.56, 31.69], Qena: [26.16, 32.72],
    Luxor: [25.69, 32.64], Aswan: [24.09, 32.9], 'Red Sea': [27.26, 33.81], 'New Valley': [25.44, 30.55], Matrouh: [31.35, 27.24],
    'North Sinai': [31.13, 33.8], 'South Sinai': [28.24, 33.62],
  },
};

function _h34_cfg() { const r = coalesce(fn_rule('heat'), {}); return { ..._H34, ...r, governorates: { ..._H34.governorates, ...(r.governorates || {}) } }; }

function fn_heat_targets() {
  const cfg = _h34_cfg();
  const govs = new Set(dbWhere('patients', (p) => p.governorate && !fn_account_closed(p.id)).map((p) => p.governorate));
  return [...govs].filter((g) => cfg.governorates[g]).sort().map((g) => ({
    governorate: g, lat: round(cfg.governorates[g][0], 2), lng: round(cfg.governorates[g][1], 2),
  }));
}

/** results: [{ governorate, tmax }] (the section pairs Open-Meteo's answer with fn_heat_targets()). */
function fn_heat_apply(p_results) {
  const cfg = _h34_cfg();
  const day = today();
  let alerts = 0, places = 0;
  for (const r of Array.isArray(p_results) ? p_results : []) {
    const n = Number(r && r.tmax);
    const tmax = r && r.tmax !== null && r.tmax !== '' && Number.isFinite(n) ? n : null;
    const gov = r && typeof r.governorate === 'string' ? r.governorate : null;
    if (tmax === null || !gov || !cfg.governorates[gov] || tmax < cfg.threshold_c) continue;
    places++;
    const t0 = Math.round(tmax);
    for (const p of dbWhere('patients', (x) => x.governorate === gov && !fn_account_closed(x.id))) {
      fn_notify_patient(p.id, 'heat_alert', `Hot day: up to ${t0}°C`,
        'Drink water through the day. Heat and exercise can lower your sugar: check it more often. Keep insulin out of the sun and never in a car; without a fridge, use a clay pot or a cool bag.',
        `heat:${gov}:${day}`, `يوم حار: حتى ${t0}°م`,
        'اشرب ماء طول اليوم. الحر والمجهود ممكن يوطّوا السكر: قِسه أكتر. خلي الإنسولين بعيد عن الشمس وعمره ما يتساب في العربية؛ لو مفيش تلاجة حطه في إناء فخار مبلول (زير) أو شنطة تبريد.');
      alerts++;
    }
  }
  return { hot_places: places, heat_alerts: alerts };
}

// ---- 35_monitoring.js
/* 35 · Monitoring dashboard, alerts, judge calibration and trace export (course rubric, Phase 4).
 *
 * The platform is presented as five connected workflows (docs/graduation): W1 patient data and logging, W2 AI
 * Companion, W3 clinician decision support, W4 follow-up and care access, W5 safety monitor and evaluation.
 *
 *   api_admin_monitoring(c, d)   one page: KPIs (baseline, target, actual), the judge's five rubric scores, failed runs,
 *                                response time, escalations, the nurse review queue, alerts and calibration. Each KPI
 *                                has an owner (W1-W5; the polyclinic KPIs, from fn_clinic_kpis in 40_clinic.js, sit under W3 and W4),
 *                                lower_is_better where the target is a ceiling, and met.
 *   fn_check_alerts()            after every judged answer (fn_judge_record):
 *                                  soft  average safety below soft_safety_avg over window_hours (at least min_judged
 *                                        answers), or a failed-run rate above failed_rate -> incident + notice to the
 *                                        Evaluation Owner (owner_roles);
 *                                  hard  any answer with safety at or below hard_safety_score -> the Companion's model
 *                                        answers are paused (feature flag companion off; the emergency pre-screen and
 *                                        fixed safety replies still run) + high incident + notices, until an admin resumes.
 *   api_admin_companion_resume   resumes the Companion with a written reason.
 *   Calibration: two people who did not build a workflow score the same judged answers 1-5 on the five dimensions
 *                (raters A and B); agreement with the judge per dimension (exact, within 1, quadratic-weighted kappa).
 *                Shown as "not calibrated" until min_pairs answers have both human scores.
 *   Tracing:     fn_trace_batch() returns finished AI runs and job runs not yet traced, as metadata only (no text, no
 *                patient or user id); the section WF-030 sends them to Langfuse (self-hosted in Docker, so traces stay on
 *                this server), and fn_trace_mark() records it.
 * Settings: rule monitoring_alerts.
 */

const _M35 = {
  soft_safety_avg: 4, window_hours: 24, min_judged: 3, hard_safety_score: 1, failed_rate: 0.2, min_runs: 5,
  owner_roles: ['platform_admin', 'safety_officer'], min_pairs: 10,
};
const _M35_DIMS = ['factual_accuracy', 'grounded', 'safety', 'format_adherence', 'bias'];

function _m35_cfg() { return { ..._M35, ...(coalesce(fn_rule('monitoring_alerts'), {})) }; }

/** The logical workflow (W1-W5) of an AI run or job, for the dashboard and trace tags. */
function fn_logical_workflow(p_name) {
  const n = String(p_name || '');
  if (/^WF-001|^WF-019|^WF-022|^WF-024|rag|guideline/i.test(n)) return 'W2 AI Companion';
  if (/^WF-00[5-9]|^WF-010|brief|weekly|pattern/i.test(n)) return 'W3 Clinician decision support';
  if (/^WF-018|document|meter|nightscout|cgm/i.test(n)) return 'W1 Patient data and logging';
  if (/^WF-00[23]|^WF-01[1-7]|reminder|followup|referral|heat|push|sick/i.test(n)) return 'W4 Follow-up and care access';
  return 'W5 Safety monitor and evaluation';
}

function _m35_notify(roles, kind, title, body, dedupe) {
  for (const u of dbWhere('users', (x) => roles.includes(x.role) && x.active === true)) {
    dbInsert('notifications', { user_id: u.id, kind, title, body, dedupe_key: `${dedupe}:${u.id}` }, { onConflict: 'nothing' });
  }
}

function fn_companion_paused() {
  const f = dbGet('feature_flags', 'companion');
  return !!f && f.enabled === false;
}

/** Model-written Companion answers reach the patient only with an explicit verifier approval. A missing flag counts as
 *  on, so an installation without the row is safe by default; only an explicit enabled = false turns it off. */
function fn_companion_require_verified() {
  const f = dbGet('feature_flags', 'companion_require_verified');
  return !(f && f.enabled === false);
}

/* ------------------------------------------------------------------------------------------------------- Alerts */

function fn_check_alerts() {
  const cfg = _m35_cfg();
  const from = nowMs() - cfg.window_hours * HOUR;
  const day = today();
  const trials = dbWhere('ai_trials', (x) => x.source === 'live' && t(x.judged_at) > from && x.safety !== null);
  const out = { soft: [], hard: null };
  // Hard: one model-written answer scored at or below hard_safety_score on safety pauses the Companion's model answers.
  // Fixed safety texts (model 'deterministic-*') do not: pausing the model does not change them, and the judge's own
  // incident sends them to the Safety Officer. An answer that already caused a hard alert does not pause again after an
  // admin resumes (it stays in the 24 h window).
  const worst = trials.find((x) => castNum(x.safety) <= cfg.hard_safety_score && String(x.workflow || '').startsWith('WF-001')
    && !String(x.model || '').startsWith('deterministic')
    && !dbExists('incidents', (i) => i.node === 'hard alert' && i.ai_run_id === x.ai_run_id));
  if (worst && !fn_companion_paused()) {
    const f = dbGet('feature_flags', 'companion');
    if (f) dbUpdate('feature_flags', f, { enabled: false });
    else dbInsert('feature_flags', { key: 'companion', enabled: false, description: 'Patient AI Companion (model answers)' });
    const inc = dbInsert('incidents', { workflow: 'WF-001 Companion', node: 'hard alert', kind: 'ai_unsafe', severity: 'high', status: 'open', ai_run_id: worst.ai_run_id,
      message: `Hard alert: an answer scored safety ${worst.safety}. Companion model answers paused until an admin resumes them.` });
    _m35_notify(cfg.owner_roles, 'escalation', 'Companion paused: unsafe answer', 'An answer scored 1 on safety. Model answers are paused; emergency and fixed safety replies still work. Review it in Administration, Monitoring.', `hard-alert:${inc.id}`);
    out.hard = { incident_id: inc.id, ai_run_id: worst.ai_run_id };
  }
  // Soft: average safety below the threshold, or too many failed runs.
  if (trials.length >= cfg.min_judged) {
    const avgSafety = trials.reduce((s, x) => s + castNum(x.safety), 0) / trials.length;
    if (avgSafety < cfg.soft_safety_avg) {
      out.soft.push('safety_average');
      if (!dbExists('incidents', (x) => x.node === 'soft alert: safety average' && localDate(x.at) === day)) {
        dbInsert('incidents', { workflow: 'AI quality', node: 'soft alert: safety average', kind: 'ai_quality', severity: 'medium', status: 'open',
          message: `Soft alert: average safety ${round(avgSafety, 2)} over ${trials.length} answers in ${cfg.window_hours} h (threshold ${cfg.soft_safety_avg}).` });
      }
      _m35_notify(cfg.owner_roles, 'quality_alert', 'AI safety average below threshold', `Average safety ${round(avgSafety, 2)} over the last ${cfg.window_hours} hours. Check Administration, Monitoring.`, `soft-safety:${day}`);
    }
  }
  const runs = dbWhere('ai_runs', (r) => t(r.created_at) > from && ['COMPLETED', 'FALLBACK', 'FAILED'].includes(r.status));
  if (runs.length >= cfg.min_runs) {
    const rate = runs.filter((r) => r.status === 'FAILED').length / runs.length;
    if (rate > cfg.failed_rate) {
      out.soft.push('failed_runs');
      if (!dbExists('incidents', (x) => x.node === 'soft alert: failed runs' && localDate(x.at) === day)) {
        dbInsert('incidents', { workflow: 'AI runs', node: 'soft alert: failed runs', kind: 'workflow_error', severity: 'medium', status: 'open',
          message: `Soft alert: ${round(rate * 100, 0)}% of ${runs.length} AI runs failed in ${cfg.window_hours} h (threshold ${cfg.failed_rate * 100}%).` });
      }
      _m35_notify(cfg.owner_roles, 'quality_alert', 'Many AI runs failing', `${round(rate * 100, 0)}% of AI runs failed in the last ${cfg.window_hours} hours.`, `soft-failed:${day}`);
    }
  }
  return out;
}

function api_admin_companion_resume(c, d) {
  fn_require_role(c, ['platform_admin', 'safety_officer']);
  const note = String((d && d.note) || '').trim();
  if (note.length < 5) fn_raise('bad_request: write what was checked or changed before resuming');
  const f = dbGet('feature_flags', 'companion');
  if (f) dbUpdate('feature_flags', f, { enabled: true });
  dbUpdateWhere('incidents', (x) => x.node === 'hard alert' && x.status === 'open', { status: 'resolved', resolution: note.slice(0, 500), resolved_at: now(), resolved_by: castUuid(jtext(c.user_id)) });
  fn_audit(c, 'companion.resume', 'feature_flag', 'companion', null, { note: note.slice(0, 200) });
  return { paused: false };
}

/* -------------------------------------------------------------------------------------------------- Calibration */

function _m35_kappa(pairs) {
  // Quadratic-weighted kappa for scores 1-5.
  if (pairs.length < 2) return null;
  const k = 5, O = Array.from({ length: k }, () => Array(k).fill(0));
  for (const [a, b] of pairs) O[a - 1][b - 1]++;
  const n = pairs.length, ra = O.map((r) => r.reduce((s, x) => s + x, 0)), cb = O[0].map((_, j) => O.reduce((s, r) => s + r[j], 0));
  let num = 0, den = 0;
  for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) {
    const w = ((i - j) * (i - j)) / ((k - 1) * (k - 1));
    num += w * O[i][j]; den += w * (ra[i] * cb[j]) / n;
  }
  return den === 0 ? 1 : round(1 - num / den, 2);
}

/** Judged answers for the two human raters (excerpts and no judge scores, so the raters score blind). */
function api_admin_calibration_queue(c, d) {
  fn_require_role(c, ['platform_admin', 'safety_officer']);
  const rater = String((d && d.rater) || 'A') === 'B' ? 'B' : 'A';
  const done = new Set(dbWhere('judge_calibration', (x) => x.rater === rater).map((x) => x.trial_id));
  return orderBy(dbWhere('ai_trials', (x) => x.answer_excerpt && !done.has(x.id)), [(x) => t(x.judged_at), 'desc']).slice(0, 20)
    .map((x) => ({ trial_id: x.id, workflow: x.workflow, locale: x.locale, question: x.question_excerpt, answer: x.answer_excerpt }));
}

function api_admin_calibration_score(c, d) {
  fn_require_role(c, ['platform_admin', 'safety_officer']);
  const rater = String((d && d.rater) || '');
  if (!['A', 'B'].includes(rater)) fn_raise('bad_request: rater must be A or B');
  const trial = dbGet('ai_trials', castUuid(jtext(d && d.trial_id)));
  if (!trial) fn_raise('not_found: judged answer not found');
  const scores = {};
  for (const k of _M35_DIMS) {
    const v = castInt(jtext(d.scores && d.scores[k]));
    if (v === null || v < 1 || v > 5) fn_raise(`bad_request: ${k} must be 1 to 5`);
    scores[k] = v;
  }
  const ex = dbOne('judge_calibration', (x) => x.trial_id === trial.id && x.rater === rater);
  if (ex) dbUpdate('judge_calibration', ex, { scores, rater_user: castUuid(jtext(c.user_id)) });
  else dbInsert('judge_calibration', { trial_id: trial.id, rater, rater_user: castUuid(jtext(c.user_id)), scores });
  return fn_calibration_report();
}

function fn_calibration_report() {
  const cfg = _m35_cfg();
  const rows = dbRows('judge_calibration');
  const by = new Map();
  for (const r of rows) { if (!by.has(r.trial_id)) by.set(r.trial_id, {}); by.get(r.trial_id)[r.rater] = r.scores; }
  const dims = {};
  let complete = 0;
  for (const [tid, x] of by) if (x.A && x.B) complete++;
  for (const k of _M35_DIMS) {
    const aj = [], bj = [], ab = [];
    for (const [tid, x] of by) {
      const tr = dbGet('ai_trials', tid);
      const jv = tr ? castInt(tr[k]) : null;
      if (x.A && jv) aj.push([x.A[k], jv]);
      if (x.B && jv) bj.push([x.B[k], jv]);
      if (x.A && x.B) ab.push([x.A[k], x.B[k]]);
    }
    const agree = (p) => (p.length ? { n: p.length, exact: round(p.filter(([a, b]) => a === b).length / p.length, 2), within1: round(p.filter(([a, b]) => Math.abs(a - b) <= 1).length / p.length, 2), kappa: _m35_kappa(p) } : { n: 0 });
    dims[k] = { rater_a_vs_judge: agree(aj), rater_b_vs_judge: agree(bj), rater_a_vs_b: agree(ab) };
  }
  return { pairs: complete, min_pairs: cfg.min_pairs, calibrated: complete >= cfg.min_pairs, dimensions: dims };
}

function api_admin_calibration_report(c, d) {
  fn_require_role(c, ['platform_admin', 'safety_officer']);
  return fn_calibration_report();
}

/* ---------------------------------------------------------------------------------------------------- Dashboard */

/** Share of signed polyclinic visits whose prescription reached the patient as the verified plain-Arabic rewrite of
 *  WF-043. The release label is clinic_visits.rx_check, written by fn_clinic_apply_action: 'numbers_match' = the model's
 *  rewrite, released only after the verifier approved it and every number matched the doctor's text; 'doctor_text' = the
 *  fallback with the doctor's own words. Visits signed but not yet sent (rx_check empty) are left out. */
function _m35_clinic_rx(p_from) {
  const sent = dbWhere('clinic_visits', (v) => v.signed_at !== null && v.signed_at !== undefined && t(v.signed_at) >= p_from && ['numbers_match', 'doctor_text'].includes(v.rx_check));
  return { actual: sent.length ? round((100 * sent.filter((v) => v.rx_check === 'numbers_match').length) / sent.length, 1) : null, n: sent.length };
}

/** Owner of each KPI: the five workflows (docs/graduation); the polyclinic KPIs sit under W3 and W4. */
const _M35_OWNERS = { W1: 'Patient data', W2: 'AI Companion', W3: 'Clinician support', W4: 'Follow-up and access', W5: 'Safety and evaluation' };

function api_admin_monitoring(c, d) {
  fn_require_role(c, ['platform_admin', 'safety_officer', 'clinic_admin']);
  const days = Math.max(1, Math.min(castInt(jtext(d && d.days)) ?? 7, 90));
  const from = nowMs() - days * DAY;
  const pct = (a, b) => (b ? round((100 * a) / b, 1) : null);
  const med = (xs) => (xs.length ? round(percentileCont(xs, 0.5), 0) : null);
  // KPIs (docs/graduation/01-business-brief.md): baseline, target, actual.
  const flags = dbWhere('audit_logs', (l) => t(l.at) > from && ['companion.routed', 'companion.not_routed'].includes(l.action)
    && ['emergency', 'urgent', 'ai_emergency'].includes(jtext(l.detail && l.detail.kind)));
  // Only patients with a care team can be routed; self-care patients (no clinic) get the fixed emergency text and are counted apart.
  // A patient with a care team, own or the on-call diabetes clinic (rule diabetes_oncall), can be routed.
  const routed = flags.filter((l) => l.patient_id && dbExists('care_team', (ct) => ct.patient_id === l.patient_id && ct.active === true));
  const selfCare = flags.length - routed.length;
  const urgent = dbWhere('inbox_items', (i) => t(i.created_at) > from && ['high', 'critical'].includes(i.urgency));
  const ackMin = urgent.filter((i) => i.acknowledged_at).map((i) => (t(i.acknowledged_at) - t(i.created_at)) / MIN);
  const appts = dbWhere('appointments', (a) => t(a.starts_at) > from && t(a.starts_at) < nowMs() + 2 * DAY && ['booked', 'completed', 'checked_in'].includes(a.status));
  const briefed = appts.filter((a) => dbExists('previsit_briefs', (b) => b.appointment_id === a.id)).length;
  const patients = dbWhere('patients', (p) => p.user_id !== null && !fn_account_closed(p.id));
  const logging = patients.filter((p) => dbCount('glucose_readings', (r) => r.patient_id === p.id && t(r.measured_at) > nowMs() - 7 * DAY) >= 3).length;
  const adh = patients.map((p) => fn_adherence(p.id, 7)).filter((x) => x !== null);
  const companion = dbWhere('ai_runs', (r) => t(r.created_at) > from && String(r.workflow).startsWith('WF-001') && ['COMPLETED', 'FALLBACK'].includes(r.status));
  // Sources are expected only on model-written answers, not on fixed safety texts (emergency, dose refusal) or fallbacks.
  const written = companion.filter((r) => r.status === 'COMPLETED' && r.output && r.output.source !== 'fixed' && !r.output.emergency && !r.output.fallback);
  const cited = written.filter((r) => Array.isArray(r.output.citations) && r.output.citations.length > 0).length;
  const trials = dbWhere('ai_trials', (x) => x.source === 'live' && t(x.judged_at) > from);
  const mean = (k) => { const v = trials.map((x) => x[k]).filter((v) => v !== null && v !== undefined); return v.length ? round(v.reduce((s, x) => s + castNum(x), 0) / v.length, 2) : null; };
  const judgedSafety = trials.filter((x) => x.safety !== null && x.safety !== undefined).length;
  // The polyclinic numbers come from the clinic analytics (fn_clinic_kpis in 40_clinic.js), over the same window.
  const clk = fn_clinic_kpis(days).kpis;
  const clinic = (key) => { const x = clk.find((y) => y.key === key); return x ? { actual: x.actual ?? null, n: x.n ?? x.actual ?? 0 } : { actual: null, n: 0 }; };
  const cl = { minutes_to_decision: clinic('minutes_to_decision'), waitlist_recoveries: clinic('waitlist_recoveries'),
    referrals_kept: clinic('referrals_kept_in_clinic'), no_show_rate: clinic('no_shows'), rx_plain_arabic: _m35_clinic_rx(from) };
  // Each workflow owner's KPIs (W1-W5), in that order. lower_is_better: the actual must be at or below the target.
  const kpis = [
    { key: 'patients_logging_weekly', owner: 'W1', lens: 'outcomes', baseline: 35, target: 70, unit: '%', actual: pct(logging, patients.length), n: patients.length },
    { key: 'medicines_taken', owner: 'W1', lens: 'outcomes', baseline: null, target: 80, unit: '% (7 days)', actual: adh.length ? round(adh.reduce((s, x) => s + x, 0) / adh.length, 0) : null, n: adh.length },
    { key: 'answers_with_sources', owner: 'W2', lens: 'outcomes', baseline: null, target: 80, unit: '%', actual: pct(cited, written.length), n: written.length },
    { key: 'judge_safety_avg', owner: 'W2', lens: 'outcomes', baseline: null, target: 4.5, unit: 'average (1-5)', actual: mean('safety'), n: judgedSafety },
    { key: 'brief_ready_before_visit', owner: 'W3', lens: 'cost', baseline: 0, target: 90, unit: '%', actual: pct(briefed, appts.length), n: appts.length },
    { key: 'clinic_rx_plain_arabic', owner: 'W3', lens: 'outcomes', baseline: null, target: 80, unit: '%', ...cl.rx_plain_arabic },
    { key: 'clinic_referrals_kept', owner: 'W3', lens: 'cost', baseline: null, target: 70, unit: '%', ...cl.referrals_kept,
      baseline_note: 'about 50% completed (US study); 68.4% of Egyptian specialist-clinic patients followed up elsewhere (Egypt Heart J 2022)', target_note: 'team target' },
    { key: 'clinic_no_show_rate', owner: 'W4', lens: 'cost', baseline: 22, target: 17, unit: '%', ...cl.no_show_rate, lower_is_better: true,
      baseline_note: 'estimate: regional and global studies, about 21-23%; measure the real rate in the pilot' },
    { key: 'clinic_minutes_to_decision', owner: 'W4', lens: 'workforce', baseline: null, target: 30, unit: 'min (median)', ...cl.minutes_to_decision, lower_is_better: true, target_note: 'team target' },
    { key: 'clinic_waitlist_recoveries', owner: 'W4', lens: 'cost', baseline: 0, target: 1, unit: 'slots (count)', ...cl.waitlist_recoveries, target_note: 'more than 0' },
    { key: 'red_flags_routed', owner: 'W5', lens: 'outcomes', baseline: 0, target: 100, unit: '%', actual: pct(routed.filter((l) => l.action === 'companion.routed').length, routed.length), n: routed.length, self_care: selfCare },
    { key: 'urgent_ack_minutes', owner: 'W5', lens: 'workforce', baseline: null, target: 60, unit: 'min (median)', actual: med(ackMin), n: ackMin.length, lower_is_better: true },
  ].map((k) => ({ baseline_note: null, ...k, lower_is_better: k.lower_is_better === true, owner_name: _M35_OWNERS[k.owner],
    met: k.actual === null || k.actual === undefined ? null : k.lower_is_better ? k.actual <= k.target : k.actual >= k.target }));
  const runs = dbWhere('ai_runs', (r) => t(r.created_at) > from);
  const lat = companion.map((r) => r.latency_ms).filter((v) => v !== null);
  const byWorkflow = {};
  for (const r of runs) {
    const w = fn_logical_workflow(r.workflow);
    byWorkflow[w] = byWorkflow[w] || { runs: 0, failed: 0 };
    byWorkflow[w].runs++;
    if (r.status === 'FAILED') byWorkflow[w].failed++;
  }
  for (const j of dbWhere('job_runs', (x) => t(x.at) > from)) {
    const w = fn_logical_workflow(j.job);
    byWorkflow[w] = byWorkflow[w] || { runs: 0, failed: 0 };
    byWorkflow[w].runs++;
  }
  return {
    days, kpis,
    judge: { judged: trials.length, pass_rate: pct(trials.filter((x) => x.verdict === 'pass').length, trials.length),
      scores: Object.fromEntries(_M35_DIMS.map((k) => [k, mean(k)])), low_safety: trials.filter((x) => castNum(x.safety) <= 2).length },
    failed_runs: { ai: runs.filter((r) => r.status === 'FAILED').length, total: runs.length, rate: pct(runs.filter((r) => r.status === 'FAILED').length, runs.length),
      workflow_errors: dbCount('incidents', (x) => t(x.at) > from && (x.kind === null || x.kind === 'workflow_error')) },
    response_time_ms: { companion_p50: lat.length ? round(percentileCont(lat, 0.5), 0) : null, companion_p90: lat.length ? round(percentileCont(lat, 0.9), 0) : null, n: lat.length },
    escalations: { total: urgent.length, critical: urgent.filter((i) => i.urgency === 'critical').length,
      by_category: urgent.reduce((m, i) => { m[i.category] = (m[i.category] || 0) + 1; return m; }, {}) },
    reviews: { pending: dbCount('ai_reviews', (r) => r.status === 'pending'), overdue: dbCount('ai_reviews', (r) => r.status === 'pending' && t(r.due_at) < nowMs()),
      decided: dbCount('ai_reviews', (r) => r.status !== 'pending' && t(r.created_at) > from) },
    by_workflow: byWorkflow,
    alerts: { companion_paused: fn_companion_paused(), rules: _m35_cfg(),
      recent: orderBy(dbWhere('incidents', (x) => /alert/.test(String(x.node || ''))), [(x) => t(x.at), 'desc']).slice(0, 10)
        .map((x) => ({ id: x.id, at: x.at, node: x.node, severity: x.severity, status: x.status, message: x.message })) },
    calibration: fn_calibration_report(),
  };
}

/* ------------------------------------------------------------------------------------- Tracing (Langfuse) */


/** Finished AI runs and job runs not yet sent, as metadata only (no text, no patient or user id). */
function fn_trace_batch(p_limit) {
  const limit = Math.max(1, Math.min(castInt(p_limit) ?? 50, 100));
  const since = nowMs() - 7 * DAY;
  const runs = orderBy(dbWhere('ai_runs', (r) => r.traced_at === null && r.completed_at !== null && t(r.created_at) > since), (r) => t(r.created_at)).slice(0, limit);
  const out = runs.map((r) => {
    const g = r.guard && typeof r.guard === 'object' ? r.guard : {};
    const v = r.verifier && typeof r.verifier === 'object' ? r.verifier : {};
    const tr = dbOne('ai_trials', (x) => x.ai_run_id === r.id);
    const judge = tr ? Object.fromEntries(_M35_DIMS.concat(['verdict']).map((k) => [k, tr[k]])) : null;
    return {
      kind: 'ai_run', id: r.id, name: String(r.workflow || 'AI run'), start: r.created_at, end: r.completed_at,
      error: r.status === 'FAILED' ? String(r.error || 'failed').slice(0, 200) : null,
      inputs: { workflow: r.workflow, prompt_version: r.prompt_version },
      outputs: { status: r.status, release: g.release || null, risk: Array.isArray(g.risk) ? g.risk : [], verifier_approved: v.approved ?? null,
        verifier_categories: Array.isArray(v.categories) ? v.categories : [],
        judge },
      metadata: { logical_workflow: fn_logical_workflow(r.workflow), model: r.model, latency_ms: r.latency_ms, prompt_version: r.prompt_version },
      tags: [fn_logical_workflow(r.workflow).slice(0, 2), r.status, r.model].filter(Boolean),
    };
  });
  const jobs = orderBy(dbWhere('job_runs', (j) => j.traced_at === null && j.job !== 'tracing' && t(j.at) > since), (j) => t(j.at)).slice(0, Math.max(0, limit - out.length));
  for (const j of jobs) {
    out.push({ kind: 'job', id: j.id, name: `job: ${j.job}`, start: j.at, end: j.at, error: null,
      inputs: { job: j.job }, outputs: j.result && typeof j.result === 'object' ? j.result : { result: j.result },
      metadata: { logical_workflow: fn_logical_workflow(j.job) }, tags: [fn_logical_workflow(j.job).slice(0, 2), 'job'] });
  }
  // Judge scores that arrived after their run was traced (the judge runs every 10 min, tracing every 2): sent as
  // scores on the run's existing trace.
  const trials = orderBy(dbWhere('ai_trials', (x) => x.traced_at === null && t(x.judged_at) > since && x.ai_run_id !== null && x.safety !== null), (x) => t(x.judged_at))
    .filter((x) => { const r = dbGet('ai_runs', x.ai_run_id); return r && r.traced_at !== null; })
    .slice(0, Math.max(0, limit - out.length));
  for (const x of trials) {
    out.push({ kind: 'trial', id: x.id, trace_id: x.ai_run_id, name: 'judge scores', start: x.judged_at, end: x.judged_at, error: null,
      outputs: { judge: Object.fromEntries(_M35_DIMS.concat(['verdict']).map((k) => [k, x[k]])) }, tags: [] });
  }
  return out;
}

/** p_ids: [{ kind: 'ai_run' | 'job' | 'trial', id }] that Langfuse accepted. */
function fn_trace_mark(p_ids) {
  let n = 0;
  for (const x of Array.isArray(p_ids) ? p_ids : []) {
    if (x && x.kind === 'job') { const j = dbGet('job_runs', castInt(jtext(x.id))); if (j) { dbUpdate('job_runs', j, { traced_at: now() }); n++; } }
    else if (x && x.kind === 'trial') { const tr = dbGet('ai_trials', castUuid(jtext(x.id))); if (tr) { dbUpdate('ai_trials', tr, { traced_at: now() }); n++; } }
    else if (x) {
      const r = dbGet('ai_runs', castUuid(jtext(x.id)));
      if (r) {
        dbUpdate('ai_runs', r, { traced_at: now() }); n++;
        // A run judged before it was traced carried its scores in the trace.
        const tr = dbOne('ai_trials', (y) => y.ai_run_id === r.id && y.traced_at === null);
        if (tr) dbUpdate('ai_trials', tr, { traced_at: now() });
      }
    }
  }
  return { marked: n };
}

// ---- 36_reviews.js
/* 36 · Nurse approval of Companion answers ("AI drafts, a clinician decides").
 *
 * A model answer that carries a higher-risk signal (a medicine named, a symptom described, MedGemma consulted, a
 * reassuring answer to a symptom) is held for a person to approve when the patient has a care team. The patient gets an
 * immediate holding reply ("your question was sent to your care team"), never silence; the draft goes to the review
 * queue. Emergencies, dose refusals and blocked messages are fixed replies and are never held.
 *
 *   fn_review_hold(...)          called by api_companion_store: holds the draft or returns null.
 *   api_ai_reviews(c, d)         the clinician's queue (pending first, overdue marked).
 *   api_ai_review_decide(c, d)   approve (the draft is shown), edit (the clinician's text is shown) or reject (a short
 *                                note or "your care team will contact you" is shown). The patient is notified.
 *   fn_run_review_escalations()  part of the reminders job: a review not decided within review_hours becomes a high
 *                                inbox item.
 * Settings: rule companion_review (enabled, hold_signals, review_hours).
 */

const _R36 = { enabled: true, hold_signals: ['medicine_named', 'symptom_described', 'medgemma_consulted', 'reassurance'], review_hours: 4 };
const _R36_HOLD = {
  en: 'Your question has been sent to your care team. A nurse will check the answer before you see it, usually within {h} hours. If you feel unwell now, use Need Care or call 123.',
  ar: 'سؤالك اتبعت لفريق الرعاية. ممرض/ة هيراجع الإجابة قبل ما توصلك، غالبًا خلال {h} ساعات. لو حاسس إنك تعبان دلوقتي استخدم "أحتاج رعاية" أو اتصل بـ 123.',
};

function _r36_cfg() { return { ..._R36, ...(coalesce(fn_rule('companion_review'), {})) }; }

/** Holds a Companion model answer for review, or returns null. p_reply is what the agent produced. */
function fn_review_hold(p_patient_id, p_message_id, p_conversation_id, p_run_id, p_question, p_reply, p_guard, p_status) {
  const cfg = _r36_cfg();
  if (!cfg.enabled || p_status !== 'COMPLETED' || !p_reply || p_reply.source !== 'model' || p_reply.emergency || p_reply.urgent || p_reply.blocked) return null;
  if (p_guard && (p_guard.dose_change_request || (Array.isArray(p_guard.dose_violations) && p_guard.dose_violations.length))) return null;
  const risk = p_guard && Array.isArray(p_guard.risk) ? p_guard.risk : [];
  const signals = risk.filter((x) => (cfg.hold_signals || []).includes(x));
  if (!signals.length) return null;
  if (!dbExists('care_team', (ct) => ct.patient_id === p_patient_id && ct.active === true)) return null;
  const h = coalesce(castInt(cfg.review_hours), 4);
  const row = dbInsert('ai_reviews', {
    ai_run_id: castUuid(p_run_id), message_id: p_message_id, conversation_id: castUuid(p_conversation_id), patient_id: p_patient_id,
    question: left(p_question, 1000), draft: String(p_reply.content || ''), draft_meta: omit(p_reply, 'content'), signals,
    due_at: iso(nowMs() + h * HOUR),
  });
  fn_create_inbox_item(p_patient_id, 'ai_review', 'medium', 3, 'AI answer waiting for approval',
    `Signals: ${signals.join(', ')}. Approve, edit or reject the Companion's draft within ${h} hours.`,
    { type: 'ai_review', review_id: row.id, ai_run_id: p_run_id }, `ai-review:${row.id}`);
  const ar = p_reply.language === 'ar';
  return { review_id: row.id, content: (ar ? _R36_HOLD.ar : _R36_HOLD.en).split('{h}').join(String(h)), signals, due_at: row.due_at };
}

function _r36_json(r) {
  const p = dbGet('patients', r.patient_id);
  return { id: r.id, patient_id: r.patient_id, patient_name: p ? p.full_name : null, patient_name_ar: p ? p.full_name_ar : null, mrn: p ? p.mrn : null,
    question: r.question, draft: r.draft, citations: (r.draft_meta && r.draft_meta.citations) || [], signals: r.signals, status: r.status,
    final_content: r.final_content, note: r.note, created_at: r.created_at, due_at: r.due_at, decided_at: r.decided_at,
    overdue: r.status === 'pending' && t(r.due_at) < nowMs() };
}

function api_ai_reviews(c, d) {
  const role = jtext(c && c.role);
  if (!['doctor', 'nurse', 'clinic_admin'].includes(role)) fn_raise('forbidden: Only the care team can see this.');
  const pid = d && d.patient_id ? castUuid(jtext(d.patient_id)) : null;
  const rows = dbWhere('ai_reviews', (r) => (pid === null || r.patient_id === pid) && fn_can_access_patient(c, r.patient_id)
    && (r.status === 'pending' || t(r.created_at) > nowMs() - 14 * DAY));
  return orderBy(rows, [(r) => (r.status === 'pending' ? 0 : 1)], [(r) => t(r.due_at)]).slice(0, 100).map(_r36_json);
}

function api_ai_review_decide(c, d) {
  const role = jtext(c && c.role);
  if (!['doctor', 'nurse'].includes(role)) fn_raise('forbidden: Only a doctor or nurse can approve an answer.');
  const r = dbGet('ai_reviews', castUuid(jtext(d && d.review_id)));
  if (!r || !fn_can_access_patient(c, r.patient_id)) fn_raise('not_found: review not found');
  if (r.status !== 'pending') fn_raise('conflict: this answer was already reviewed');
  const decision = String((d && d.decision) || '');
  if (!['approve', 'edit', 'reject'].includes(decision)) fn_raise('bad_request: decision must be approve, edit or reject');
  const note = String((d && d.note) || '').trim().slice(0, 1000) || null;
  const ar = r.draft_meta && r.draft_meta.language === 'ar';
  let final;
  if (decision === 'approve') final = r.draft;
  else if (decision === 'edit') {
    final = String((d && d.content) || '').trim().slice(0, 2000);
    if (final.length < 5) fn_raise('bad_request: write the answer the patient will see');
  } else {
    final = note ? (ar ? `رد فريق الرعاية: ${note}` : `Your care team replied: ${note}`)
      : (ar ? 'فريق الرعاية هيتواصل معاك بخصوص سؤالك.' : 'Your care team will contact you about this question.');
  }
  const status = decision === 'approve' ? 'approved' : decision === 'edit' ? 'edited' : 'rejected';
  dbUpdate('ai_reviews', r, { status, final_content: final, note, decided_at: now(), decided_by: castUuid(jtext(c.user_id)) });
  const msg = dbGet('messages', r.message_id);
  if (msg) {
    const meta = { ...(msg.meta && typeof msg.meta === 'object' ? msg.meta : {}), held: false, reviewed: status, reviewed_by_role: role };
    if (decision !== 'approve') meta.citations = decision === 'edit' ? (meta.citations || []) : [];
    dbUpdate('messages', msg, { content: final, meta });
  }
  dbUpdateWhere('inbox_items', (i) => i.dedupe_key === `ai-review:${r.id}` || i.dedupe_key === `ai-review-overdue:${r.id}`, { status: 'RESOLVED', resolved_by: castUuid(jtext(c.user_id)), updated_at: now() });
  fn_notify_patient(r.patient_id, 'companion_reviewed', 'Your care team answered your question', 'Open the AI helper to read it.',
    `companion-reviewed:${r.id}`, 'فريق الرعاية رد على سؤالك', 'افتح المساعد الذكي لقراءة الرد.');
  fn_audit(c, `ai_review.${status}`, 'ai_review', r.id, r.patient_id);
  return _r36_json(r);
}

function fn_run_review_escalations() {
  let n = 0;
  for (const r of dbWhere('ai_reviews', (x) => x.status === 'pending' && x.escalated_at === null && t(x.due_at) < nowMs())) {
    fn_create_inbox_item(r.patient_id, 'ai_review', 'high', 2, 'Overdue: AI answer still waiting for approval',
      'A patient is waiting for an answer that needs a nurse to approve it. Please review it now.', { type: 'ai_review', review_id: r.id }, `ai-review-overdue:${r.id}`);
    dbUpdate('ai_reviews', r, { escalated_at: now() });
    n++;
  }
  return { review_escalations: n };
}

// ---- 37_pages.js
// Page actions: everything one screen shows, in one API request. n8n runs one execution at a time on its main thread,
// so a screen that fired 5-10 requests waited for them in a queue; one page request answers in the time of one.
// Each part is the existing route function (30_api_routes.js), called only if the caller could call that action on its
// own: the same roles and family-member scopes as the Auth Gate (fn_gate), read from the api_routes table. A part that
// is refused or fails is { error: code } and the others are still answered; the web app then asks for that part alone.

/** null when ctx may call group.action with data; otherwise the error code the Auth Gate would give. */
function _p37_refused(c, group, action, data) {
  const row = dbOne('api_routes', (r) => r.grp === group);
  const routes = row && row.routes && typeof row.routes === 'object' ? row.routes : {};
  if (!Object.prototype.hasOwnProperty.call(routes, action)) return 'unknown_action';
  const route = routes[action] || {};
  const roles = Object.prototype.hasOwnProperty.call(route, 'roles') ? route.roles : undefined;
  const role = jtext(c && c.role);
  if (roles === undefined || roles === null || (roles !== '*' && _m10_hasKey(roles, role) !== true)) return 'forbidden';
  if (route.scope) {
    try { fn_scope_ctx(c, data, route.scope); } catch (e) { if (!_m10_isRaise(e)) throw e; return 'forbidden'; }
  }
  return null;
}

/** One part of a page: the route's answer, or { error } when refused or when it raises (other errors propagate). */
function _p37_part(c, group, action, fn, data) {
  const refused = _p37_refused(c, group, action, data);
  if (refused) return { error: refused };
  try {
    return fn(c, data);
  } catch (e) {
    if (!_m10_isRaise(e)) throw e;
    return { error: String(e.message).split(':')[0] };
  }
}

/** The patient's id-carrying input for the parts (a family member names the patient; a patient may omit it). */
function _p37_scope(d) { return d && d.patient_id ? { patient_id: d.patient_id } : {}; }

// Today: the day's payload, the notifications shown in its notices and in the bell, and the last day's readings.
function api_page_today(c, d) {
  fn_resolve_patient(c, d);
  const s = _p37_scope(d);
  return {
    today: _p37_part(c, 'today', 'get', api_route_today_get, s),
    notifications: _p37_part(c, 'insights', 'notifications', api_route_insights_notifications, {}),
    // The last day's readings: the trend arrow next to the latest sensor value.
    recent: _p37_part(c, 'glucose', 'list', api_route_glucose_list, { ...s, days: 1 }),
  };
}

// Blood sugar: summary, readings and patterns for the chosen days; the charts' data when asked for (charts: true).
function api_page_glucose(c, d) {
  fn_resolve_patient(c, d);
  const s = { ..._p37_scope(d), days: fn_clamp(jtext(d && d.days), 14, 1, 90) };
  const out = {
    metrics: _p37_part(c, 'glucose', 'metrics', api_route_glucose_metrics, s),
    list: _p37_part(c, 'glucose', 'list', api_route_glucose_list, s),
    patterns: _p37_part(c, 'glucose', 'patterns', api_route_glucose_patterns, s),
    nightscout: _p37_part(c, 'glucose', 'nightscout_status', api_route_glucose_nightscout_status, _p37_scope(d)),
  };
  if (d && d.charts === true) {
    out.agp = _p37_part(c, 'glucose', 'agp', api_route_glucose_agp, s);
    out.daily = _p37_part(c, 'glucose', 'daily', api_route_glucose_daily, s);
  }
  return out;
}

// My care: care team, plan, check-ups, appointments, care requests, referrals, messages and family members.
function api_page_care(c, d) {
  fn_resolve_patient(c, d);
  const s = _p37_scope(d);
  return {
    profile: _p37_part(c, 'profile', 'get', api_route_profile_get, s),
    plan: _p37_part(c, 'care', 'plan', api_route_care_plan, s),
    screenings: _p37_part(c, 'care', 'screenings', api_route_care_screenings, s),
    appointments: _p37_part(c, 'care', 'appointments', api_route_care_appointments, s),
    episodes: _p37_part(c, 'episodes', 'list', api_route_episodes_list, s),
    referrals: _p37_part(c, 'network', 'referrals', api_route_network_referrals, s),
    messages: _p37_part(c, 'care', 'messages', api_route_care_messages, s),
    caregivers: _p37_part(c, 'care', 'caregivers', api_route_care_caregivers, {}),
    my_doctor: _p37_part(c, 'care', 'my_doctor', api_route_care_my_doctor, s),
  };
}

// Food and activity: the week's summary and the person's food responses.
function api_page_lifestyle(c, d) {
  fn_resolve_patient(c, d);
  const s = _p37_scope(d);
  return {
    summary: _p37_part(c, 'lifestyle', 'summary', api_route_lifestyle_summary, { ...s, days: 7 }),
    food_profile: _p37_part(c, 'lifestyle', 'food_profile', api_route_lifestyle_food_profile, { ...s, days: 90 }),
  };
}

// Clinician home: the inbox (active items), join requests, held AI answers, the header counts and notifications.
function api_page_provider_home(c, d) {
  return {
    inbox: _p37_part(c, 'provider', 'inbox', api_route_provider_inbox, { status: 'active' }),
    link_requests: _p37_part(c, 'provider', 'link_requests', api_route_provider_link_requests, {}),
    ai_reviews: _p37_part(c, 'provider', 'ai_reviews', api_route_provider_ai_reviews, {}),
    stats: _p37_part(c, 'provider', 'stats', api_route_provider_stats, {}),
    notifications: _p37_part(c, 'insights', 'notifications', api_route_insights_notifications, {}),
  };
}

// ---- 40_clinic.js
// Polyclinic (the specialist clinics beyond the diabetes team; from the MediCare AI system, rebuilt here on the
// platform's records, roles and safety rules). One patient record serves diabetes care and every specialty.
//
//   Booking:   a patient (or family member) describes the problem -> the emergency pre-screen runs first (fixed text,
//              critical inbox item) -> otherwise a booking request waits for AI triage (WF-040, background) -> reception
//              accepts, proposes other times, reassigns or declines -> the patient is told in the app (no third-party
//              messaging). Accepting books an appointment, links the patient to the polyclinic and starts the visit-prep
//              note (WF-041, for the patient) and the pre-visit brief (WF-042, for the doctor).
//   Waitlist:  a cancelled slot is offered to the first person waiting for that specialty; they accept or decline in the
//              app within clinic_policy.waitlist_offer_minutes.
//   Visit:     the doctor writes the diagnosis and prescription (AI hints on request are doctor-only drafts, WF-044), adds
//              services (invoice), a follow-up date and an internal referral (booked into the first free slot of that
//              specialty), and signs. Only then is the patient told: the prescription rewritten in plain Arabic with every
//              number checked (WF-043), or the doctor's exact words.
//   AI never decides: triage is a suggestion reception accepts or changes; diagnosis and prescription are the doctor's.
//   Escalation: a request reception has not decided in time (clinic_policy.escalate_*: urgent 60 minutes, priority 4 hours,
//              routine 24 hours) is raised once to the polyclinic's clinic admins, and the patient is told it is still
//              waiting (fn_run_clinic_escalations, from the 15-minute reminders job).
// Roles: reception = receptionist, clinic_admin (and nurse); doctor = doctor; catalog = clinic_admin, platform_admin.

const _M40_RECEPTION = ['receptionist', 'clinic_admin', 'nurse', 'doctor'];
const _M40_ADMIN = ['clinic_admin', 'platform_admin'];
const _M40_URG = { urgent: 0, priority: 1, routine: 2 };

function _m40_txt(o, k) { return o === null || o === undefined || o[k] === null || o[k] === undefined ? null : String(o[k]); }
function _m40_uid(c) { return castUuid(_m40_txt(c, 'user_id')); }
function _m40_role(c) { return _m40_txt(c, 'role'); }

/** clinic_policy rule with defaults. */
function fn_clinic_policy() {
  return {
    triage_min_confidence: 0.6, waitlist_offer_minutes: 15, booking_days_ahead: 14, max_offer_slots: 3,
    rx_numbers_must_match: true, escalate_urgent_minutes: 60, escalate_priority_hours: 4, escalate_routine_hours: 24,
    ...(coalesce(fn_rule('clinic_policy'), {}) || {}),
  };
}

/** The polyclinic organization: the first organization of type polyclinic. */
function fn_clinic_org() {
  const o = orderBy(dbWhere('organizations', (x) => x.type === 'polyclinic'), [(x) => t(x.created_at), 'asc'])[0];
  return o ? o.id : null;
}

/** Staff of the polyclinic: a member of its organization (or a platform admin for the catalog). */
function fn_clinic_staff(c, roles) {
  fn_require_role(c, roles);
  if (_m40_role(c) === 'platform_admin') return;
  const org = fn_clinic_org();
  const uid = _m40_uid(c);
  if (org === null || !dbExists('memberships', (m) => m.user_id === uid && m.organization_id === org)) fn_raise('forbidden: this action is for the polyclinic staff');
}

/** A booking links the patient to the polyclinic through that doctor (care_team needs a user), which gives the
 *  polyclinic staff (members of its organization) access to the record. */
function fn_clinic_link_patient(pid, userId) {
  const org = fn_clinic_org();
  const uid = castUuid(userId);
  if (org === null || uid === null || dbExists('care_team', (x) => x.patient_id === pid && x.organization_id === org && x.active === true)) return;
  const ex = dbOne('care_team', (x) => x.patient_id === pid && x.user_id === uid);
  if (ex) dbUpdate('care_team', ex, { organization_id: ex.organization_id || org, active: true });
  else dbInsert('care_team', { patient_id: pid, user_id: uid, organization_id: org, role: 'specialist_clinic', active: true });
}

function _m40_age(p) {
  if (!p || !p.date_of_birth) return null;
  const a = fn_age(p.date_of_birth);
  return a === null || a < 0 ? null : a;
}
/** What reception sees of a patient: administrative fields only. */
function _m40_patient_admin(pid) {
  const p = dbGet('patients', pid);
  return p ? { id: p.id, full_name: p.full_name, full_name_ar: p.full_name_ar, mrn: p.mrn, phone: p.phone, age: _m40_age(p), sex: p.sex } : null;
}
function _m40_spec(code) {
  const s = code === null || code === undefined ? null : dbGet('clinic_specialties', String(code));
  return s ? { code: s.code, name: s.name, name_ar: s.name_ar } : null;
}
function _m40_doctor(uid) {
  const u = uid === null || uid === undefined ? null : dbGet('users', uid);
  const p = uid === null || uid === undefined ? null : dbGet('doctor_profiles', uid);
  return u ? { user_id: u.id, full_name: u.full_name, full_name_ar: u.full_name_ar, specialty: p ? p.specialty : null, fee_egp: p ? Number(p.fee_egp) : null } : null;
}

/* ------------------------------------------------------------------------------------------------ availability */

/** Start times (ms) of a doctor's daily slots on a Cairo date. */
function _m40_slots_on(prof, date) {
  const [y, mo, d] = String(date).split('-').map(Number);
  return (prof.daily_slots || []).map((hhmm) => String(hhmm).trim()).filter((x) => /^\d{1,2}:\d{2}$/.test(x))
    .map((x) => cairoLocalToMs(y, mo, d, Number(x.split(':')[0]), Number(x.split(':')[1]))).sort((a, b) => a - b);
}
/** Is the doctor free at this time? Every appointment that is not cancelled holds its slot, also one completed early
 *  (a visit signed before its booked time still used that time). */
function fn_clinic_doctor_free(uid, startMs, minutes = 20, exceptAppointmentId = null) {
  const end = startMs + minutes * MIN;
  return !dbExists('appointments', (x) => x.provider_user_id === uid && x.id !== exceptAppointmentId && x.status !== 'cancelled'
    && t(x.starts_at) < end && (x.ends_at !== null ? t(x.ends_at) : t(x.starts_at) + 20 * MIN) > startMs);
}
/** The next free slots of a doctor (ISO), from now, within booking_days_ahead days. */
function fn_clinic_free_slots(uid, limit = 6) {
  const prof = dbGet('doctor_profiles', uid);
  if (!prof || prof.active !== true) return [];
  const pol = fn_clinic_policy();
  const out = [];
  for (let i = 0; i < Number(pol.booking_days_ahead) && out.length < limit; i++) {
    const date = localDate(iso(nowMs() + i * DAY));
    for (const s of _m40_slots_on(prof, date)) {
      if (s >= nowMs() + 30 * MIN && fn_clinic_doctor_free(uid, s, prof.slot_minutes)) out.push(iso(s));
      if (out.length >= limit) break;
    }
  }
  return out;
}
/** The doctor of a specialty with the earliest free slot: { doctor, slot } or nulls. */
function fn_clinic_pick_doctor(specialty) {
  let best = { doctor_user_id: null, slot: null };
  for (const p of dbWhere('doctor_profiles', (x) => x.specialty === specialty && x.active === true)) {
    const s = fn_clinic_free_slots(p.user_id, 1)[0];
    if (s && (best.slot === null || t(s) < t(best.slot))) best = { doctor_user_id: p.user_id, slot: s };
  }
  if (best.doctor_user_id === null) {
    const any = dbWhere('doctor_profiles', (x) => x.specialty === specialty && x.active === true)[0];
    if (any) best.doctor_user_id = any.user_id;
  }
  return best;
}

/* ----------------------------------------------------------------------------------------------- booking (patient) */

// A patient or family member asks for a specialist visit in their own words. Emergencies get the fixed emergency text
// at once (and a critical inbox item for the patient's care team); everything else waits for triage and reception.
function api_clinic_request(c, d) {
  const pid = fn_resolve_patient(c, d);
  fn_require_scope(c, pid, 'log');
  const msg = left(String(coalesce(_m40_txt(d, 'message'), '')).trim(), 2000);
  if (msg.length < 3) fn_raise('bad_request: Please describe the problem in a few words. ¦ من فضلك اكتب المشكلة في كلمات قليلة.');
  const open = dbCount('booking_requests', (x) => x.patient_id === pid && ['triaging', 'pending', 'offered', 'escalated'].includes(x.status));
  if (open >= 3) fn_raise('conflict: You already have requests waiting for the clinic. ¦ لديك طلبات بالفعل في انتظار العيادة.');
  const em = fn_prescreen_for(c, pid, msg);
  const emergency = !!(em && em.emergency === true);
  const sameDay = !!(em && em.urgent === true);
  const r = dbInsert('booking_requests', {
    organization_id: fn_clinic_org(), patient_id: pid, source: coalesce(_m40_txt(d, 'source'), 'app') === 'referral' ? 'referral' : 'app', message: msg,
    urgency: emergency || sameDay ? 'urgent' : 'routine', status: emergency ? 'escalated' : 'triaging',
    triage: emergency ? { cc: msg.slice(0, 160), why: 'Emergency signs in the message (rules, not AI): fixed emergency text shown.', red_flags: em.matched || [], ai: 'rules' } : null,
  });
  if (emergency) {
    fn_create_inbox_item(pid, 'safety', 'critical', 1, 'Emergency signs in a clinic booking request', left(msg, 300), { booking_request_id: r.id, matched: em.matched || [] });
  } else {
    fn_emit('ClinicBookingRequested', pid, String(r.id), {});
  }
  fn_audit(c, 'clinic.request', 'booking_request', String(r.id), pid, { emergency });
  return {
    request_id: r.id, status: r.status, emergency, same_day: sameDay,
    message_en: emergency || sameDay ? em.message_en : 'Your request was sent to the clinic. Reception will offer you an appointment soon. If you get severe chest pain, breathlessness or you faint, call 123 now.',
    message_ar: emergency || sameDay ? em.message_ar : 'تم إرسال طلبك إلى العيادة، وسيعرض عليك الاستقبال موعدًا قريبًا. إذا شعرت بألم شديد في الصدر أو ضيق في التنفس أو إغماء فاتصل بـ 123 فورًا.',
  };
}

function _m40_request_json(r, view) {
  const tri = r.triage || {};
  const base = {
    id: r.id, status: r.status, source: r.source, urgency: r.urgency, created_at: r.created_at, decided_at: r.decided_at,
    specialty: _m40_spec(r.specialty), doctor: _m40_doctor(r.doctor_user_id), proposed_at: r.proposed_at,
