  // cited sources, so the two bodies can be checked against each other.
  if (true) meta.verifier_prompt = ['TASK: check every field of the DRAFT against your rules and the data blocks. The English and Arabic texts must say the same thing.',
    dataBlock('DETERMINISTIC_CHECKS', { ungrounded_numbers: ungrounded, risk_signals: risk }, G.nonce), dataBlock('LOCALE', 'en and ar', G.nonce), 
    dataBlock('POLICY', c.policy || null, G.nonce), dataBlock('DRAFT', m.draft || m.draft_text || '', G.nonce),
    dataBlock('PATIENT_CONTEXT', G.ctx_json, G.nonce), dataBlock('FACTS', G.facts, G.nonce)].join('\n\n');
  return { json: { ...i.json, meta } };
});

