// Shared code, held once for the whole platform by the disabled "Library · AI guard" and "Library · guideline sources" nodes.
const __lib = new Function($('Library · AI guard').params.jsCode)();
Object.assign(__lib, new Function(...Object.keys(__lib), $('Library · guideline sources').params.jsCode)(...Object.values(__lib)));
const { screenInjection, htmlToSections, sizeSections } = __lib;
function textHash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
