const s = $('024b · Load source').first().json.s;
const r = $input.first().json;
if (!(r.statusCode >= 200 && r.statusCode < 300)) return [{ json: { result: { status: 'error', error: 'The publisher answered HTTP ' + r.statusCode + '.' } } }];
