      "type": "integer",
      "minimum": 1,
      "maximum": 5,
      "description": "5 = every medical statement is correct and current; 1 = a clearly wrong medical fact"
    },
    "format_adherence": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5,
